// POST /api/providers/import — create multiple provider connections from a parsed
// CSV/JSON file, where each row/entry may target a DIFFERENT provider (#6836).
// Partial-failure semantics identical to /api/providers/bulk: every entry succeeds or
// fails independently and the response always returns 200 with per-entry results.
export async function POST(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  const auditContext = getAuditRequestContext(request);

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const validation = validateBody(bulkImportProviderSchema, body);
  if (isValidationFailure(validation)) {
    return NextResponse.json({ error: validation.error }, { status: 400 });
  }

  const { entries, validateKeys } = validation.data;
  const resolvedEntries = await resolveImportNameCollisions(entries);

  const created: Array<Record<string, unknown>> = [];
  const errors: Array<{ index: number; name: string; provider: string; message: string }> = [];

  for (let i = 0; i < resolvedEntries.length; i++) {
    const entry = resolvedEntries[i];
    try {
      const result = await importOneEntry(entry, !!validateKeys);
      if ("error" in result) {
        errors.push({ index: i, name: entry.name, provider: entry.provider, message: result.error });
        continue;
      }
      created.push(result.created);
      logAuditEvent({
        action: "provider.credentials.created",
        actor: "admin",
        target: getProviderAuditTarget(result.created),
        resourceType: "provider_credentials",
        status: "success",
        ipAddress: auditContext.ipAddress || undefined,
        requestId: auditContext.requestId,
        metadata: {
          provider: entry.provider,
          via: "import",
          connection: summarizeProviderConnectionForAudit(result.created),
        },
      });
    } catch (err) {
      errors.push({
        index: i,
        name: entry.name,
        provider: entry.provider,
        message: sanitizeErrorMessage(err) || "Failed to create connection",
      });
    }
  }

  if (created.length > 0) {
    await syncToCloudIfEnabled();
  }

  logAuditEvent({
    action: "provider.credentials.bulk_created",
    actor: "admin",
    resourceType: "provider_credentials",
    status: errors.length === entries.length ? "failure" : "success",
    ipAddress: auditContext.ipAddress || undefined,
    requestId: auditContext.requestId,
    metadata: {
      via: "import",
      total: entries.length,
      success: created.length,
      failed: errors.length,
    },
  });

  return NextResponse.json(
    {
      success: created.length,
      failed: errors.length,
      total: entries.length,
      created,
      errors,
    },
    { status: 200 }
  );
}

import { NextResponse } from "next/server";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";
import { getAuditRequestContext, logAuditEvent } from "@/lib/compliance/index";
import { getProviderNodeById } from "@/models";
import {
  isClaudeCodeCompatibleProvider,
  isOpenAICompatibleProvider,
  isAnthropicCompatibleProvider,
} from "@/shared/constants/providers";
import { validateProviderApiKey } from "@/lib/providers/validation";
import { getProxyForLevel } from "@/lib/db/settings"
import { resolveProxyForProvider } from "@/lib/localDb";
import { validateProviderApiKeySchema } from "@/shared/validation/schemas";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";
import { runWithProxyContextOrDirect } from "@omniroute/open-sse/utils/proxyFetch.ts";

function sanitizeAuditUrl(url: string | null | undefined) {
  if (!url) return null;
  try {
    const parsed = new URL(url);
    return `${parsed.origin}${parsed.pathname}`.replace(/\/$/, "") || parsed.origin;
  } catch {
    return String(url);
  }
}

// POST /api/providers/validate - Validate API key with provider
export async function POST(request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  const auditContext = getAuditRequestContext(request);
  let rawBody;
  try {
    rawBody = await request.json();
  } catch {
    return NextResponse.json(
      {
        error: {
          message: "Invalid request",
          details: [{ field: "body", message: "Invalid JSON body" }],
        },
      },
      { status: 400 }
    );
  }

  try {
    const validation = validateBody(validateProviderApiKeySchema, rawBody);
    if (isValidationFailure(validation)) {
      return NextResponse.json({ error: validation.error }, { status: 400 });
    }
    const {
      provider,
      apiKey,
      validationModelId,
      customUserAgent,
      baseUrl: bodyBaseUrl,
      region,
      cx,
      runtimeKey,
      tunnelId,
      connectorName,
    } = validation.data;

    let providerSpecificData: any = { validationModelId };
    if (customUserAgent) {
      providerSpecificData.customUserAgent = customUserAgent;
    }
    if (bodyBaseUrl) {
      providerSpecificData.baseUrl = bodyBaseUrl;
    }
    if (region) {
      providerSpecificData.region = region;
    }
    if (cx) {
      providerSpecificData.cx = cx;
    }
    if (runtimeKey) providerSpecificData.runtimeKey = runtimeKey;
    if (tunnelId) providerSpecificData.tunnelId = tunnelId;
    if (connectorName) providerSpecificData.connectorName = connectorName;

    if (isOpenAICompatibleProvider(provider) || isAnthropicCompatibleProvider(provider)) {
      const node: any = await getProviderNodeById(provider);
      if (!node) {
        const typeName = isOpenAICompatibleProvider(provider)
          ? "OpenAI"
          : isClaudeCodeCompatibleProvider(provider)
            ? "CC"
            : "Anthropic";
        return NextResponse.json(
          { error: `${typeName} Compatible node not found` },
          { status: 404 }
        );
      }
      providerSpecificData = {
        ...providerSpecificData,
        baseUrl: bodyBaseUrl || node.baseUrl,
        apiType: node.apiType,
        chatPath: node.chatPath,
        modelsPath: node.modelsPath,
      };
    }

    const registryProxy = await resolveProxyForProvider(provider);
    let proxyToUse = registryProxy;

    if (!proxyToUse) {
      const providerProxy = await getProxyForLevel("provider", provider);
      const globalProxy = providerProxy ? null : await getProxyForLevel("global");
      proxyToUse = providerProxy || globalProxy || null;
    }

    const result = await runWithProxyContextOrDirect(proxyToUse || null, () =>
      validateProviderApiKey({
        provider,
        apiKey,
        providerSpecificData,
      })
    );

    if (result.unsupported) {
      // #5565/#5567: surface `unsupported` so the dashboard can treat "validation
      // not supported" as a non-blocking warning (allow Save) instead of a hard
      // "Invalid" block — providers like lmarena / piapi have no live validator.
      return NextResponse.json(
        { error: "Provider validation not supported", unsupported: true },
        { status: 400 }
      );
    }

    if (!result.valid && typeof result.statusCode === "number") {
      if (result.securityBlocked) {
        logAuditEvent({
          action: "provider.validation.ssrf_blocked",
          actor: "admin",
          target: provider,
          resourceType: "provider_validation",
          status: "blocked",
          ipAddress: auditContext.ipAddress || undefined,
          requestId: auditContext.requestId,
          metadata: {
            provider,
            route: "/api/providers/validate",
            reason: result.error || "Blocked provider validation target",
            baseUrl: sanitizeAuditUrl(bodyBaseUrl || providerSpecificData?.baseUrl),
          },
        });
      }
      return NextResponse.json(
        { error: result.error || "Validation failed" },
        { status: result.statusCode }
      );
    }

    return NextResponse.json({
      valid: !!result.valid,
      error: result.valid ? null : result.error || "Invalid API key",
      warning: result.warning || null,
      method: result.method || null,
      capabilities: result.capabilities || null,
      providerSpecificData: result.providerSpecificData || null,
    });
  } catch (error) {
    console.log("Error validating API key:", error);
    return NextResponse.json({ error: "Validation failed" }, { status: 500 });
  }
}

/**
 * GET    /api/quota/plans/[connectionId]  — get resolved plan for a connection
 * PUT    /api/quota/plans/[connectionId]  — upsert manual plan override
 * DELETE /api/quota/plans/[connectionId]  — clear manual override (revert to auto/catalog)
 *
 * Auth: requireManagementAuth
 * Zod:  PlanUpsertSchema from @/shared/schemas/quota (PUT only)
 * Audit: quota.plan.updated on PUT and DELETE (B26 — DELETE reverts override to auto/catalog)
 * Sanitization: all error responses via buildErrorBody (Hard Rule #12, B25)
 *
 * For PUT: provider is derived from the connectionId via getProviderConnectionById.
 * If the connection lookup fails (e.g. provider not found), provider defaults to
 * "unknown" — the override is still stored so operator can correct later.
 *
 * Part of: Group B — REST routes for Quota Sharing (plan 22, frente F8).
 */

import { NextResponse } from "next/server";
import { buildErrorBody } from "@omniroute/open-sse/utils/error";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";
import { PlanUpsertSchema } from "@/shared/schemas/quota";
import { getProviderPlan } from "@/lib/db/providerPlans"
import { deleteProviderPlan, upsertProviderPlan } from "@/lib/localDb";
import { resolvePlan } from "@/lib/quota/planResolver";
import { resolveConnectionProvider } from "@/lib/quota/connectionProvider";
import { logAuditEvent, getAuditRequestContext } from "@/lib/compliance/index";

export const dynamic = "force-dynamic";

type RouteParams = { params: Promise<{ connectionId: string }> };

export async function GET(request: Request, { params }: RouteParams): Promise<Response> {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  try {
    const { connectionId } = await params;

    // Try DB override first, then fall back to resolved plan (catalog/empty)
    const dbPlan = getProviderPlan(connectionId);
    if (dbPlan) {
      return NextResponse.json({ plan: dbPlan });
    }

    // Resolve via catalog (may return empty plan)
    const provider = await resolveConnectionProvider(connectionId);
    const plan = resolvePlan(connectionId, provider);
    return NextResponse.json({ plan });
  } catch (err) {
    const message = err instanceof Error ? err.message : "Failed to get plan";
    return NextResponse.json(buildErrorBody(500, message), { status: 500 });
  }
}

export async function PUT(request: Request, { params }: RouteParams): Promise<Response> {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  try {
    const { connectionId } = await params;
    const body = await request.json().catch(() => null);
    const parsed = PlanUpsertSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(buildErrorBody(400, parsed.error.message), { status: 400 });
    }

    // Derive provider for the connection
    const provider = await resolveConnectionProvider(connectionId);

    upsertProviderPlan(connectionId, provider, parsed.data.dimensions, "manual");

    const ctx = getAuditRequestContext(request);
    logAuditEvent({
      action: "quota.plan.updated",
      target: connectionId,
      metadata: { provider, dimensions: parsed.data.dimensions, source: "manual" },
      ipAddress: ctx.ipAddress ?? undefined,
      requestId: ctx.requestId,
    });

    // Return the stored plan
    const plan = getProviderPlan(connectionId);
    return NextResponse.json({ plan });
  } catch (err) {
    const message = err instanceof Error ? err.message : "Failed to upsert plan";
    return NextResponse.json(buildErrorBody(500, message), { status: 500 });
  }
}

export async function DELETE(request: Request, { params }: RouteParams): Promise<Response> {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  try {
    const { connectionId } = await params;

    const existing = getProviderPlan(connectionId);
    const provider = existing?.provider ?? (await resolveConnectionProvider(connectionId));

    deleteProviderPlan(connectionId);

    const ctx = getAuditRequestContext(request);
    logAuditEvent({
      action: "quota.plan.updated",
      target: connectionId,
      metadata: { provider, source: "auto", reverted: true },
      ipAddress: ctx.ipAddress ?? undefined,
      requestId: ctx.requestId,
    });

    return new Response(null, { status: 204 });
  } catch (err) {
    const message = err instanceof Error ? err.message : "Failed to delete plan";
    return NextResponse.json(buildErrorBody(500, message), { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getCachedSettings } from "@/lib/db/readCache"
import { updateSettings } from "@/lib/db/settings"
import { getSettings } from "@/lib/localDb";
import {
  buildLegacyResilienceCompat,
  mergeResilienceSettings,
  resolveResilienceSettings,
  type ResilienceSettings,
  type ResilienceSettingsPatch,
} from "@/lib/resilience/settings";
import { updateResilienceSchema } from "@/shared/validation/schemas";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";
import { resetAllCircuitBreakers } from "@/shared/utils/circuitBreaker";
import { sanitizeErrorMessage } from "@omniroute/open-sse/utils/error";

type JsonRecord = Record<string, unknown>;

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function getErrorMessage(error: unknown, fallback: string): string {
  return sanitizeErrorMessage(error) || fallback;
}

function normalizeLegacyPatch(body: JsonRecord): ResilienceSettingsPatch {
  const profiles = asRecord(body.profiles);
  const defaults = asRecord(body.defaults);
  const oauth = asRecord(profiles.oauth);
  const apikey = asRecord(profiles.apikey);

  const patch: ResilienceSettingsPatch = {};

  if (Object.keys(defaults).length > 0) {
    patch.requestQueue = {
      ...(typeof defaults.requestsPerMinute === "number"
        ? { requestsPerMinute: defaults.requestsPerMinute }
        : {}),
      ...(typeof defaults.minTimeBetweenRequests === "number"
        ? { minTimeBetweenRequestsMs: defaults.minTimeBetweenRequests }
        : {}),
      ...(typeof defaults.concurrentRequests === "number"
        ? { concurrentRequests: defaults.concurrentRequests }
        : {}),
    };
  }

  if (Object.keys(oauth).length > 0 || Object.keys(apikey).length > 0) {
    const buildLegacyCooldownPatch = (profile: JsonRecord) => {
      const cooldownCandidates = [
        typeof profile.transientCooldown === "number" ? profile.transientCooldown : null,
        typeof profile.rateLimitCooldown === "number" && profile.rateLimitCooldown > 0
          ? profile.rateLimitCooldown
          : null,
      ].filter((value): value is number => typeof value === "number");

      return {
        ...(cooldownCandidates.length > 0
          ? { baseCooldownMs: Math.max(...cooldownCandidates) }
          : {}),
        ...(typeof profile.rateLimitCooldown === "number"
          ? { useUpstreamRetryHints: profile.rateLimitCooldown === 0 }
          : {}),
        ...(typeof profile.maxBackoffLevel === "number"
          ? { maxBackoffSteps: profile.maxBackoffLevel }
          : {}),
      };
    };

    patch.connectionCooldown = {
      ...(Object.keys(oauth).length > 0
        ? {
            oauth: buildLegacyCooldownPatch(oauth),
          }
        : {}),
      ...(Object.keys(apikey).length > 0
        ? {
            apikey: buildLegacyCooldownPatch(apikey),
          }
        : {}),
    };

    patch.providerBreaker = {
      ...(Object.keys(oauth).length > 0
        ? {
            oauth: {
              ...(typeof oauth.circuitBreakerThreshold === "number"
                ? { failureThreshold: oauth.circuitBreakerThreshold }
                : {}),
              ...(typeof oauth.circuitBreakerReset === "number"
                ? { resetTimeoutMs: oauth.circuitBreakerReset }
                : {}),
            },
          }
        : {}),
      ...(Object.keys(apikey).length > 0
        ? {
            apikey: {
              ...(typeof apikey.circuitBreakerThreshold === "number"
                ? { failureThreshold: apikey.circuitBreakerThreshold }
                : {}),
              ...(typeof apikey.circuitBreakerReset === "number"
                ? { resetTimeoutMs: apikey.circuitBreakerReset }
                : {}),
            },
          }
        : {}),
    };
  }

  return patch;
}

async function syncRuntimeSettings(resilienceSettings: ResilienceSettings) {
  const [{ applyRequestQueueSettings }, { setProviderQuotaOverrides }] = await Promise.all([
    import("@omniroute/open-sse/services/rateLimitManager"),
    import("@omniroute/open-sse/services/providerDefaultRateLimit"),
  ]);
  await applyRequestQueueSettings(resilienceSettings.requestQueue);
  // #6846 Phase 2: re-apply per-provider RPM/concurrency overrides on the hot
  // path so a PATCH takes effect without a process restart. Mirrors the call in
  // rateLimitManager.ts::initializeRateLimits() (startup).
  setProviderQuotaOverrides(resilienceSettings.providerQuotaOverrides);
}

/**
 * GET /api/resilience — Get current resilience configuration
 */
export async function GET() {
  try {
    const settings = await getCachedSettings();
    const resilience = resolveResilienceSettings(settings);

    return NextResponse.json({
      requestQueue: resilience.requestQueue,
      connectionCooldown: resilience.connectionCooldown,
      providerBreaker: resilience.providerBreaker,
      waitForCooldown: {
        enabled: resilience.waitForCooldown.enabled,
        maxRetries: resilience.waitForCooldown.maxRetries,
        maxRetryWaitSec: resilience.waitForCooldown.maxRetryWaitSec,
      },
      comboCooldownWait: resilience.comboCooldownWait,
      quotaShareConcurrencyLimit: resilience.quotaShareConcurrencyLimit,
      providerCooldown: resilience.providerCooldown,
      providerQuotaOverrides: resilience.providerQuotaOverrides,
      legacy: buildLegacyResilienceCompat(resilience),
    });
  } catch (err: unknown) {
    console.error("[API] GET /api/resilience error:", err);
    return NextResponse.json(
      { error: getErrorMessage(err, "Failed to load resilience settings") },
      { status: 500 }
    );
  }
}

/**
 * PATCH /api/resilience — Update resilience configuration
 */
export async function PATCH(request) {
  let rawBody;
  try {
    rawBody = await request.json();
  } catch {
    return NextResponse.json(
      {
        error: {
          message: "Invalid request",
          details: [{ field: "body", message: "Invalid JSON body" }],
        },
      },
      { status: 400 }
    );
  }

  try {
    const validation = validateBody(updateResilienceSchema, rawBody);
    if (isValidationFailure(validation)) {
      return NextResponse.json({ error: validation.error }, { status: 400 });
    }

    const body = validation.data as JsonRecord;
    const currentSettings = await getSettings();
    const currentResilience = resolveResilienceSettings(currentSettings);
    const nextResilience = mergeResilienceSettings(currentResilience, {
      ...(body.requestQueue
        ? { requestQueue: body.requestQueue as ResilienceSettingsPatch["requestQueue"] }
        : {}),
      ...(body.connectionCooldown
        ? {
            connectionCooldown:
              body.connectionCooldown as ResilienceSettingsPatch["connectionCooldown"],
          }
        : {}),
      ...(body.providerBreaker
        ? { providerBreaker: body.providerBreaker as ResilienceSettingsPatch["providerBreaker"] }
        : {}),
      ...(body.waitForCooldown
        ? { waitForCooldown: body.waitForCooldown as ResilienceSettingsPatch["waitForCooldown"] }
        : {}),
      ...(body.comboCooldownWait
        ? {
            comboCooldownWait:
              body.comboCooldownWait as ResilienceSettingsPatch["comboCooldownWait"],
          }
        : {}),
      ...(body.quotaShareConcurrencyLimit
        ? {
            quotaShareConcurrencyLimit:
              body.quotaShareConcurrencyLimit as ResilienceSettingsPatch["quotaShareConcurrencyLimit"],
          }
        : {}),
      ...(body.providerCooldown
        ? {
            providerCooldown: body.providerCooldown as ResilienceSettingsPatch["providerCooldown"],
          }
        : {}),
      ...(body.providerQuotaOverrides
        ? {
            providerQuotaOverrides:
              body.providerQuotaOverrides as ResilienceSettingsPatch["providerQuotaOverrides"],
          }
        : {}),
      ...normalizeLegacyPatch(body),
    });

    await updateSettings({
      resilienceSettings: nextResilience,
      requestRetry: nextResilience.waitForCooldown.maxRetries,
      maxRetryIntervalSec: nextResilience.waitForCooldown.maxRetryWaitSec,
    });
    await syncRuntimeSettings(nextResilience);

    // Issue #2100 follow-up: detect transitions in useUpstream429BreakerHints
    // and reset breakers so the registry stops serving cached options.
    // Compared on STORED override transition (boolean | undefined) so that
    // `null` (PATCH input) → undefined (stored) is correctly detected as
    // "unset request" when the previous stored value was a boolean.
    const breakerHintsChanged =
      currentResilience.connectionCooldown.oauth.useUpstream429BreakerHints !==
        nextResilience.connectionCooldown.oauth.useUpstream429BreakerHints ||
      currentResilience.connectionCooldown.apikey.useUpstream429BreakerHints !==
        nextResilience.connectionCooldown.apikey.useUpstream429BreakerHints;
    if (breakerHintsChanged) {
      resetAllCircuitBreakers();
    }

    return NextResponse.json({
      ok: true,
      requestQueue: nextResilience.requestQueue,
      connectionCooldown: nextResilience.connectionCooldown,
      providerBreaker: nextResilience.providerBreaker,
      waitForCooldown: {
        enabled: nextResilience.waitForCooldown.enabled,
        maxRetries: nextResilience.waitForCooldown.maxRetries,
        maxRetryWaitSec: nextResilience.waitForCooldown.maxRetryWaitSec,
      },
      comboCooldownWait: nextResilience.comboCooldownWait,
      quotaShareConcurrencyLimit: nextResilience.quotaShareConcurrencyLimit,
      providerCooldown: nextResilience.providerCooldown,
      providerQuotaOverrides: nextResilience.providerQuotaOverrides,
      legacy: buildLegacyResilienceCompat(nextResilience),
    });
  } catch (err: unknown) {
    console.error("[API] PATCH /api/resilience error:", err);
    return NextResponse.json(
      { error: getErrorMessage(err, "Failed to save resilience settings") },
      { status: 500 }
    );
  }
}

/**
 * GET /api/services/[name]/logs — SSE log tail for embedded services.
 *
 * Query params:
 *   tail   — number of historical lines to send first (default 200, max 1000)
 *   filter — optional case-insensitive substring filter (no regex — ReDoS-safe by design)
 *
 * Events:
 *   event: snapshot  — array of LogLine objects (initial tail)
 *   event: log       — single LogLine object (live)
 *   event: heartbeat — keep-alive, no meaningful data
 */

import type { NextRequest } from "next/server";
import { getSupervisor } from "@/lib/services/registry";
import { createErrorResponse } from "@/lib/api/errorResponse";
import type { LogLine } from "@/lib/services/types";

const MAX_TAIL = 1000;
const DEFAULT_TAIL = 200;
const HEARTBEAT_MS = 15_000;
const MAX_FILTER_LEN = 200;

const encoder = new TextEncoder();

async function getOrInitNamedSupervisor(name: string) {
  const existing = getSupervisor(name);
  if (existing) return existing;

  if (name === "cliproxy") {
    const { getOrInitSupervisor } = await import("../../cliproxy/_lib");
    return getOrInitSupervisor();
  }

  if (name === "9router") {
    const { getOrInitSupervisor } = await import("../../9router/_lib");
    return getOrInitSupervisor();
  }

  if (name === "mux") {
    const { getOrInitSupervisor } = await import("../../mux/_lib");
    return getOrInitSupervisor();
  }
  if (name === "bifrost") {
    const { getOrInitSupervisor } = await import("../../bifrost/_lib");
    return getOrInitSupervisor();
  }
  if (name === "dario") {
    const { getOrInitSupervisor } = await import("../../dario/_lib");
    return getOrInitSupervisor();
  }

  return null;
}

function sseChunk(event: string, data: unknown): Uint8Array {
  return encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

export async function GET(request: NextRequest, { params }: { params: Promise<{ name: string }> }) {
  const { name } = await params;

  const supervisor = await getOrInitNamedSupervisor(name);
  if (!supervisor) {
    return createErrorResponse({ status: 404, message: `Service '${name}' not found` });
  }

  const url = new URL(request.url);
  const tailRaw = url.searchParams.get("tail");
  const filterRaw = url.searchParams.get("filter");

  const tail = Math.min(
    tailRaw ? Math.max(0, parseInt(tailRaw, 10) || DEFAULT_TAIL) : DEFAULT_TAIL,
    MAX_TAIL
  );

  if (filterRaw !== null && filterRaw.length > MAX_FILTER_LEN) {
    return createErrorResponse({ status: 400, message: "filter exceeds maximum length" });
  }

  // Substring match only — avoids ReDoS that user-supplied RegExp() would introduce.
  const filterLower = filterRaw !== null ? filterRaw.toLowerCase() : null;

  const buffer = supervisor.getRingBuffer();
  const signal = request.signal;

  const stream = new ReadableStream({
    start(controller) {
      if (signal.aborted) {
        controller.close();
        return;
      }

      const applyFilter = (line: LogLine) =>
        filterLower === null || line.line.toLowerCase().includes(filterLower);

      // Send initial snapshot
      const snapshot = buffer.snapshot().filter(applyFilter).slice(-tail);
      controller.enqueue(sseChunk("snapshot", snapshot));

      // Subscribe to live events
      const unsubscribe = buffer.subscribe((line) => {
        if (!applyFilter(line)) return;
        try {
          controller.enqueue(sseChunk("log", line));
        } catch {
          // controller closed — subscriber will be removed on abort
        }
      });

      // Heartbeat
      const heartbeatTimer = setInterval(() => {
        try {
          controller.enqueue(sseChunk("heartbeat", {}));
        } catch {
          clearInterval(heartbeatTimer);
        }
      }, HEARTBEAT_MS);

      // Cleanup on client disconnect
      signal.addEventListener("abort", () => {
        clearInterval(heartbeatTimer);
        unsubscribe();
        try {
          controller.close();
        } catch {
          // already closed
        }
      });
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      Connection: "keep-alive",
      "X-Accel-Buffering": "no",
    },
  });
}

