import { NextResponse } from "next/server";
import { getSettings } from "@/lib/localDb";
import { isAuthRequired, isDashboardSessionAuthenticated } from "@/shared/utils/apiAuth";
import { createErrorResponse } from "@/lib/api/errorResponse";
import { extractApiKey, isValidApiKey } from "@/sse/services/auth";
import {
  LOCAL_ONLY_API_PREFIXES,
  ALWAYS_PROTECTED_API_PATHS,
  LOCAL_ONLY_MANAGE_SCOPE_BYPASS_PREFIXES,
  SPAWN_CAPABLE_PREFIXES,
} from "@/server/authz/routeGuard";
import { getCorsStatus } from "@/server/cors/origins";

/**
 * Static MANAGEMENT-tier example prefixes. Render-only — never consulted by
 * the runtime policy. The actual MANAGEMENT classification is "any /api/*
 * that is not LOCAL_ONLY, not v1/client, not on the public allowlist", so the
 * inventory shows representative entries rather than a generated enumeration.
 */
const MANAGEMENT_TIER_PREFIXES: ReadonlyArray<string> = [
  "/api/settings",
  "/api/providers/",
  "/api/api-keys",
];

const CLIENT_API_TIER_PREFIXES: ReadonlyArray<string> = [
  "/v1/",
  "/api/v1/",
  "/v1beta/",
  "/api/v1beta/",
];

const PUBLIC_TIER_PREFIXES: ReadonlyArray<string> = ["/api/health", "/api/version", "/_next/"];

type TierName = "LOCAL_ONLY" | "ALWAYS_PROTECTED" | "MANAGEMENT" | "CLIENT_API" | "PUBLIC";

interface TierEntry {
  name: TierName;
  prefixes: string[];
  description: string;
  bypassable: boolean;
}

/**
 * OQ-5: viewing the inventory requires authentication (dashboard session OR
 * any valid API key, regardless of scope). The inventory leaks route-prefix
 * taxonomy + current bypass state (reconnaissance value), so we never expose
 * it anonymously — but a non-manage key holder may still inspect it.
 *
 * Compare with `requireManagementAuth` which would refuse anything below the
 * manage scope; this endpoint is intentionally read-only and one rung lower.
 */
async function requireInventoryReadAuth(request: Request): Promise<Response | null> {
  if (!(await isAuthRequired(request))) {
    return null;
  }

  if (await isDashboardSessionAuthenticated(request)) {
    return null;
  }

  const apiKey = extractApiKey(request);
  if (apiKey) {
    try {
      if (await isValidApiKey(apiKey)) {
        return null;
      }
    } catch {
      return createErrorResponse({
        status: 503,
        message: "Service temporarily unavailable",
        type: "server_error",
      });
    }
    return createErrorResponse({
      status: 403,
      message: "Invalid API key",
      type: "invalid_request",
    });
  }

  return createErrorResponse({
    status: 401,
    message: "Authentication required",
    type: "invalid_request",
  });
}

function isBypassableConstant(prefix: string): boolean {
  // A LOCAL_ONLY prefix is bypassable iff it appears in the compile-time
  // bypass constant AND is not a SPAWN_CAPABLE prefix. Runtime DB state is
  // surfaced separately via `bypassEnabled` / `bypassPrefixes`.
  if (SPAWN_CAPABLE_PREFIXES.some((p) => p === prefix || prefix.startsWith(p))) {
    return false;
  }
  return LOCAL_ONLY_MANAGE_SCOPE_BYPASS_PREFIXES.some((p) => p === prefix);
}

export async function GET(request: Request) {
  const authError = await requireInventoryReadAuth(request);
  if (authError) return authError;

  try {
    const settings = await getSettings();

    const tiers: TierEntry[] = [
      {
        name: "LOCAL_ONLY",
        prefixes: [...LOCAL_ONLY_API_PREFIXES],
        description:
          "Loopback-only routes. Spawn child processes; exposing them to non-local traffic is a known CVE class (GHSA-fhh6-4qxv-rpqj). Some entries are opt-in bypassable via the manage scope (kill-switch gated).",
        bypassable: LOCAL_ONLY_API_PREFIXES.some(isBypassableConstant),
      },
      {
        name: "ALWAYS_PROTECTED",
        prefixes: [...ALWAYS_PROTECTED_API_PATHS],
        description:
          "Auth required unconditionally, even when requireLogin=false. Covers destructive / irreversible operations (shutdown, database settings).",
        bypassable: false,
      },
      {
        name: "MANAGEMENT",
        prefixes: [...MANAGEMENT_TIER_PREFIXES],
        description:
          "Default tier for /api/* admin endpoints. Auth required unless requireLogin=false. PATCHes touching security-impacting keys require currentPassword re-auth.",
        bypassable: false,
      },
      {
        name: "CLIENT_API",
        prefixes: [...CLIENT_API_TIER_PREFIXES],
        description:
          "Client-facing inference APIs. Accept Bearer API keys; not gated by dashboard sessions.",
        bypassable: false,
      },
      {
        name: "PUBLIC",
        prefixes: [...PUBLIC_TIER_PREFIXES],
        description: "Unauthenticated routes: health probes, public assets, onboarding bootstrap.",
        bypassable: false,
      },
    ];

    const bypassEnabled =
      typeof settings.localOnlyManageScopeBypassEnabled === "boolean"
        ? settings.localOnlyManageScopeBypassEnabled
        : true;
    const bypassPrefixesRaw = settings.localOnlyManageScopeBypassPrefixes;
    const bypassPrefixes = Array.isArray(bypassPrefixesRaw)
      ? bypassPrefixesRaw.filter((p): p is string => typeof p === "string")
      : [...LOCAL_ONLY_MANAGE_SCOPE_BYPASS_PREFIXES];

    return NextResponse.json({
      tiers,
      bypassEnabled,
      bypassPrefixes,
      spawnCapablePrefixes: [...SPAWN_CAPABLE_PREFIXES],
      // #5602: surface the effective CORS allowlist so the dashboard can warn
      // when `CORS_ALLOW_ALL=true` is set (wildcard origins). See docs/security/CORS.md.
      cors: getCorsStatus(),
    });
  } catch (error) {
    console.log("Error loading authz inventory:", error);
    return NextResponse.json({ error: "Failed to load authz inventory" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { updateSettings } from "@/lib/db/settings"
import { getSettings } from "@/lib/localDb";
import { updateAutoDisableAccountsSchema } from "@/shared/validation/schemas";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";

export async function GET(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;
  try {
    const settings = await getSettings();
    return NextResponse.json({
      enabled: settings.autoDisableBannedAccounts ?? false,
      threshold: settings.autoDisableBannedThreshold ?? 3,
    });
  } catch (error) {
    console.error("Error reading auto-disable accounts config:", error);
    return NextResponse.json(
      { error: "Failed to read auto-disable accounts config" },
      { status: 500 }
    );
  }
}

export async function PUT(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;
  let rawBody: unknown;
  try {
    rawBody = await request.json();
  } catch {
    return NextResponse.json(
      {
        error: {
          message: "Invalid request",
          details: [{ field: "body", message: "Invalid JSON body" }],
        },
      },
      { status: 400 }
    );
  }

  try {
    const validation = validateBody(updateAutoDisableAccountsSchema, rawBody);
    if (isValidationFailure(validation)) {
      return NextResponse.json({ error: validation.error }, { status: 400 });
    }
    const body = validation.data;

    await updateSettings({
      autoDisableBannedAccounts: body.enabled,
      ...(body.threshold !== undefined && { autoDisableBannedThreshold: body.threshold }),
    });

    const settings = await getSettings();
    return NextResponse.json({
      enabled: settings.autoDisableBannedAccounts ?? false,
      threshold: settings.autoDisableBannedThreshold ?? 3,
    });
  } catch (error) {
    console.error("Error updating auto-disable accounts config:", error);
    return NextResponse.json(
      { error: "Failed to update auto-disable accounts config" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { updateSettings } from "@/lib/db/settings"
import { getSettings } from "@/lib/localDb";
import { updateComboDefaultsSchema } from "@/shared/validation/schemas";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";
import { isPaidModelTarget } from "@/shared/utils/freeModels";

const LEGACY_COMBO_RESILIENCE_KEYS = new Set([
  "timeoutMs",
  "healthCheckEnabled",
  "healthCheckTimeoutMs",
]);

function sanitizeComboRuntimeConfig(config?: Record<string, any> | null) {
  if (!config || typeof config !== "object") return {};
  return Object.fromEntries(
    Object.entries(config).filter(
      ([key, value]) =>
        value !== undefined && value !== null && !LEGACY_COMBO_RESILIENCE_KEYS.has(key)
    )
  );
}

function sanitizeProviderOverrides(overrides?: Record<string, any> | null) {
  if (!overrides || typeof overrides !== "object") return {};
  return Object.fromEntries(
    Object.entries(overrides).map(([providerId, config]) => [
      providerId,
      sanitizeComboRuntimeConfig(config),
    ])
  );
}

/**
 * GET /api/settings/combo-defaults
 * Returns the current combo global defaults and provider overrides
 */
export async function GET(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;
  try {
    const settings: any = await getSettings();
    const comboDefaults = sanitizeComboRuntimeConfig(settings.comboDefaults);
    const providerOverrides = sanitizeProviderOverrides(settings.providerOverrides);
    return NextResponse.json({
      comboDefaults:
        Object.keys(comboDefaults).length > 0
          ? comboDefaults
          : {
              strategy: "priority",
              maxRetries: 1,
              retryDelayMs: 2000,
              fallbackDelayMs: 0,
              handoffThreshold: 0.85,
              handoffModel: "",
              maxMessagesForSummary: 30,
              maxComboDepth: 3,
              trackMetrics: true,
              reasoningTokenBufferEnabled: true,
              zeroLatencyOptimizationsEnabled: false,
            },
      providerOverrides,
    });
  } catch (error) {
    console.log("Error fetching combo defaults:", error);
    return NextResponse.json({ error: "Failed to fetch combo defaults" }, { status: 500 });
  }
}

/**
 * PATCH /api/settings/combo-defaults
 * Update combo global defaults and/or provider overrides
 * Body: { comboDefaults?: {...}, providerOverrides?: {...} }
 */
export async function PATCH(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;
  let rawBody;
  try {
    rawBody = await request.json();
  } catch {
    return NextResponse.json(
      {
        error: {
          message: "Invalid request",
          details: [{ field: "body", message: "Invalid JSON body" }],
        },
      },
      { status: 400 }
    );
  }

  try {
    const validation = validateBody(updateComboDefaultsSchema, rawBody);
    if (isValidationFailure(validation)) {
      return NextResponse.json({ error: validation.error }, { status: 400 });
    }
    const body = validation.data;

    // #6540: reject a paid-only handoffModel target when hidePaidModels is on.
    // Fails open on "unknown" (aliases/combo names) — mirrors the settings
    // route's PAID_MODEL_TARGET_BLOCKED check.
    if (
      typeof body.comboDefaults?.handoffModel === "string" &&
      body.comboDefaults.handoffModel.trim() !== ""
    ) {
      const currentSettings: any = await getSettings();
      if (currentSettings?.hidePaidModels === true) {
        if (isPaidModelTarget(body.comboDefaults.handoffModel) === "paid") {
          return NextResponse.json(
            {
              error: {
                code: "PAID_MODEL_TARGET_BLOCKED",
                message:
                  "This field cannot target a paid-only model while 'Hide paid models' is enabled.",
              },
            },
            { status: 400 }
          );
        }
      }
    }

    const updates: Record<string, any> = {};

    if (body.comboDefaults) {
      updates.comboDefaults = sanitizeComboRuntimeConfig(body.comboDefaults);
    }
    if (body.providerOverrides) {
      updates.providerOverrides = sanitizeProviderOverrides(body.providerOverrides);
    }

    const settings: any = await updateSettings(updates);
    return NextResponse.json({
      comboDefaults: sanitizeComboRuntimeConfig(settings.comboDefaults),
      providerOverrides: sanitizeProviderOverrides(settings.providerOverrides),
    });
  } catch (error) {
    console.log("Error updating combo defaults:", error);
    return NextResponse.json({ error: "Failed to update combo defaults" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getApiKeys } from "@/lib/db/apiKeys"
import { getCombos } from "@/lib/db/combos"
import { getProviderConnections } from "@/lib/db/providers"
import { getCachedProviderNodes } from "@/lib/db/readCache"
import { getSettings } from "@/lib/localDb";
import { isAuthRequired, isAuthenticated } from "@/shared/utils/apiAuth";
import {
  getAllUsageHistory,
  getAllDomainCostHistory,
  getAllDomainBudgets,
} from "@/lib/db/usageAnalytics";
import { isFreeModel, providerHasFreeModels } from "@/shared/utils/freeModels";

/**
 * When `settings.hidePaidModels === true`, exports must not leak paid model ids
 * via combos — otherwise a round-trip (export → share/store → import) silently
 * re-materialises the paid targets the operator asked to REMOVE (#6328).
 * Filter combo model steps in place; keep combo-ref steps untouched.
 */
export function filterPaidComboSteps<T extends { models?: unknown }>(combos: T[]): T[] {
  return combos.map((combo) => {
    if (!Array.isArray(combo.models)) return combo;
    const filtered = combo.models.filter((step) => {
      if (!step || typeof step !== "object") return true;
      const s = step as Record<string, unknown>;
      if (s.kind === "combo-ref") return true;
      const rawModel = typeof s.model === "string" ? s.model.trim() : "";
      if (!rawModel) return true;
      const provider =
        (typeof s.providerId === "string" && s.providerId.trim()) ||
        (typeof s.provider === "string" && s.provider.trim()) ||
        (rawModel.includes("/") ? rawModel.split("/")[0] : "");
      if (!provider) return true;
      if (!providerHasFreeModels(provider)) return false;
      const modelId = rawModel.startsWith(`${provider}/`)
        ? rawModel.slice(provider.length + 1)
        : rawModel;
      return isFreeModel(provider, { id: modelId });
    });
    return { ...combo, models: filtered };
  });
}

/**
 * GET /api/settings/export-json
 * Exports a legacy OmniRoute-compatible JSON backup.
 */
export async function GET(request: Request) {
  if (await isAuthRequired(request)) {
    if (!(await isAuthenticated(request))) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
  }

  try {
    const url = new URL(request.url);
    // Telemetry/history tables grow indefinitely and inflate backups.
    // Exclude them by default — opt-in with ?includeHistory=true (#2125).
    const includeHistory = url.searchParams.get("includeHistory") === "true";

    const rawSettings = await getSettings();

    // REDACT sensitive security keys to maintain Zero-Trust posture
    // even if the admin shares their backup file.
    // Use destructuring (not delete) to avoid mutating a potentially cached object.
    const { password: _pw, requireLogin: _rl, ...safeSettings } = rawSettings;

    const providerConnections = await getProviderConnections();
    const providerNodes = await getCachedProviderNodes();
    const combosRaw = await getCombos();
    const apiKeys = await getApiKeys();

    // #6328: honor hidePaidModels at the export boundary so backup files
    // cannot silently smuggle paid model ids back in on import.
    const combos = rawSettings.hidePaidModels === true
      ? filterPaidComboSteps(combosRaw as Array<{ models?: unknown }>)
      : combosRaw;

    const exportData: Record<string, unknown> = {
      settings: safeSettings,
      providerConnections,
      providerNodes,
      combos,
      apiKeys,
      // Metadata to identify export version
      _meta: {
        exportedAt: new Date().toISOString(),
        version: "omniroute-v3-legacy-export",
        includesHistory: includeHistory,
      },
    };

    // Only include telemetry/history tables when explicitly requested.
    // These tables (usage_history, domain_cost_history, domain_budgets) can contain
    // thousands of rows and make the config backup grow to many MBs.
    if (includeHistory) {
      exportData.usageHistory = getAllUsageHistory();
      exportData.domainCostHistory = getAllDomainCostHistory();
      exportData.domainBudgets = getAllDomainBudgets();
    }

    return new NextResponse(JSON.stringify(exportData, null, 2), {
      status: 200,
      headers: {
        "Content-Type": "application/json",
        "Content-Disposition": `attachment; filename="omniroute-legacy-backup-${new Date().toISOString().replace(/[:.]/g, "-")}.json"`,
      },
    });
  } catch (error) {
    console.error("[API] Error exporting JSON backup:", error);
    return NextResponse.json({ error: "Failed to export JSON" }, { status: 500 });
  }
}

import { requireManagementAuth } from "@/lib/api/requireManagementAuth";
import { createErrorResponse, createErrorResponseFromUnknown } from "@/lib/api/errorResponse";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";
import { freeProxyListSchema, freeProxySourceSchema } from "@/shared/validation/freeProxySchemas";
import { getFreeProxyStats } from "@/lib/db/freeProxies"
import { clearFreeProxiesBySource, countFreeProxies, deleteFreeProxy, getFreeProxySyncErrors, listFreeProxies } from "@/lib/localDb";
import type { FreeProxySourceId } from "@/lib/freeProxyProviders/types";

export async function GET(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  try {
    const { searchParams } = new URL(request.url);
    const raw = {
      sources: searchParams.get("sources") || undefined,
      protocol: searchParams.get("protocol") || undefined,
      country: searchParams.get("country") || undefined,
      minQuality: searchParams.get("minQuality") || undefined,
      search: searchParams.get("search") || undefined,
      sortBy: searchParams.get("sortBy") || undefined,
      limit: searchParams.get("limit") || undefined,
      offset: searchParams.get("offset") || undefined,
      onlyNotInPool: searchParams.get("onlyNotInPool") || undefined,
    };

    const validation = validateBody(freeProxyListSchema, raw);
    if (isValidationFailure(validation)) {
      return createErrorResponse({
        status: 400,
        message: validation.error.message,
        type: "invalid_request",
      });
    }

    const items = await listFreeProxies({
      sources: validation.data.sources as FreeProxySourceId[] | undefined,
      protocol: validation.data.protocol,
      country: validation.data.country,
      minQuality: validation.data.minQuality,
      search: validation.data.search,
      sortBy: validation.data.sortBy,
      limit: validation.data.limit,
      offset: validation.data.offset,
      onlyNotInPool: validation.data.onlyNotInPool || undefined,
    });

    const total = await countFreeProxies({
      sources: validation.data.sources as FreeProxySourceId[] | undefined,
      protocol: validation.data.protocol,
      country: validation.data.country,
      minQuality: validation.data.minQuality,
      search: validation.data.search,
      onlyNotInPool: validation.data.onlyNotInPool || undefined,
    });

    const limit = validation.data.limit ?? 50;
    const stats = await getFreeProxyStats();
    const syncErrors = await getFreeProxySyncErrors();

    return Response.json({
      success: true,
      data: {
        proxies: items,
        total,
        hasMore: items.length >= limit && total > items.length + (validation.data.offset ?? 0),
        stats,
        syncErrors,
      },
    });
  } catch (error) {
    return createErrorResponseFromUnknown(error, "Failed to list free proxies");
  }
}

export async function DELETE(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get("id");
    const source = searchParams.get("source");

    if (source) {
      const parsed = freeProxySourceSchema.safeParse(source);
      if (!parsed.success) {
        return createErrorResponse({
          status: 400,
          message: "Invalid source",
          type: "invalid_request",
        });
      }
      const count = await clearFreeProxiesBySource(parsed.data);
      return Response.json({ success: true, deleted: count });
    }

    if (!id) {
      return createErrorResponse({
        status: 400,
        message: "id or source required",
        type: "invalid_request",
      });
    }

    const deleted = await deleteFreeProxy(id);
    if (!deleted) {
      return createErrorResponse({ status: 404, message: "Proxy not found", type: "not_found" });
    }
    return Response.json({ success: true });
  } catch (error) {
    return createErrorResponseFromUnknown(error, "Failed to delete free proxy");
  }
}

import { NextRequest, NextResponse } from "next/server";
import { updateSettings } from "@/lib/db/settings"
import { getSettings } from "@/lib/localDb";
import { isAuthenticated } from "@/shared/utils/apiAuth";
