import { MemorySettingsExtendedSchema } from "@/shared/schemas/memory";
import {
  invalidateMemorySettingsCache,
  normalizeMemorySettings,
  toMemorySettingsUpdates,
} from "@/lib/memory/settings";
import { sanitizeErrorMessage } from "@omniroute/open-sse/utils/error.ts";

export async function GET(request: NextRequest) {
  if (!(await isAuthenticated(request))) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const settings = (await getSettings()) as Record<string, unknown>;
    return NextResponse.json(normalizeMemorySettings(settings));
  } catch (err: unknown) {
    const message = sanitizeErrorMessage(err instanceof Error ? err.message : String(err));
    return NextResponse.json({ error: { message } }, { status: 500 });
  }
}

export async function PUT(request: NextRequest) {
  if (!(await isAuthenticated(request))) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  let rawBody: unknown;
  try {
    rawBody = await request.json();
  } catch {
    return NextResponse.json(
      { error: { message: "Invalid JSON body", details: [] } },
      { status: 400 },
    );
  }

  const validation = validateBody(MemorySettingsExtendedSchema, rawBody);
  if (isValidationFailure(validation)) {
    return NextResponse.json(validation.error, { status: 400 });
  }

  try {
    const updates = toMemorySettingsUpdates(validation.data);
    const settings = (await updateSettings(updates)) as Record<string, unknown>;
    invalidateMemorySettingsCache();

    return NextResponse.json(normalizeMemorySettings(settings));
  } catch (err: unknown) {
    const message = sanitizeErrorMessage(err instanceof Error ? err.message : String(err));
    return NextResponse.json({ error: { message } }, { status: 500 });
  }
}

import { z } from "zod";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";
import { createErrorResponse, createErrorResponseFromUnknown } from "@/lib/api/errorResponse";
import { getProxyById } from "@/lib/db/proxies"
import { updateProxy } from "@/lib/localDb";
import { decrypt } from "@/lib/db/encryption";
import { isRelayProxyType, relayRepairMode } from "@/lib/db/proxies/mappers";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";

const idParamSchema = z.object({ id: z.string().min(1) });

/**
 * POST /api/settings/proxies/[id]/repair-relay
 *
 * Recovers a relay's auth IN PLACE without a full redeploy. The deploy token is
 * never persisted, but when STORAGE_ENCRYPTION_KEY is set the deploy routes
 * wrote an encrypted `relayAuthEnc` blob into proxy `notes`. That blob is the
 * recoverable secret — we decrypt it and write the plaintext `relayAuth` back,
 * so the relay works again without re-entering any deploy credentials.
 *
 * Returns:
 *   200 { repaired: false, mode: "noop" }      — plaintext already present
 *   200 { repaired: true,  mode: "recovered" }  — re-derived from relayAuthEnc
 *   409 { repaired: false, mode: "redeploy" }  — token unrecoverable, redeploy
 *   400                                      — not a relay-type proxy
 *   404                                      — proxy not found
 */
export async function POST(
  request: Request,
  context: { params: Promise<{ id: string }> | { id: string } }
) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  const params = await context.params;
  const idValidation = validateBody(idParamSchema, params);
  if (isValidationFailure(idValidation)) {
    return createErrorResponse({
      status: 400,
      message: idValidation.error.message,
      type: "invalid_request",
    });
  }
  const { id } = idValidation.data;

  try {
    const proxy = await getProxyById(id, { includeSecrets: true });
    if (!proxy) {
      return createErrorResponse({ status: 404, message: "Proxy not found", type: "not_found" });
    }

    if (!isRelayProxyType(proxy.type)) {
      return createErrorResponse({
        status: 400,
        message: "Repair is only available for relay proxies (vercel/deno/cloudflare)",
        type: "invalid_request",
      });
    }

    const mode = relayRepairMode(proxy.notes, proxy.type);
    if (mode === "noop") {
      return Response.json({ repaired: false, mode });
    }

    if (mode === "redeploy") {
      return createErrorResponse({
        status: 409,
        message:
          "Relay auth is unrecoverable (no stored token, encrypted blob absent or undecryptable — " +
          "likely a STORAGE_ENCRYPTION_KEY rotation). Redeploy the relay to write a fresh relayAuth.",
        type: "conflict",
      });
    }

    // mode === "recovered": read the still-encrypted blob, decrypt, write plaintext.
    let enc: string | undefined;
    let existingNotes: Record<string, unknown> = {};
    try {
      const parsed = JSON.parse(proxy.notes ?? "{}") as Record<string, unknown>;
      existingNotes = parsed;
      if (typeof parsed.relayAuthEnc === "string") enc = parsed.relayAuthEnc;
    } catch {
      enc = undefined;
    }
    const decrypted = typeof enc === "string" ? decrypt(enc) : undefined;
    if (!decrypted) {
      return createErrorResponse({
        status: 409,
        message:
          "Relay auth is unrecoverable (encrypted blob could not be decrypted — likely a " +
          "STORAGE_ENCRYPTION_KEY rotation). Redeploy the relay to write a fresh relayAuth.",
        type: "conflict",
      });
    }

    // Merge relayAuth into existing notes; drop relayAuthEnc since plaintext is now present.
    const { relayAuthEnc: _dropped, ...rest } = existingNotes as { relayAuthEnc?: unknown };
    await updateProxy(id, { notes: JSON.stringify({ ...rest, relayAuth: decrypted }) });
    return Response.json({ repaired: true, mode: "recovered" });
  } catch (error) {
    return createErrorResponseFromUnknown(error, "Failed to repair relay");
  }
}

import { assignProxyToScope, getProxyAssignments } from "@/lib/db/proxies"
import { resolveProxyForConnection } from "@/lib/localDb";
import { proxyAssignmentSchema } from "@/shared/validation/schemas";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";
import { createErrorResponse, createErrorResponseFromUnknown } from "@/lib/api/errorResponse";
import { clearDispatcherCache } from "@omniroute/open-sse/utils/proxyDispatcher";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";

export async function GET(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;
  try {
    const { searchParams } = new URL(request.url);
    const proxyId = searchParams.get("proxyId");
    const scope = searchParams.get("scope");
    const scopeId = searchParams.get("scopeId");
    const resolveConnectionId = searchParams.get("resolveConnectionId");

    if (resolveConnectionId) {
      const resolved = await resolveProxyForConnection(resolveConnectionId);
      return Response.json(resolved);
    }

    const assignments = await getProxyAssignments({
      proxyId: proxyId || undefined,
      scope: scope || undefined,
    });
    const filtered = scopeId
      ? assignments.filter((entry) => entry.scopeId === scopeId)
      : assignments;
    return Response.json({ items: filtered, total: filtered.length });
  } catch (error) {
    return createErrorResponseFromUnknown(error, "Failed to load proxy assignments");
  }
}

export async function PUT(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;
  let rawBody: unknown;
  try {
    rawBody = await request.json();
  } catch {
    return createErrorResponse({
      status: 400,
      message: "Invalid JSON body",
      type: "invalid_request",
    });
  }

  try {
    const validation = validateBody(proxyAssignmentSchema, rawBody);
    if (isValidationFailure(validation)) {
      return createErrorResponse({
        status: 400,
        message: validation.error.message,
        details: validation.error.details,
        type: "invalid_request",
      });
    }

    const { scope, scopeId, proxyId } = validation.data;
    const assigned = await assignProxyToScope(scope, scopeId || null, proxyId || null);
    clearDispatcherCache();
    return Response.json({ success: true, assignment: assigned });
  } catch (error) {
    return createErrorResponseFromUnknown(error, "Failed to update assignment");
  }
}

import { z } from "zod";
import { deleteProxyById, listProxies } from "@/lib/db/proxies"
import { updateProxy } from "@/lib/localDb";
import { createErrorResponseFromUnknown } from "@/lib/api/errorResponse";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";
import { createProxyDispatcher, proxyConfigToUrl } from "@omniroute/open-sse/utils/proxyDispatcher";
import { fetch as undiciFetch } from "undici";
import { resolveHealthCheckStatusWrite } from "@/lib/proxyHealth/statusPolicy";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";
import { createErrorResponse } from "@/lib/api/errorResponse";

const TEST_TIMEOUT_MS = 5000;
// Reachability probe target. Configurable so operators can point it at an
// internal/self-hosted endpoint instead of the public default.
const TEST_URL = process.env.PROXY_HEALTH_TEST_URL || "https://httpbin.org/ip";
const CONCURRENCY = 10;

const autoTestSchema = z.object({
  ids: z.array(z.string()).optional(),
  autoRemove: z.boolean().optional().default(false),
});

interface TestResult {
  proxyId: string;
  host: string;
  port: number;
  alive: boolean;
  latencyMs: number | null;
  error?: string;
}

async function testSingleProxy(proxy: {
  id: string;
  type: string;
  host: string;
  port: number;
  username?: string;
  password?: string;
  family?: string;
}): Promise<TestResult> {
  let proxyUrl: string | null;
  try {
    proxyUrl = proxyConfigToUrl(proxy);
  } catch {
    proxyUrl = null;
  }
  if (!proxyUrl) {
    return {
      proxyId: proxy.id,
      host: proxy.host,
      port: proxy.port,
      alive: false,
      latencyMs: null,
      error: "Invalid proxy config (check type, host, port)",
    };
  }
  const start = Date.now();
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), TEST_TIMEOUT_MS);

  try {
    const dispatcher = createProxyDispatcher(proxyUrl);
    const resp = await undiciFetch(TEST_URL, {
      method: "HEAD",
      signal: controller.signal,
      dispatcher,
      headers: { "User-Agent": "OmniRoute/1.0" },
    });
    const latencyMs = Date.now() - start;
    const alive = resp.status < 500;
    // #6246: "Test All" is a test, not test-and-set. By default an automated probe
    // never mutates a proxy's status (only the operator does). Opt back into the
    // legacy write with PROXY_HEALTH_AUTO_DEACTIVATE=true.
    const statusWrite = resolveHealthCheckStatusWrite(alive);
    if (statusWrite) await updateProxy(proxy.id, { status: statusWrite }).catch(() => {});
    return { proxyId: proxy.id, host: proxy.host, port: proxy.port, alive, latencyMs };
  } catch (err) {
    const latencyMs = Date.now() - start;
    const statusWrite = resolveHealthCheckStatusWrite(false);
    if (statusWrite) await updateProxy(proxy.id, { status: statusWrite }).catch(() => {});
    return {
      proxyId: proxy.id,
      host: proxy.host,
      port: proxy.port,
      alive: false,
      latencyMs,
      error: err instanceof Error ? err.message : "Connection failed",
    };
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * POST /api/settings/proxies/auto-test
 * Tests proxy reachability. If autoRemove is true, removes dead proxies.
 */
export async function POST(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  let rawBody: unknown;
  try {
    rawBody = await request.json();
  } catch {
    rawBody = {};
  }

  const validation = validateBody(autoTestSchema, rawBody);
  if (isValidationFailure(validation)) {
    return createErrorResponse({
      status: 400,
      message: validation.error.message,
      type: "invalid_request",
    });
  }

  const { ids: specificIds, autoRemove } = validation.data;

  try {
    const result = await listProxies({ includeSecrets: true });
    const allProxies = result.items;
    const proxiesToTest = specificIds
      ? allProxies.filter((p) => specificIds.includes(p.id))
      : allProxies;

    if (proxiesToTest.length === 0) {
      return Response.json({ results: [], removed: [] });
    }

    const results: TestResult[] = [];
    for (let i = 0; i < proxiesToTest.length; i += CONCURRENCY) {
      const batch = proxiesToTest.slice(i, i + CONCURRENCY);
      const batchResults = await Promise.allSettled(batch.map((proxy) => testSingleProxy(proxy)));
      for (const result of batchResults) {
        if (result.status === "fulfilled") results.push(result.value);
      }
    }

    const removed: string[] = [];
    if (autoRemove) {
      for (const r of results) {
        if (!r.alive) {
          try {
            if (await deleteProxyById(r.proxyId, { force: true })) removed.push(r.proxyId);
          } catch {
            /* skip */
          }
        }
      }
    }

    return Response.json({
      tested: results.length,
      alive: results.filter((r) => r.alive).length,
      dead: results.filter((r) => !r.alive).length,
      removed: removed.length,
      results,
    });
  } catch (error) {
    return createErrorResponseFromUnknown(error, "Failed to auto-test proxies");
  }
}

import { z } from "zod";
import { updateProxy } from "@/lib/localDb";
import { createErrorResponse, createErrorResponseFromUnknown } from "@/lib/api/errorResponse";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";
import { clearDispatcherCache } from "@omniroute/open-sse/utils/proxyDispatcher";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";

const batchActivateSchema = z.object({
  ids: z.array(z.string()).min(1).max(500),
  // "active" (bulk enable) or "inactive" (bulk disable). Defaults to enable —
  // the #6246 ask was a way to re-enable proxies an operator had disabled.
  status: z.enum(["active", "inactive"]).optional().default("active"),
});

/**
 * POST /api/settings/proxies/batch-activate
 *
 * Bulk-set the status of multiple proxies in one request (#6246). This is the
 * ONLY automated path allowed to change proxy status — it is an explicit
 * operator action, unlike the reachability probes which are read-only by
 * default (see src/lib/proxyHealth/statusPolicy.ts).
 */
export async function POST(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  let rawBody: unknown;
  try {
    rawBody = await request.json();
  } catch {
    return createErrorResponse({ status: 400, message: "Invalid JSON body", type: "invalid_request" });
  }

  const validation = validateBody(batchActivateSchema, rawBody);
  if (isValidationFailure(validation)) {
    return createErrorResponse({ status: 400, message: validation.error.message, type: "invalid_request" });
  }

  const { ids, status } = validation.data;

  try {
    const results: Array<{ id: string; success: boolean; error?: string }> = [];
    let updatedCount = 0;

    for (const id of ids) {
      try {
        if (await updateProxy(id, { status })) {
          results.push({ id, success: true });
          updatedCount++;
        } else {
          results.push({ id, success: false, error: "Proxy not found" });
        }
      } catch (err) {
        results.push({ id, success: false, error: err instanceof Error ? err.message : "Unknown error" });
      }
    }

    if (updatedCount > 0) {
      try { clearDispatcherCache(); } catch { /* non-critical */ }
    }

    return Response.json({
      success: updatedCount > 0,
      status,
      updated: updatedCount,
      failed: ids.length - updatedCount,
      results,
    });
  } catch (error) {
    return createErrorResponseFromUnknown(error, "Failed to batch update proxy status");
  }
}

import { upsertProxy } from "@/lib/localDb";
import { bulkImportProxiesSchema } from "@/shared/validation/schemas";
import { isValidationFailure, validateBody } from "@/shared/validation/helpers";
import { createErrorResponse, createErrorResponseFromUnknown } from "@/lib/api/errorResponse";
import { requireManagementAuth } from "@/lib/api/requireManagementAuth";

export async function POST(request: Request) {
  const authError = await requireManagementAuth(request);
  if (authError) return authError;

  let rawBody: unknown;
  try {
    rawBody = await request.json();
  } catch {
    return createErrorResponse({
      status: 400,
      message: "Invalid JSON body",
      type: "invalid_request",
    });
  }

  try {
    const validation = validateBody(bulkImportProxiesSchema, rawBody);
    if (isValidationFailure(validation)) {
      return createErrorResponse({
        status: 400,
        message: validation.error.message,
        details: validation.error.details,
        type: "invalid_request",
      });
    }

    const { items } = validation.data;
    let created = 0;
    let updated = 0;
    let failed = 0;
    const results: Array<{
      name: string;
      success: boolean;
      action?: "created" | "updated";
      id?: string;
      error?: string;
    }> = [];

    for (const item of items) {
      try {
        const result = await upsertProxy(item);
        if (result.proxy) {
          if (result.action === "created") created++;
          else updated++;
          results.push({
            name: item.name,
            success: true,
            action: result.action,
            id: result.proxy.id,
          });
        } else {
          failed++;
          results.push({ name: item.name, success: false, error: "Unknown error" });
        }
      } catch (error) {
        failed++;
        results.push({
          name: item.name,
          success: false,
          error: error instanceof Error ? error.message : "Unknown error",
        });
      }
    }

    return Response.json({ created, updated, failed, results });
  } catch (error) {
    return createErrorResponseFromUnknown(error, "Failed to bulk import proxies");
  }
}

