function toStringOrNull(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : null;
}

function toNumberOrNull(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

function toStringArray(value: unknown): string[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const normalized = value
    .map((item) => toStringOrNull(item))
    .filter((item): item is string => Boolean(item));
  return normalized.length > 0 ? normalized : undefined;
}

function getSourcePriority(source: BuilderModelSource): number {
  switch (source) {
    case "imported":
      return 0;
    case "system":
      return 1;
    case "custom":
      return 2;
    case "fallback":
      return 3;
    default:
      return 99;
  }
}

function getCompatibleProviderVisual(providerNodeType: string | null): ProviderVisual {
  if (providerNodeType === "openai-compatible") {
    return { icon: "api", color: "#10A37F", source: "provider-node" };
  }
  if (providerNodeType === "anthropic-compatible") {
    return { icon: "api", color: "#D97757", source: "provider-node" };
  }
  if (providerNodeType === "anthropic-compatible-cc") {
    return { icon: "smart_toy", color: "#D97757", source: "provider-node" };
  }
  return { icon: "api", color: "#6B7280", source: "provider-node" };
}

function getProviderVisual(
  providerId: string,
  providerNode: ProviderNodeLike | null
): ProviderVisual & { alias: string; providerType: string } {
  const providerEntry = AI_PROVIDERS[providerId];
  if (providerEntry) {
    return {
      alias: providerEntry.alias || providerEntry.id,
      providerType: providerEntry.id,
      icon: providerEntry.icon || "hub",
      color: providerEntry.color || "#6B7280",
      source: "system",
    };
  }

  const providerNodeType = toStringOrNull(providerNode?.type);
  const compatibleVisual = getCompatibleProviderVisual(providerNodeType);
  return {
    alias: toStringOrNull(providerNode?.prefix) || providerId,
    providerType: providerNodeType || providerId,
    ...compatibleVisual,
  };
}

function deriveConnectionStatus(connection: ProviderConnectionLike): BuilderConnectionStatus {
  if (connection.isActive === false) return "inactive";
  const rateLimitedUntil = toNumberOrNull(connection.rateLimitedUntil);
  if (typeof rateLimitedUntil === "number" && rateLimitedUntil > Date.now()) {
    return "rate-limited";
  }
  if (typeof connection.testStatus === "string" && /error|fail/i.test(connection.testStatus)) {
    return "error";
  }
  return "active";
}

/**
 * Expand a list of raw DB connection rows into `ComboBuilderConnectionOption` items.
 *
 * No-auth account providers (opencode, mimocode) pack multiple "accounts" as UUIDs in
 * `providerSpecificData.fingerprints` of a single DB row (#6087). This helper inflates
 * them: each fingerprint becomes a separate option labeled "Account N" with an id of
 * `${rowId}|fp|${fingerprint}` so the combo step can pin a specific account.
 * Rows without fingerprints are converted 1:1 via buildConnectionOption as before.
 */
export function expandConnectionOptions(
  connections: ProviderConnectionLike[]
): ComboBuilderConnectionOption[] {
  const result: ComboBuilderConnectionOption[] = [];
  for (const connection of connections) {
    const fingerprints = Array.isArray(connection.providerSpecificData?.fingerprints)
      ? (connection.providerSpecificData.fingerprints as unknown[]).filter(
          (fp): fp is string => typeof fp === "string" && fp.length > 0
        )
      : [];
    if (fingerprints.length > 0) {
      const baseStatus = deriveConnectionStatus(connection);
      const basePriority = typeof connection.priority === "number" ? connection.priority : 0;
      for (let i = 0; i < fingerprints.length; i++) {
        result.push({
          id: `${toStringOrNull(connection.id) || ""}|fp|${fingerprints[i]}`,
          label: `Account ${i + 1}`,
          type: toStringOrNull(connection.authType) || "unknown",
          status: baseStatus,
          priority: basePriority,
          isActive: connection.isActive !== false,
          defaultModel: toStringOrNull(connection.defaultModel),
          rateLimitedUntil: toNumberOrNull(connection.rateLimitedUntil),
          lastError: toStringOrNull(connection.lastError),
          lastTested: toStringOrNull(connection.lastTested),
        });
      }
    } else {
      const opt = buildConnectionOption(connection);
      if (opt) result.push(opt);
    }
  }
  return result;
}

function buildConnectionOption(
  connection: ProviderConnectionLike
): ComboBuilderConnectionOption | null {
  const id = toStringOrNull(connection.id);
  if (!id) return null;

  return {
    id,
    label: getAccountDisplayName(connection),
    type: toStringOrNull(connection.authType) || "unknown",
    status: deriveConnectionStatus(connection),
    priority: typeof connection.priority === "number" ? connection.priority : 0,
    isActive: connection.isActive !== false,
    defaultModel: toStringOrNull(connection.defaultModel),
    rateLimitedUntil: toNumberOrNull(connection.rateLimitedUntil),
    lastError: toStringOrNull(connection.lastError),
    lastTested: toStringOrNull(connection.lastTested),
  };
}

function addModelOption(
  modelMap: Map<string, ComboBuilderModelOption>,
  providerId: string,
  input: {
    id: string | null;
    name?: string | null;
    source: BuilderModelSource;
    supportedEndpoints?: string[];
    apiFormat?: string | null;
    contextLength?: number | null;
    outputTokenLimit?: number | null;
    supportsThinking?: boolean;
  }
) {
  const modelId = toStringOrNull(input.id);
  if (!modelId) return;
  if (getModelIsHidden(providerId, modelId)) return;

  const nextSourcePriority = getSourcePriority(input.source);
  const existing = modelMap.get(modelId);
  if (!existing) {
    modelMap.set(modelId, {
      id: modelId,
      qualifiedModel: `${providerId}/${modelId}`,
      name: toStringOrNull(input.name) || modelId,
      source: input.source,
      sources: [input.source],
      ...(input.supportedEndpoints && input.supportedEndpoints.length > 0
        ? { supportedEndpoints: input.supportedEndpoints }
        : {}),
      ...(toStringOrNull(input.apiFormat) ? { apiFormat: input.apiFormat || undefined } : {}),
      ...(typeof input.contextLength === "number" ? { contextLength: input.contextLength } : {}),
      ...(typeof input.outputTokenLimit === "number"
        ? { outputTokenLimit: input.outputTokenLimit }
        : {}),
      ...(typeof input.supportsThinking === "boolean"
        ? { supportsThinking: input.supportsThinking }
        : {}),
    });
    return;
  }

  const existingPriority = getSourcePriority(existing.source);
  const mergedSources = new Set<BuilderModelSource>([...existing.sources, input.source]);

  if (nextSourcePriority < existingPriority) {
    existing.source = input.source;
  }
  if (!existing.name || existing.name === existing.id) {
    existing.name = toStringOrNull(input.name) || existing.name;
  }
  if (!existing.supportedEndpoints && input.supportedEndpoints?.length) {
    existing.supportedEndpoints = input.supportedEndpoints;
  }
  if (!existing.apiFormat && toStringOrNull(input.apiFormat)) {
    existing.apiFormat = input.apiFormat || undefined;
  }
  if (existing.contextLength == null && typeof input.contextLength === "number") {
    existing.contextLength = input.contextLength;
  }
  if (existing.outputTokenLimit == null && typeof input.outputTokenLimit === "number") {
    existing.outputTokenLimit = input.outputTokenLimit;
  }
  if (existing.supportsThinking == null && typeof input.supportsThinking === "boolean") {
    existing.supportsThinking = input.supportsThinking;
  }
  existing.sources = Array.from(mergedSources).sort(
    (left, right) => getSourcePriority(left) - getSourcePriority(right)
  );
}

function buildModelOptions(
  providerId: string,
  builtInModels: RegistryModel[],
  syncedModels: SyncedModelLike[],
  customModels: CustomModelLike[]
): Map<string, ComboBuilderModelOption> {
  const modelMap = new Map<string, ComboBuilderModelOption>();
  const fallbackModels = getCompatibleFallbackModels(providerId, builtInModels);

  for (const model of syncedModels) {
    const resolved = getResolvedModelCapabilities({
      provider: providerId,
      model: toStringOrNull(model.id),
    });
    addModelOption(modelMap, providerId, {
      id: toStringOrNull(model.id),
      name: toStringOrNull(model.name),
      source: "imported",
      supportedEndpoints: toStringArray(model.supportedEndpoints),
      contextLength: toNumberOrNull(model.inputTokenLimit) ?? resolved.contextWindow,
      outputTokenLimit: toNumberOrNull(model.outputTokenLimit) ?? resolved.maxOutputTokens,
      supportsThinking:
        typeof model.supportsThinking === "boolean"
          ? model.supportsThinking
          : (resolved.supportsThinking ?? undefined),
    });
  }

  // #8072: expose reasoning-effort variants (e.g. model-high, model-medium)
  // in the Combo Builder picker, matching the catalog/Playground behaviour.
  // Convert synced models with supportedThinkingEfforts into catalog-shaped
  // entries, run the shared appendSyncedEffortVariants utility, and add any
  // new variant ids that aren't already in the model map.
  const catalogShaped = syncedModels
    .filter(
      (m): m is SyncedModelLike & { id: string; supportedThinkingEfforts: string[] } =>
        typeof m.id === "string" &&
        Array.isArray(m.supportedThinkingEfforts) &&
        m.supportedThinkingEfforts.length > 0
    )
    .map((m) => ({
      id: `${providerId}/${m.id}`,
      owned_by: providerId,
      root: m.id,
      name: m.name || m.id,
      capabilities: { effort_tiers: m.supportedThinkingEfforts },
    }));
  if (catalogShaped.length > 0) {
    // Track each tier variant's true base model id (the synced model's own raw,
    // unsuffixed id) directly while iterating tiers here. We can't re-derive the
    // base id from `variant.root` after calling appendSyncedEffortVariants: that
    // utility sets a variant's `root` to `${baseRoot}-${tier}` (still tier-suffixed,
    // see open-sse/utils/syncedEffortVariants.ts), not the base model id, so a
    // lookup keyed on it never matches an entry in modelMap and variants silently
    // fail to inherit contextLength/outputTokenLimit/supportedEndpoints/supportsThinking.
    const baseRawIdByVariantId = new Map<string, string>();
    for (const shaped of catalogShaped) {
      for (const tier of shaped.capabilities.effort_tiers) {
        if (typeof tier === "string" && tier.length > 0) {
          baseRawIdByVariantId.set(`${shaped.id}-${tier}`, shaped.root);
        }
      }
    }

    const withVariants = appendSyncedEffortVariants(catalogShaped);
    for (const variant of withVariants) {
      if (typeof variant.id !== "string") continue;
      // Strip the provider prefix to get the raw model id for the builder
      const rawId = variant.id.startsWith(`${providerId}/`)
        ? variant.id.slice(providerId.length + 1)
        : variant.id;
      if (modelMap.has(rawId)) continue;
      const baseId = baseRawIdByVariantId.get(variant.id) ?? rawId;
      const base = modelMap.get(baseId);
      addModelOption(modelMap, providerId, {
        id: rawId,
        name: base ? `${base.name} (${rawId.slice(baseId.length + 1)})` : rawId,
        source: "imported",
        supportedEndpoints: base?.supportedEndpoints,
        contextLength: base?.contextLength ?? null,
        outputTokenLimit: base?.outputTokenLimit ?? null,
        supportsThinking: base?.supportsThinking,
      });
    }
  }

  for (const model of builtInModels) {
    const resolved = getResolvedModelCapabilities({
      provider: providerId,
      model: toStringOrNull(model.id),
    });
    addModelOption(modelMap, providerId, {
      id: toStringOrNull(model.id),
      name: toStringOrNull(model.name),
      source: "system",
      contextLength: toNumberOrNull(model.contextLength) ?? resolved.contextWindow,
      outputTokenLimit: resolved.maxOutputTokens,
      supportsThinking: resolved.supportsThinking ?? undefined,
    });
  }

  // #9485: static registry models can declare provider-specific effort tiers even
  // when a connection's synced row does not include supportedThinkingEfforts.
  // Feed those declarations through the same catalog variant utility, while
  // copying the merged base option so aliases retain its metadata and source.
  const staticCatalogShaped = builtInModels
    .filter(
      (m): m is RegistryModel & { supportedThinkingEfforts: readonly string[] } =>
        typeof m.id === "string" &&
        Array.isArray(m.supportedThinkingEfforts) &&
        m.supportedThinkingEfforts.length > 0
    )
    .map((m) => ({
      id: `${providerId}/${m.id}`,
      owned_by: providerId,
      root: m.id,
      name: m.name,
      capabilities: { effort_tiers: m.supportedThinkingEfforts },
    }));
  if (staticCatalogShaped.length > 0) {
    const baseRawIdByVariantId = new Map<string, string>();
    for (const shaped of staticCatalogShaped) {
      for (const tier of shaped.capabilities.effort_tiers) {
        if (typeof tier === "string" && tier.length > 0) {
          baseRawIdByVariantId.set(`${shaped.id}-${tier}`, shaped.root);
        }
      }
    }

    const withVariants = appendSyncedEffortVariants(staticCatalogShaped);
    for (const variant of withVariants) {
      if (typeof variant.id !== "string") continue;
      const rawId = variant.id.startsWith(`${providerId}/`)
        ? variant.id.slice(providerId.length + 1)
        : variant.id;
      if (modelMap.has(rawId)) continue;
      const baseId = baseRawIdByVariantId.get(variant.id) ?? rawId;
      const base = modelMap.get(baseId);
      addModelOption(modelMap, providerId, {
        id: rawId,
        name: base ? `${base.name} (${rawId.slice(baseId.length + 1)})` : rawId,
        source: base?.source ?? "system",
        supportedEndpoints: base?.supportedEndpoints,
        contextLength: base?.contextLength ?? null,
        outputTokenLimit: base?.outputTokenLimit ?? null,
        supportsThinking: base?.supportsThinking,
      });
    }
  }

  for (const model of customModels) {
    if (model.isHidden === true) continue;
    const source = ["api-sync", "auto-sync", "imported"].includes(
      toStringOrNull(model.source)?.toLowerCase() || ""
    )
      ? "imported"
      : ("custom" as BuilderModelSource);
    const resolved = getResolvedModelCapabilities({
      provider: providerId,
      model: toStringOrNull(model.id),
    });
    addModelOption(modelMap, providerId, {
      id: toStringOrNull(model.id),
      name: toStringOrNull(model.name),
      source,
      supportedEndpoints: toStringArray(model.supportedEndpoints),
      apiFormat: toStringOrNull(model.apiFormat),
      contextLength: toNumberOrNull(model.inputTokenLimit) ?? resolved.contextWindow,
      outputTokenLimit: toNumberOrNull(model.outputTokenLimit) ?? resolved.maxOutputTokens,
      supportsThinking:
        typeof model.supportsThinking === "boolean"
          ? model.supportsThinking
          : (resolved.supportsThinking ?? undefined),
    });
  }

  if (Array.isArray(fallbackModels)) {
    for (const model of fallbackModels) {
      const resolved = getResolvedModelCapabilities({
        provider: providerId,
        model: toStringOrNull(model.id),
      });
      addModelOption(modelMap, providerId, {
        id: toStringOrNull(model.id),
        name: toStringOrNull(model.name),
        source: "fallback",
        contextLength:
          typeof (model as { contextLength?: number }).contextLength === "number"
            ? (model as { contextLength?: number }).contextLength || null
            : resolved.contextWindow,
        outputTokenLimit: resolved.maxOutputTokens,
        supportsThinking: resolved.supportsThinking ?? undefined,
      });
    }
  }

  disambiguateCollidingModelNames(modelMap);
  return modelMap;
}

/**
 * #6957: some providers' own catalogs assign the identical display `name` to
 * several distinct model ids (e.g. Mistral's "codestral-latest" alias renders
 * under the same upstream name as its base "codestral-2508" model). Since the
 * builder picker renders `model.name` as the visible option text, two colliding
 * names make genuinely different models look like duplicates and hide aliases.
 * Run this after all merge loops have populated `modelMap`: for any name shared
 * by 2+ distinct ids, fall back every entry in that group to its own `id` as the
 * display name (display-only — `id`/`qualifiedModel` used for routing untouched).
 */
function disambiguateCollidingModelNames(modelMap: Map<string, ComboBuilderModelOption>): void {
  const idsByName = new Map<string, string[]>();
  for (const option of modelMap.values()) {
    const bucket = idsByName.get(option.name) || [];
    bucket.push(option.id);
    idsByName.set(option.name, bucket);
  }
  for (const [name, ids] of idsByName) {
    if (ids.length < 2) continue;
    for (const id of ids) {
      const option = modelMap.get(id);
      if (option && option.name === name) option.name = option.id;
    }
  }
}

function compareConnections(
  left: ComboBuilderConnectionOption,
  right: ComboBuilderConnectionOption
): number {
  if (left.isActive !== right.isActive) return left.isActive ? -1 : 1;
  if (left.priority !== right.priority) return left.priority - right.priority;
  return left.label.localeCompare(right.label, undefined, { sensitivity: "base" });
}

function compareModels(left: ComboBuilderModelOption, right: ComboBuilderModelOption): number {
  const sourceDelta = getSourcePriority(left.source) - getSourcePriority(right.source);
  if (sourceDelta !== 0) return sourceDelta;
  const nameDelta = left.name.localeCompare(right.name, undefined, { sensitivity: "base" });
  if (nameDelta !== 0) return nameDelta;
  return left.id.localeCompare(right.id, undefined, { sensitivity: "base" });
}

function compareProviders(
  left: ComboBuilderProviderOption,
  right: ComboBuilderProviderOption
): number {
  if (left.activeConnectionCount !== right.activeConnectionCount) {
    return right.activeConnectionCount - left.activeConnectionCount;
  }
  return left.displayName.localeCompare(right.displayName, undefined, { sensitivity: "base" });
}

function normalizeCustomModels(raw: unknown): CustomModelLike[] {
  return Array.isArray(raw)
    ? raw.filter(
        (model): model is CustomModelLike =>
          Boolean(model) && typeof model === "object" && !Array.isArray(model)
      )
    : [];
}

function normalizeSyncedModels(raw: unknown): SyncedModelLike[] {
  return Array.isArray(raw)
    ? raw.filter(
        (model): model is SyncedModelLike =>
          Boolean(model) && typeof model === "object" && !Array.isArray(model)
      )
    : [];
}

export async function getComboBuilderOptions(): Promise<ComboBuilderOptionsPayload> {
  getSyncedCapabilities();
  const [connections, providerNodes, customModelsMap, syncedModelsMap, combos, settings] =
    await Promise.all([
      getProviderConnections(),
      getProviderNodes(),
      getAllCustomModels(),
      getAllSyncedAvailableModels(),
      getCombos(),
      getSettings().catch(() => ({}) as Record<string, unknown>),
    ]);
  const blockedProviders = new Set(
    Array.isArray((settings as Record<string, unknown>).blockedProviders)
      ? ((settings as Record<string, unknown>).blockedProviders as string[])
      : []
  );

  const providerNodeMap = new Map<string, ProviderNodeLike>();
  for (const providerNode of providerNodes as ProviderNodeLike[]) {
    const providerId = toStringOrNull(providerNode.id);
    if (!providerId) continue;
    providerNodeMap.set(providerId, providerNode);
  }

  const connectionsByProvider = new Map<string, ProviderConnectionLike[]>();
  for (const connection of connections as ProviderConnectionLike[]) {
    const providerId = toStringOrNull(connection.provider);
    if (!providerId) continue;
    const list = connectionsByProvider.get(providerId) || [];
    list.push(connection);
    connectionsByProvider.set(providerId, list);
  }

  const providers: ComboBuilderProviderOption[] = [];

  for (const [providerId, providerConnections] of connectionsByProvider) {
    const providerNode = providerNodeMap.get(providerId) || null;
    const providerVisual = getProviderVisual(providerId, providerNode);
    const builtInModels = getModelsByProviderId(providerId);
    const syncedModels = normalizeSyncedModels(
      (syncedModelsMap as Record<string, unknown>)[providerId]
    );
    const customModels = normalizeCustomModels(
      (customModelsMap as Record<string, unknown>)[providerId]
    );
    const acceptsArbitraryModel =
      Boolean((AI_PROVIDERS[providerId] as JsonRecord | undefined)?.passthroughModels) ||
      isOpenAICompatibleProvider(providerId) ||
      isAnthropicCompatibleProvider(providerId) ||
      isClaudeCodeCompatibleProvider(providerId);
    const modelMap = buildModelOptions(
      providerId,
      builtInModels as RegistryModel[],
      syncedModels,
      customModels
    );

    const normalizedConnections =
      expandConnectionOptions(providerConnections).sort(compareConnections);

    const activeConnectionCount = normalizedConnections.filter(
      (connection) => connection.isActive
    ).length;
    const displayName = (providerEntryName(providerId) ||
      getProviderDisplayName(providerId, providerNode) ||
      providerId) as string;

    providers.push({
      providerId,
      providerType: providerVisual.providerType,
      displayName,
      alias: providerVisual.alias,
      prefix: toStringOrNull(providerNode?.prefix),
      icon: providerVisual.icon,
      color: providerVisual.color,
      source: providerVisual.source,
      acceptsArbitraryModel,
      connectionCount: normalizedConnections.length,
      activeConnectionCount,
      modelCount: modelMap.size,
      connections: normalizedConnections,
      models: Array.from(modelMap.values()).sort(compareModels),
    });
  }

  // No-auth providers have no rows in provider_connections, so they are never included in the
  // connectionsByProvider loop above. Add them unless the provider is explicitly blocked.
  for (const noAuthProvider of Object.values(NOAUTH_PROVIDERS)) {
    const providerId = noAuthProvider.id;
    if (
      blockedProviders.has(providerId) ||
      (typeof noAuthProvider.alias === "string" && blockedProviders.has(noAuthProvider.alias))
    )
      continue;
    // Skip if already covered (defensive: shouldn't happen for true no-auth providers)
    if (connectionsByProvider.has(providerId)) continue;

    const providerVisual = getProviderVisual(providerId, null);
    const builtInModels = getModelsByProviderId(providerId);
    const syncedModels = normalizeSyncedModels(
      (syncedModelsMap as Record<string, unknown>)[providerId]
    );
    const customModels = normalizeCustomModels(
      (customModelsMap as Record<string, unknown>)[providerId]
    );
    const acceptsArbitraryModel =
      Boolean((AI_PROVIDERS[providerId] as JsonRecord | undefined)?.passthroughModels) ||
      isOpenAICompatibleProvider(providerId) ||
      isAnthropicCompatibleProvider(providerId) ||
      isClaudeCodeCompatibleProvider(providerId);
    const modelMap = buildModelOptions(
      providerId,
      builtInModels as RegistryModel[],
      syncedModels,
      customModels
    );

    // #2901: no-auth providers must route under their alias (e.g. "oc"), not
    // their id — "opencode/<model>" misroutes to the opencode-zen api-key tier
    // (manual ALIAS_TO_PROVIDER_ID override), while "oc/<model>" resolves to the
    // no-auth "opencode" provider. Rewrite qualifiedModel to the alias prefix.
    const routingPrefix = noAuthProvider.alias || providerId;
    if (routingPrefix !== providerId) {
      for (const opt of modelMap.values()) {
        opt.qualifiedModel = `${routingPrefix}/${opt.id}`;
      }
    }

    const displayName = (providerEntryName(providerId) ||
      getProviderDisplayName(providerId, null) ||
      providerId) as string;

    providers.push({
      providerId,
      providerType: providerVisual.providerType,
      displayName,
      alias: providerVisual.alias,
      prefix: null,
      icon: providerVisual.icon,
      color: providerVisual.color,
      source: providerVisual.source,
      acceptsArbitraryModel,
      connectionCount: 0,
      activeConnectionCount: 0,
      modelCount: modelMap.size,
      connections: [],
      models: Array.from(modelMap.values()).sort(compareModels),
    });
  }

  const comboRefs = (combos as JsonRecord[])
    .filter((combo) => combo.isHidden !== true && combo.isActive !== false)
    .map((combo) => ({
      id: toStringOrNull(combo.id) || toStringOrNull(combo.name) || "combo",
      name: toStringOrNull(combo.name) || "combo",
      strategy: toStringOrNull(combo.strategy) || "priority",
      stepCount: Array.isArray(combo.models) ? combo.models.length : 0,
      version: typeof combo.version === "number" ? combo.version : 2,
      ...(typeof combo.sortOrder === "number" ? { sortOrder: combo.sortOrder } : {}),
    }))
    .sort((left, right) => {
      const leftSort =
        typeof left.sortOrder === "number" ? left.sortOrder : Number.MAX_SAFE_INTEGER;
      const rightSort =
        typeof right.sortOrder === "number" ? right.sortOrder : Number.MAX_SAFE_INTEGER;
      if (leftSort !== rightSort) return leftSort - rightSort;
      return left.name.localeCompare(right.name, undefined, { sensitivity: "base" });
    });

  return {
    schemaVersion: 2,
    generatedAt: new Date().toISOString(),
    providers: providers.sort(compareProviders),
    comboRefs,
  };
}

function providerEntryName(providerId: string): string | null {
  const providerEntry = AI_PROVIDERS[providerId] as { name?: string } | undefined;
  return toStringOrNull(providerEntry?.name);
}

import { normalizeComboModels, type ComboStep } from "./steps";

type JsonRecord = Record<string, unknown>;

export type ComboControlCenterHealthState = "healthy" | "warning" | "critical" | "idle";

export interface ComboControlCenterCombo {
  id?: string;
  name?: string;
  strategy?: string | null;
  models?: unknown[];
  isActive?: boolean | null;
  config?: JsonRecord | null;
}

export interface ComboControlCenterMetrics {
  totalRequests?: number;
  totalSuccesses?: number;
  totalFailures?: number;
  totalFallbacks?: number;
  avgLatencyMs?: number;
  successRate?: number;
  fallbackRate?: number;
  lastUsedAt?: string | null;
}

export interface ComboControlCenterHealth {
  performance?: {
    avgLatencyMs?: number;
    successRate?: number;
    totalRequests?: number;
  };
  quotaHealth?: {
    worstRemainingPct?: number;
    providers?: Array<{
      provider: string;
      remainingPct: number;
      isExhausted: boolean;
      trend: "improving" | "stable" | "declining";
    }>;
  };
  usageSkew?: {
    giniCoefficient?: number;
    modelDistribution?: Array<{ model: string; requestShare: number; tokenShare: number }>;
  };
  targetHealth?: ComboControlCenterTargetHealth[];
}

export interface ComboControlCenterTargetHealth {
  executionKey?: string;
  stepId?: string | null;
  model?: string;
  provider?: string;
  connectionId?: string | null;
  label?: string | null;
  requests?: number;
  successRate?: number;
  avgLatencyMs?: number;
  lastStatus?: "ok" | "error" | null;
  lastUsedAt?: string | null;
  quotaRemainingPct?: number | null;
  quotaIsExhausted?: boolean | null;
  quotaTrend?: "improving" | "stable" | "declining" | null;
  quotaScope?: "connection" | "provider" | "none";
}

export interface ComboControlCenterTarget {
  id: string;
  kind: "model" | "combo-ref" | "provider-wildcard";
  index: number;
  label: string;
  model: string;
  provider: string | null;
  connectionId: string | null;
  weight: number;
  tags: string[];
  health: ComboControlCenterTargetHealth | null;
}

export interface ComboControlCenterSummary {
  strategy: string;
  isActive: boolean;
  targetCount: number;
  modelTargetCount: number;
  nestedComboCount: number;
  providerCount: number;
  totalRequests: number;
  successRate: number;
  avgLatencyMs: number;
  fallbackRate: number;
  worstQuotaRemainingPct: number | null;
  usageSkew: number;
  healthState: ComboControlCenterHealthState;
  healthReasons: string[];
}

function isRecord(value: unknown): value is JsonRecord {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function toNumber(value: unknown, fallback = 0): number {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

function toString(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : null;
}

function providerFromModel(model: string | null | undefined): string | null {
  if (!model) return null;
  const slashIndex = model.indexOf("/");
  if (slashIndex <= 0) return null;
  return model.slice(0, slashIndex);
}

function normalizeSuccessRate(value: unknown): number {
  const rate = toNumber(value, 0);
  if (rate <= 1) return Math.round(rate * 100);
  return Math.round(rate);
}

function getMetricRequests(metrics?: ComboControlCenterMetrics | null): number {
  return toNumber(metrics?.totalRequests, 0);
}

function getHealthRequests(health?: ComboControlCenterHealth | null): number {
  return toNumber(health?.performance?.totalRequests, 0);
}

function getStepTags(step: ComboStep): string[] {
  return step.kind === "model" && Array.isArray(step.tags) ? step.tags : [];
}

function getStepLabel(step: ComboStep): string {
  if (step.label) return step.label;
  if (step.kind === "combo-ref") return `Combo → ${step.comboName}`;
  if (step.kind === "provider-wildcard") {
    return `All ${step.providerId}/${step.modelPattern}`;
  }
  return step.model;
}

export function getComboControlCenterTargets(
  combo: ComboControlCenterCombo,
  health?: ComboControlCenterHealth | null
): ComboControlCenterTarget[] {
  const steps = normalizeComboModels(combo.models || [], { comboName: combo.name || null });
  const healthByStepId = new Map<string, ComboControlCenterTargetHealth>();
  const healthByModel = new Map<string, ComboControlCenterTargetHealth>();

  for (const target of health?.targetHealth || []) {
    const stepId = toString(target.stepId);
    const model = toString(target.model);
    if (stepId) healthByStepId.set(stepId, target);
    if (model && !healthByModel.has(model)) healthByModel.set(model, target);
  }

  return steps.map((step, index) => {
    const model =
      step.kind === "combo-ref"
        ? step.comboName
        : step.kind === "provider-wildcard"
          ? `${step.providerId}/${step.modelPattern}`
          : step.model;
    const healthEntry = healthByStepId.get(step.id) || healthByModel.get(model) || null;
    const provider =
      step.kind === "model"
        ? step.providerId || providerFromModel(step.model) || healthEntry?.provider || null
        : step.kind === "provider-wildcard"
          ? step.providerId
          : null;

    return {
      id: step.id,
      kind: step.kind,
      index,
      label: getStepLabel(step),
      model,
      provider,
      connectionId:
        step.kind === "model" || step.kind === "provider-wildcard"
          ? step.connectionId || null
          : null,
      weight: step.weight || 0,
      tags: getStepTags(step),
      health: healthEntry,
    };
  });
}

export function getResolvedComboControlCenterTargets(
  health?: ComboControlCenterHealth | null
): ComboControlCenterTargetHealth[] {
  return Array.isArray(health?.targetHealth) ? health.targetHealth : [];
}

export function summarizeComboControlCenter(
  combo: ComboControlCenterCombo,
  metrics?: ComboControlCenterMetrics | null,
  health?: ComboControlCenterHealth | null
): ComboControlCenterSummary {
  const targets = getComboControlCenterTargets(combo, health);
  const resolvedTargets = getResolvedComboControlCenterTargets(health);
  const providers = new Set<string>();
  for (const target of targets) {
    if (target.provider) providers.add(target.provider);
  }
  for (const target of resolvedTargets) {
    const provider = toString(target.provider);
    if (provider) providers.add(provider);
  }

  const healthRequests = getHealthRequests(health);
  const metricRequests = getMetricRequests(metrics);
  const totalRequests = healthRequests || metricRequests;
  const successRate =
    healthRequests > 0
      ? normalizeSuccessRate(health?.performance?.successRate)
      : normalizeSuccessRate(metrics?.successRate);
  const avgLatencyMs =
    toNumber(health?.performance?.avgLatencyMs, 0) || toNumber(metrics?.avgLatencyMs, 0);
  const fallbackRate = normalizeSuccessRate(metrics?.fallbackRate);
  const worstQuotaRemainingPct =
    typeof health?.quotaHealth?.worstRemainingPct === "number"
      ? health.quotaHealth.worstRemainingPct
      : null;
  const usageSkew = toNumber(health?.usageSkew?.giniCoefficient, 0);
  const hasExhaustedQuota = Boolean(
    health?.quotaHealth?.providers?.some((provider) => provider.isExhausted)
  );

  const healthReasons: string[] = [];
  if (totalRequests === 0) healthReasons.push("No recent combo traffic");
  if (successRate > 0 && successRate < 80) healthReasons.push("Low success rate");
  else if (successRate > 0 && successRate < 95) healthReasons.push("Success rate below target");
  if (fallbackRate >= 20) healthReasons.push("High fallback rate");
  else if (fallbackRate >= 10) healthReasons.push("Elevated fallback rate");
  if (hasExhaustedQuota) healthReasons.push("At least one quota is exhausted");
  else if (worstQuotaRemainingPct !== null && worstQuotaRemainingPct < 10) {
    healthReasons.push("Quota is nearly exhausted");
  } else if (worstQuotaRemainingPct !== null && worstQuotaRemainingPct < 25) {
    healthReasons.push("Quota is getting low");
  }
  if (usageSkew >= 0.5) healthReasons.push("Traffic distribution is highly skewed");

  let healthState: ComboControlCenterHealthState = "healthy";
  if (totalRequests === 0 && worstQuotaRemainingPct === null) {
    healthState = "idle";
  } else if (
    hasExhaustedQuota ||
    (successRate > 0 && successRate < 80) ||
    (worstQuotaRemainingPct !== null && worstQuotaRemainingPct < 10)
  ) {
    healthState = "critical";
  } else if (
    (successRate > 0 && successRate < 95) ||
    fallbackRate >= 10 ||
    (worstQuotaRemainingPct !== null && worstQuotaRemainingPct < 25) ||
    usageSkew >= 0.5
  ) {
    healthState = "warning";
  }

  return {
    strategy: combo.strategy || "priority",
    isActive: combo.isActive !== false,
    targetCount: targets.length,
    modelTargetCount: targets.filter(
      (target) => target.kind === "model" || target.kind === "provider-wildcard"
    ).length,
    nestedComboCount: targets.filter((target) => target.kind === "combo-ref").length,
    providerCount: providers.size,
    totalRequests,
    successRate,
    avgLatencyMs,
    fallbackRate,
    worstQuotaRemainingPct,
    usageSkew,
    healthState,
    healthReasons: healthReasons.length > 0 ? healthReasons : ["Combo looks healthy"],
  };
}

export function extractComboRuntimeConfig(combo: ComboControlCenterCombo): JsonRecord {
  return isRecord(combo.config) ? combo.config : {};
}

import { getExecutor } from "@omniroute/open-sse/executors/index";
import type { ExecuteInput, ProviderCredentials } from "@omniroute/open-sse/executors/base";
import type {
  ChatTurn,
  ModelCallResult,
  ModelClient,
} from "@omniroute/open-sse/services/compression/eval/types";
import { calculateCost } from "@/lib/usage/costCalculator";

/**
 * Cost-aware judge ModelClient for the compression playground's fidelity verify.
 * Hard Rule #18 — NOT unit-tested (touches the real executor); the cost math is calculateCost
 * (already covered) and the cap logic is judgeFidelityBatch (unit-tested with a stub). Computes
 * usdCost from FULL usage (prompt + completion tokens) via the canonical pricing engine, so the
 * USD cap actually engages and totalUsd is real.
 */
export function createPricedJudgeClient(
  provider: string,
  credentials: ProviderCredentials
): ModelClient {
  const executor = getExecutor(provider);
  return {
    async complete(model: string, messages: ChatTurn[]): Promise<ModelCallResult> {
      const input: ExecuteInput = {
        model,
        body: { model, messages, stream: false },
        stream: false,
        credentials,
      };
      const raw = (await executor.execute(input)) as { response: Response };
      const json = (await raw.response.json()) as {
        choices?: Array<{ message?: { content?: string } }>;
        usage?: { prompt_tokens?: number; completion_tokens?: number };
      };
      const text = json.choices?.[0]?.message?.content ?? "";
      const usdCost = await calculateCost(provider, model, {
        prompt_tokens: json.usage?.prompt_tokens,
        completion_tokens: json.usage?.completion_tokens,
      });
      return usdCost > 0 ? { text, usdCost } : { text };
    },
  };
}

/**
 * Simple DI Container — Factory-pattern service locator
 *
 * Provides a lightweight dependency injection container using factory
 * functions (no heavy frameworks). Services are lazily instantiated
 * and cached as singletons.
 *
 * Usage:
 *   import { container } from '@/lib/container';
 *   const settings = container.resolve('settings');
 *
 * Registration:
 *   container.register('myService', () => new MyService());
 *
 * @module lib/container
 */

import { evaluateFirstAllowed, evaluateRequest, PolicyEngine } from "../domain/policyEngine.ts";
import { getDbInstance } from "./db/core.ts";
import {
  decrypt,
  decryptConnectionFields,
  encrypt,
  encryptConnectionFields,
} from "./db/encryption.ts";
import { getSettings } from "./localDb.ts";
import { getCircuitBreaker } from "../shared/utils/circuitBreaker.ts";
import { recordTelemetry, RequestTelemetry } from "../shared/utils/requestTelemetry.ts";

type Factory<T = any> = () => T;

class Container {
  private _factories = new Map<string, Factory>();
  private _instances = new Map<string, any>();

  /**
   * Register a factory for a service. Does NOT instantiate until resolve().
   */
  register<T>(name: string, factory: Factory<T>): void {
    this._factories.set(name, factory);
    // Clear cached instance if re-registering (useful for testing)
    this._instances.delete(name);
  }

  /**
   * Resolve a service by name. Lazy-creates via factory on first call,
   * then returns the cached singleton.
   */
  resolve<T = any>(name: string): T {
    if (this._instances.has(name)) {
      return this._instances.get(name) as T;
    }

    const factory = this._factories.get(name);
    if (!factory) {
      throw new Error(`[Container] No factory registered for "${name}"`);
    }

    const instance = factory();
    this._instances.set(name, instance);
    return instance as T;
  }

  /**
   * Check if a service is registered (factory exists).
   */
  has(name: string): boolean {
    return this._factories.has(name);
  }

  /**
   * List all registered service names.
   */
  list(): string[] {
    return Array.from(this._factories.keys());
  }

  /**
   * Reset all factories and instances (for testing).
   */
  reset(): void {
    this._factories.clear();
    this._instances.clear();
  }
}

// ── Singleton container instance ──
export const container = new Container();

// ── Default registrations ──
// Services are still lazily instantiated on first resolve().

container.register("settings", () => {
  return { get: getSettings };
});

container.register("db", () => {
  return getDbInstance();
});

container.register("encryption", () => {
  return {
    encrypt,
    decrypt,
    encryptConnectionFields,
    decryptConnectionFields,
  };
});

container.register("policyEngine", () => {
  return { evaluateRequest, evaluateFirstAllowed, PolicyEngine };
});

container.register("circuitBreaker", () => {
  return { get: getCircuitBreaker };
});

container.register("telemetry", () => {
  return { RequestTelemetry, recordTelemetry };
});

export default container;

/**
 * Eval Runner — T-42
 *
 * Framework for evaluating LLM responses against a golden set.
 * Supports multiple evaluation strategies: exact match, contains,
 * regex, and custom functions.
 *
 * @module lib/evals/evalRunner
 */

import { getCustomEvalSuite, listCustomEvalSuites } from "@/lib/db/evals";
import {
  goldenSet,
  codingSuite,
  reasoningSuite,
  multilingualSuite,
  safetySuite,
  instructionSuite,
  codexComparisonSuite,
  builtInSuites,
} from "./evalRunner/builtinSuites";

/**
 * @typedef {Object} EvalCase
 * @property {string} id - Unique case ID
 * @property {string} name - Human-readable name
 * @property {string} model - Target model
 * @property {Object} input - Request input (messages, etc.)
 * @property {Object} expected - Expected output criteria
 * @property {string} expected.strategy - "exact" | "contains" | "regex" | "custom"
 * @property {string|RegExp} [expected.value] - Expected value for match strategies
 * @property {Function} [expected.fn] - Custom evaluation function
 * @property {string[]} [tags] - Tags for filtering
 */

/**
 * @typedef {Object} EvalResult
 * @property {string} caseId
 * @property {string} caseName
 * @property {boolean} passed
 * @property {number} durationMs
 * @property {string} [error]
 * @property {Object} [details]
 */

/**
 * @typedef {Object} EvalSuite
 * @property {string} id
 * @property {string} name
 * @property {EvalCase[]} cases
 * @property {string} [description]
 */

/** @type {Map<string, EvalSuite>} */
const suites = new Map();

/**
 * Register an evaluation suite.
 *
 * @param {EvalSuite} suite
 */
export function registerSuite(suite: any) {
  suites.set(suite.id, suite);
}

/**
 * Get a registered suite by ID.
 *
 * @param {string} suiteId
 * @returns {EvalSuite | null}
 */
export function getSuite(suiteId: string) {
  return suites.get(suiteId) || getCustomEvalSuite(suiteId) || null;
}

/**
 * List all registered suites.
 *
 * @returns {Array<{ id: string, name: string, caseCount: number }>}
 */
export function listSuites() {
  const builtInSuites = Array.from(suites.values()).map((s) => ({
    id: s.id,
    name: s.name,
    description: s.description || "",
    source: "built-in",
    caseCount: s.cases.length,
    cases: s.cases.map((c) => ({
      id: c.id,
      name: c.name,
      model: c.model,
      input: c.input,
      expected: c.expected,
      tags: c.tags || [],
    })),
  }));

  const customSuites = listCustomEvalSuites().map((suite) => ({
    id: suite.id,
    name: suite.name,
    description: suite.description || "",
    source: "custom",
    caseCount: suite.cases.length,
    updatedAt: suite.updatedAt,
    cases: suite.cases.map((c) => ({
      id: c.id,
      name: c.name,
      model: c.model,
      input: c.input,
      expected: c.expected,
      tags: c.tags || [],
    })),
  }));

  return [...builtInSuites, ...customSuites];
}

/**
 * Evaluate a single case against actual output.
 *
 * @param {EvalCase} evalCase
 * @param {string} actualOutput - The actual LLM response text
 * @returns {EvalResult}
 */
export function evaluateCase(evalCase: any, actualOutput: string) {
  const start = Date.now();

  try {
    let passed = false;
    const details: Record<string, any> = {};
    details.actualSnippet =
      typeof actualOutput === "string" ? actualOutput.slice(0, 240) : String(actualOutput ?? "");

    switch (evalCase.expected.strategy) {
      case "exact":
        passed = actualOutput === evalCase.expected.value;
        details.expected = evalCase.expected.value;
        details.actual = actualOutput;
        break;

      case "contains":
        passed =
          typeof evalCase.expected.value === "string" &&
          actualOutput.toLowerCase().includes(evalCase.expected.value.toLowerCase());
        details.searchTerm = evalCase.expected.value;
        break;

      case "regex": {
        const expectedValue = evalCase.expected.value;
        if (!(expectedValue instanceof RegExp) && typeof expectedValue !== "string") {
          passed = false;
          details.error = "No regex value provided for evaluation.";
          break;
        }
        const regex =
          expectedValue instanceof RegExp
            ? new RegExp(expectedValue.source, expectedValue.flags.replace(/[gy]/g, ""))
            : new RegExp(expectedValue);
        if (regex.source.length > 512) {
          passed = false;
          details.error = "Regex pattern too large for safe evaluation.";
          break;
        }
        passed = regex.test(actualOutput);
        details.pattern = String(expectedValue);
        break;
      }

      case "custom":
        if (typeof evalCase.expected.fn === "function") {
          passed = evalCase.expected.fn(actualOutput, evalCase);
        }
        break;

      default:
        return {
          caseId: evalCase.id,
          caseName: evalCase.name,
          passed: false,
          durationMs: Date.now() - start,
          error: `Unknown strategy: ${evalCase.expected.strategy}`,
        };
    }

    return {
      caseId: evalCase.id,
      caseName: evalCase.name,
      passed,
      durationMs: Date.now() - start,
      details,
    };
  } catch (error: unknown) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    return {
      caseId: evalCase.id,
      caseName: evalCase.name,
      passed: false,
      durationMs: Date.now() - start,
      error: errorMessage,
    };
  }
}

/**
 * Run all cases in a suite against provided outputs.
 *
 * @param {string} suiteId
 * @param {Record<string, string>} outputs - Map of caseId → actualOutput
 * @param {Record<string, { durationMs?: number, error?: string }>} [caseMetrics]
 * @returns {{ suiteId: string, suiteName: string, results: EvalResult[], summary: { total: number, passed: number, failed: number, passRate: number } }}
 */
export function runSuite(
  suiteId: string,
  outputs: Record<string, string>,
  caseMetrics: Record<string, { durationMs?: number; error?: string }> = {}
) {
  const suite = getSuite(suiteId);
  if (!suite) {
    throw new Error(`Suite not found: ${suiteId}`);
  }

  const results = suite.cases.map((c) => {
    const output = outputs[c.id] || "";
    const result = evaluateCase(c, output);
    const metrics = caseMetrics[c.id];

    if (metrics && Number.isFinite(Number(metrics.durationMs))) {
      result.durationMs = Math.max(0, Math.round(Number(metrics.durationMs)));
    }

    if (metrics?.error && !result.error) {
      result.error = metrics.error;
    }

    return result;
  });

  const passed = results.filter((r) => r.passed).length;
  const total = results.length;

  return {
    suiteId: suite.id,
    suiteName: suite.name,
    results,
    summary: {
      total,
      passed,
      failed: total - passed,
      passRate: total > 0 ? Math.round((passed / total) * 100) : 0,
    },
  };
}

/**
 * Create a scorecard from multiple suite runs.
 *
 * @param {Array<ReturnType<typeof runSuite>>} runs
 * @returns {{ suites: number, totalCases: number, totalPassed: number, overallPassRate: number, perSuite: Array<{ id: string, name: string, passRate: number }> }}
 */
export function createScorecard(runs: any[]) {
  const totalCases = runs.reduce((sum, r) => sum + r.summary.total, 0);
  const totalPassed = runs.reduce((sum, r) => sum + r.summary.passed, 0);

  return {
    suites: runs.length,
    totalCases,
    totalPassed,
    overallPassRate: totalCases > 0 ? Math.round((totalPassed / totalCases) * 100) : 0,
    perSuite: runs.map((r) => ({
      id: r.suiteId,
      name: r.suiteName,
      passRate: r.summary.passRate,
    })),
  };
}

/**
 * Reset test-registered suites and restore built-in suites.
 */
export function resetSuites() {
  suites.clear();
  registerBuiltInSuites();
}

// ─── Built-in suite registration ───────────────────────────────────────
// Suite data lives in ./evalRunner/builtinSuites (pure data, zero imports).
// Registration runs at module load, mirroring the original inline calls.

registerSuite(goldenSet);
registerSuite(codingSuite);
registerSuite(reasoningSuite);
registerSuite(multilingualSuite);
registerSuite(safetySuite);
registerSuite(instructionSuite);
registerSuite(codexComparisonSuite);

function registerBuiltInSuites() {
  for (const suite of builtInSuites) {
    registerSuite(suite);
  }
}

import { getEnabledProviders } from "@/lib/freeProxyProviders";
import { clearFreeProxySyncErrors, recordFreeProxySync, recordFreeProxySyncErrors } from "@/lib/localDb";
import type { FreeProxyProvider } from "@/lib/freeProxyProviders/types";

export interface FreeProxySyncCycleResult {
  results: Record<string, unknown>;
  lastSyncAt: string;
}

/**
 * Run one free-proxy sync cycle: call `sync()` on each provider, isolate
 * per-provider failures, and persist the cycle timestamp.
 *
 * Shared by both trigger paths — the manual `POST /api/settings/free-proxies/sync`
 * route and the automatic scheduler (`freeProxyProviders/scheduler.ts`, #7079) —
 * so both go through the exact same code path.
 *
 * `providers` defaults to `getEnabledProviders()` when omitted, which is what the
 * scheduler always uses (it has no notion of a per-request `sources` filter).
 */
export async function runFreeProxySyncCycle(
  providers?: FreeProxyProvider[]
): Promise<FreeProxySyncCycleResult> {
  const resolvedProviders = providers ?? getEnabledProviders();
  const results: Record<string, unknown> = {};

  for (const provider of resolvedProviders) {
    try {
      results[provider.id] = await provider.sync();
      await clearFreeProxySyncErrors(provider.id);
    } catch (error) {
      // #5595: isolate per-source failures so one provider throwing doesn't
      // abort the whole sync — the other sources still populate the pool and
      // the failure is surfaced in `results` instead of a blanket 500.
      const errorMessage = error instanceof Error ? error.message : String(error);
      results[provider.id] = {
        fetched: 0,
        added: 0,
        updated: 0,
        errors: [errorMessage],
      };
      await recordFreeProxySyncErrors(provider.id, [errorMessage]);
    }
  }

  // #4878: persist the sync timestamp so the UI's "last sync" advances even
  // when a sync returns zero new/updated proxies (otherwise it stayed frozen
  // at MAX(last_validated)).
  const lastSyncAt = await recordFreeProxySync();

  return { results, lastSyncAt };
}

/**
 * Idempotency Layer — Phase 9.2
 *
 * In-memory deduplication of requests with the same idempotency key.
 * If a request with the same key arrives within 5 seconds, returns
 * the cached response instead of making a new API call.
 *
 * Headers: X-Request-Id or Idempotency-Key
 *
 * @module lib/idempotencyLayer
 */

import { getSettings } from "@/lib/localDb";

const DEFAULT_WINDOW_MS = 5000;

/** @type {Map<string, { response: object, status: number, expiresAt: number }>} */
const idempotencyStore = new Map();

// Periodic cleanup every 30s
let cleanupInterval;

function ensureCleanup() {
  if (cleanupInterval) return;
  cleanupInterval = setInterval(() => {
    const now = Date.now();
    for (const [key, entry] of idempotencyStore) {
      if (now >= entry.expiresAt) {
        idempotencyStore.delete(key);
      }
    }
  }, 30000);
  // Don't prevent process exit
  if (cleanupInterval.unref) cleanupInterval.unref();
}

/**
 * Extract idempotency key from request headers.
 * @param {Headers|object} headers
 * @returns {string|null}
 */
export function getIdempotencyKey(headers) {
  if (!headers) return null;
  const get = typeof headers.get === "function" ? (k) => headers.get(k) : (k) => headers[k];
  return get("idempotency-key") || get("x-request-id") || null;
}

/**
 * Check if a response exists for the given idempotency key.
 * @param {string} key
 * @returns {{ response: object, status: number }|null}
 */
export function checkIdempotency(key) {
  if (!key) return null;
  const entry = idempotencyStore.get(key);
  if (!entry) return null;
  if (Date.now() >= entry.expiresAt) {
    idempotencyStore.delete(key);
    return null;
  }
  return { response: entry.response, status: entry.status };
}

/**
 * Save a response for idempotency dedup.
 * @param {string} key
 * @param {object} response - Response body to cache
 * @param {number} status - HTTP status code
 * @param {number} [windowMs=5000] - Dedup window in ms
 */
export function saveIdempotency(key, response, status, windowMs = DEFAULT_WINDOW_MS) {
  if (!key) return;
  ensureCleanup();
  idempotencyStore.set(key, {
    response,
    status,
    expiresAt: Date.now() + windowMs,
  });
}

/**
 * Get current idempotency store stats.
 */
export async function getIdempotencyStats() {
  let windowMs = DEFAULT_WINDOW_MS;
  try {
    const settings = await getSettings();
    if (typeof settings.idempotencyWindowMs === "number" && settings.idempotencyWindowMs > 0) {
      windowMs = settings.idempotencyWindowMs;
    }
  } catch {
    // Fallback to default if settings unavailable
  }
  return {
    activeKeys: idempotencyStore.size,
    windowMs,
  };
}

/**
 * Clear all idempotency entries (for testing).
 */
export function clearIdempotency() {
  idempotencyStore.clear();
}

import { sanitizeErrorMessage } from "@omniroute/open-sse/utils/error.ts";
import { createEmbeddingResponse } from "@/lib/embeddings/service";
import type { EmbeddingResult, EmbeddingError } from "./types";
import type { ResolvedMemoryCustomEmbeddingProvider } from "./customProvider";

export async function embedRemote(
  text: string,
  model: string,
  customProvider: ResolvedMemoryCustomEmbeddingProvider | null = null
): Promise<EmbeddingResult | EmbeddingError> {
  const t0 = Date.now();

  let resp: Response;
  try {
    resp = await createEmbeddingResponse(
      { model, input: text },
      customProvider
        ? {
            resolvedProvider: customProvider.provider,
            resolvedModel: customProvider.model,
          }
        : undefined
    );
  } catch (err: unknown) {
    // Network-level errors (ECONNREFUSED, AbortError, etc.)
    const isTimeout =
      err instanceof Error &&
      (err.name === "AbortError" || err.message.toLowerCase().includes("timeout"));
    return {
      source: "remote",
      model,
      reason: isTimeout ? "timeout" : "request_failed",
      message: sanitizeErrorMessage(err instanceof Error ? err.message : String(err)),
    };
  }

  if (!resp.ok) {
    const status = resp.status;
    if (status === 401 || status === 403) {
      return {
        source: "remote",
        model,
        reason: "no_key",
        message: sanitizeErrorMessage(`Embedding provider returned ${status}`),
      };
    }
    if (status === 429) {
      return {
        source: "remote",
        model,
        reason: "rate_limited",
        message: sanitizeErrorMessage(`Embedding provider returned 429 (rate limited)`),
      };
    }
    return {
      source: "remote",
      model,
      reason: "request_failed",
      message: sanitizeErrorMessage(`Embedding provider returned HTTP ${status}`),
    };
  }

  let json: unknown;
  try {
    json = await resp.json();
  } catch (err: unknown) {
    return {
      source: "remote",
      model,
      reason: "request_failed",
      message: sanitizeErrorMessage(
        err instanceof Error ? err.message : "Failed to parse embedding response"
      ),
    };
  }

  try {
    const data = (json as { data?: Array<{ embedding: number[] }> }).data;
    if (!Array.isArray(data) || data.length === 0 || !Array.isArray(data[0].embedding)) {
      return {
        source: "remote",
        model,
        reason: "request_failed",
        message: sanitizeErrorMessage(
          "Unexpected embedding response shape: missing data[0].embedding"
        ),
      };
    }
    const rawVec = data[0].embedding as number[];
    const vector = new Float32Array(rawVec);
    return {
      vector,
      source: "remote",
      model,
      dimensions: vector.length,
      latencyMs: Date.now() - t0,
      cached: false,
    };
  } catch (err: unknown) {
    return {
      source: "remote",
      model,
      reason: "request_failed",
      message: sanitizeErrorMessage(err instanceof Error ? err.message : "Embedding parse error"),
    };
  }
}

/**
 * Transformers.js local embedding (D8) — Xenova/all-MiniLM-L6-v2.
 *
 * IMPORTANT: @huggingface/transformers is imported lazily (await import())
 * ONLY when this function is called. Never imported at module level.
 * This satisfies D8 + D25 (serverExternalPackages + no bundle impact).
 */

import { sanitizeErrorMessage } from "@omniroute/open-sse/utils/error.ts";
import type { EmbeddingResult, EmbeddingError } from "./types";

const TRANSFORMERS_MODEL =
  process.env.MEMORY_TRANSFORMERS_MODEL || "Xenova/all-MiniLM-L6-v2";

// Singleton pipeline, initialized once
type PipelineFn = (text: string | string[], options?: Record<string, unknown>) => Promise<unknown>;
let _pipeline: PipelineFn | null = null;
let _pipelineLoading: Promise<PipelineFn> | null = null;

/** For testing: inject a mock pipeline factory. */
export function _injectPipeline(fn: PipelineFn | null): void {
  _pipeline = fn;
  _pipelineLoading = null;
}

async function getOrLoadPipeline(): Promise<PipelineFn> {
  if (_pipeline) return _pipeline;
  if (_pipelineLoading) return _pipelineLoading;

  _pipelineLoading = (async (): Promise<PipelineFn> => {
    // Lazy import — never at module level (D8, D25)
    const transformers = await import("@huggingface/transformers");
    const { pipeline } = transformers as { pipeline: (task: string, model: string, opts?: Record<string, unknown>) => Promise<PipelineFn> };
    const pipe = await pipeline("feature-extraction", TRANSFORMERS_MODEL, { dtype: "q8" });
    _pipeline = pipe;
    _pipelineLoading = null;
    return pipe;
  })();

  return _pipelineLoading;
}

/**
 * Convert Tensor-like output from transformers pipeline to Float32Array.
 * Transformers.js pipelines return a Tensor with `.data` (Float32Array or similar)
 * and `.dims` [batch, seq, hidden_size]. We flatten to hidden_size via mean pooling.
 */
function tensorToFloat32Array(output: unknown): Float32Array {
  // Handle Tensor objects from @huggingface/transformers
  const tensor = output as {
    data?: Float32Array | number[];
    dims?: number[];
    tolist?: () => number[][][];
  };

  if (tensor && tensor.data && tensor.dims) {
    const data = tensor.data instanceof Float32Array ? tensor.data : new Float32Array(tensor.data);
    const dims = tensor.dims;

    // Typical dims: [1, seq_len, hidden_size] or [seq_len, hidden_size]
    let seqLen: number;
    let hiddenSize: number;

    if (dims.length === 3) {
      // [batch=1, seq_len, hidden_size]
      seqLen = dims[1];
      hiddenSize = dims[2];
    } else if (dims.length === 2) {
      // [seq_len, hidden_size]
      seqLen = dims[0];
      hiddenSize = dims[1];
    } else {
      // Already flat — return as-is
      return data instanceof Float32Array ? data : new Float32Array(data);
    }

    // Mean pool over sequence dimension
    const result = new Float32Array(hiddenSize);
    for (let s = 0; s < seqLen; s++) {
      for (let h = 0; h < hiddenSize; h++) {
        result[h] += data[s * hiddenSize + h];
      }
    }
    for (let h = 0; h < hiddenSize; h++) {
      result[h] /= seqLen;
    }
    return result;
  }

  // Fallback: try tolist()
  if (tensor && typeof tensor.tolist === "function") {
    const list = tensor.tolist();
    if (Array.isArray(list) && Array.isArray(list[0])) {
      // [batch=1][seq_len][hidden]
      const inner = list[0];
      const hiddenSize2 = (inner[0] as number[]).length;
      const result2 = new Float32Array(hiddenSize2);
      for (const row of inner) {
        for (let h = 0; h < hiddenSize2; h++) {
          result2[h] += (row as number[])[h];
        }
      }
      for (let h = 0; h < hiddenSize2; h++) {
        result2[h] /= inner.length;
      }
      return result2;
    }
  }

  throw new Error("Cannot convert transformers output to Float32Array");
}

export async function embedTransformers(text: string): Promise<EmbeddingResult | EmbeddingError> {
  const t0 = Date.now();
  let pipe: PipelineFn;

  try {
    pipe = await getOrLoadPipeline();
  } catch (err: unknown) {
    const isTimeout =
      err instanceof Error &&
      (err.name === "AbortError" || err.message.toLowerCase().includes("timeout"));
    return {
      source: "transformers",
      model: TRANSFORMERS_MODEL,
      reason: isTimeout ? "timeout" : "model_load_failed",
      message: sanitizeErrorMessage(err instanceof Error ? err.message : String(err)),
    };
  }

  try {
    const output = await pipe(text, { pooling: "mean", normalize: true });
    const vector = tensorToFloat32Array(output);
    return {
      vector,
      source: "transformers",
      model: TRANSFORMERS_MODEL,
      dimensions: vector.length,
      latencyMs: Date.now() - t0,
      cached: false,
    };
  } catch (err: unknown) {
    const isTimeout =
      err instanceof Error &&
      (err.name === "AbortError" || err.message.toLowerCase().includes("timeout"));
    return {
      source: "transformers",
      model: TRANSFORMERS_MODEL,
      reason: isTimeout ? "timeout" : "request_failed",
      message: sanitizeErrorMessage(err instanceof Error ? err.message : String(err)),
    };
  }
}

