  modalitiesOutput: string[];
  interleavedField: string | null;
}

function toNonEmptyString(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : null;
}

function parseModalities(value: string | null | undefined): string[] {
  if (typeof value !== "string" || value.trim().length === 0) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed)
      ? parsed.filter((entry): entry is string => typeof entry === "string" && entry.length > 0)
      : [];
  } catch {
    return [];
  }
}

function getRegistryModel(providerIdOrAlias: string | null, modelId: string | null) {
  if (!providerIdOrAlias || !modelId) return null;
  const providerAlias = PROVIDER_ID_TO_ALIAS[providerIdOrAlias] || providerIdOrAlias;
  const models = PROVIDER_MODELS[providerAlias];
  if (!Array.isArray(models)) return null;
  const normalizedModelId =
    providerAlias === "cnl" ? modelId.replace(/-(?:xhigh|high|medium|low)$/i, "") : modelId;
  return models.find((model) => model?.id === normalizedModelId) || null;
}

function resolveCapabilityInput(input: CapabilityInput) {
  if (typeof input === "string") {
    const parsed = parseModel(input);
    const rawModel = toNonEmptyString(parsed.model);
    if (parsed.provider) {
      const canonical = resolveCanonicalProviderModel(parsed.provider, rawModel);
      return {
        provider: canonical.provider,
        model: toNonEmptyString(canonical.model),
        rawModel,
        lookupKey: input,
      };
    }

    return {
      provider: null,
      model: rawModel,
      rawModel,
      lookupKey: input,
    };
  }

  const rawProvider = toNonEmptyString(input.provider);
  const rawModel = toNonEmptyString(input.model);
  if (rawProvider) {
    const canonical = resolveCanonicalProviderModel(rawProvider, rawModel);
    return {
      provider: canonical.provider,
      model: toNonEmptyString(canonical.model),
      rawModel,
      lookupKey: rawModel ? `${canonical.provider}/${rawModel}` : canonical.provider,
    };
  }

  return {
    provider: null,
    model: rawModel,
    rawModel,
    lookupKey: rawModel || "",
  };
}

function heuristicToolCalling(modelStr: string): boolean {
  const normalized = String(modelStr || "").toLowerCase();
  if (!normalized) return false;
  const blocked = TOOL_CALLING_UNSUPPORTED_PATTERNS.some((pattern) => {
    if (normalized === pattern) return true;
    if (normalized.endsWith(`/${pattern}`)) return true;
    return normalized.includes(pattern);
  });
  return !blocked;
}

function heuristicReasoning(modelStr: string): boolean {
  const normalized = String(modelStr || "").toLowerCase();
  if (!normalized) return true;
  const blocked = REASONING_UNSUPPORTED_PATTERNS.some(
    (pattern) =>
      normalized === pattern || normalized.endsWith(`/${pattern}`) || normalized.includes(pattern)
  );
  return !blocked;
}

function heuristicMaxTokens(modelStr: string): boolean {
  const normalized = String(modelStr || "").toLowerCase();
  if (!normalized) return true;
  const blocked = MAX_TOKENS_UNSUPPORTED_PATTERNS.some(
    (pattern) =>
      normalized === pattern || normalized.endsWith(`/${pattern}`) || normalized.includes(pattern)
  );
  return !blocked;
}

/** Last path segment of a path-shaped model id (`cline-pass/kimi-k3` → `kimi-k3`). */
function leafModelId(modelId: string | null | undefined): string | null {
  if (!modelId || !modelId.includes("/")) return null;
  const leaf = modelId.split("/").filter(Boolean).pop() ?? null;
  return leaf && leaf !== modelId ? leaf : null;
}

function getStaticSpec(modelId: string | null, rawModel: string | null): ModelSpec | undefined {
  if (modelId) {
    const byCanonical = getModelSpec(modelId);
    if (byCanonical) return byCanonical;
  }
  if (rawModel && rawModel !== modelId) {
    return getModelSpec(rawModel);
  }
  return undefined;
}

/**
 * #8032: vision-only leaf fallback for path-shaped routed ids.
 *
 * Must NOT live in getStaticSpec() — that helper also feeds supportsTools /
 * supportsThinking / contextWindow / maxOutputTokens. A shared leaf lookup
 * incorrectly promotes e.g. aihorde/deepseek/deepseek-v4-flash to the real
 * DeepSeek V4 Flash tool-calling spec (#8212 regression).
 */
function getVisionStaticSpec(
  modelId: string | null,
  rawModel: string | null
): ModelSpec | undefined {
  const direct = getStaticSpec(modelId, rawModel);
  if (direct) return direct;
  for (const candidate of [modelId, rawModel]) {
    const leaf = leafModelId(candidate);
    if (!leaf) continue;
    const byLeaf = getModelSpec(leaf);
    if (byLeaf) return byLeaf;
  }
  return undefined;
}

function getAuthoritativeStaticContextWindow(
  provider: string | null,
  modelId: string | null,
  rawModel: string | null
): number | null {
  for (const candidate of [modelId, rawModel]) {
    const providerContextWindow = getAuthoritativeProviderContextWindow(provider, candidate);
    if (typeof providerContextWindow === "number") return providerContextWindow;
  }
  for (const candidate of [modelId, rawModel]) {
    const contextWindow = getAuthoritativeContextWindow(candidate);
    if (typeof contextWindow === "number") return contextWindow;
  }
  return null;
}

// #8697-adjacent: this used to rescan Object.entries(MODEL_SPECS) per candidate per
// call — the top hotspot in a full catalog-rebuild profile once the pricing-path and
// getCanonicalModelSpecId() bottlenecks were fixed. Reuses the lazy index already built
// for getCanonicalModelSpecId() (@/shared/constants/modelSpecs) instead of duplicating a
// second cache over the same static table.
function getStaticSpecCanonicalModelId(modelId: string | null, rawModel: string | null) {
  const candidates = [modelId, rawModel].filter(
    (candidate): candidate is string => typeof candidate === "string" && candidate.length > 0
  );
  for (const candidate of candidates) {
    const hit = findModelSpecIdByExactOrAlias(candidate);
    if (hit) return hit;
  }
  return null;
}

/**
 * Strip a trailing `-latest` alias suffix from a model id (#4073). Returns the
 * short id (`pixtral-12b-latest` → `pixtral-12b`) or `null` when there is no
 * `-latest` suffix to drop. Used only as a last-resort synced-lookup fallback.
 */
function stripLatestAlias(modelId: string | null): string | null {
  if (!modelId) return null;
  const stripped = modelId.replace(/-latest$/i, "");
  return stripped && stripped !== modelId ? stripped : null;
}

// #8697-adjacent: MODELS_DEV_PROVIDER_MAP is a static module constant, so the result
// of reverseModelsDevProviders() never changes for a given provider — memoized by
// provider key instead of rescanning Object.entries(MODELS_DEV_PROVIDER_MAP) on every
// call (called once per model in a catalog rebuild). Never evicted — bounded by the
// number of distinct providers ever queried (~50-100 in practice), negligible memory.
const reverseModelsDevProvidersCache = new Map<string, readonly string[]>();

function reverseModelsDevProviders(provider: string): readonly string[] {
  // models.dev may store capabilities under a different OmniRoute provider id
  // that also maps from the same upstream models.dev provider. Build reverse
  // candidates from MODELS_DEV_PROVIDER_MAP (e.g. openai ↔ cx).
  //
  // MODELS_DEV_PROVIDER_MAP's RHS is inconsistent: most providers list their
  // canonical id directly, but the OAuth CLI providers (codex/claude) only
  // list their alias (cx/cc), never the canonical id. Also probe the
  // provider's alias so a canonical id like "codex"/"claude" still matches
  // the map entries keyed only by "cx"/"cc" (#8429).
  const cached = reverseModelsDevProvidersCache.get(provider);
  if (cached) return cached;

  const out = new Set<string>();
  const providerAlias = PROVIDER_ID_TO_ALIAS[provider] || provider;
  for (const [modelsDevId, omniIds] of Object.entries(MODELS_DEV_PROVIDER_MAP)) {
    if (
      omniIds.includes(provider) ||
      omniIds.includes(providerAlias) ||
      modelsDevId === provider ||
      modelsDevId === providerAlias
    ) {
      out.add(modelsDevId);
      for (const id of omniIds) out.add(id);
    }
  }
  // Frozen: the result is now shared across every future call for this provider (via
  // the cache above) instead of a fresh array per call — freeze prevents an accidental
  // caller mutation (e.g. .push()) from corrupting the cache for everyone else.
  const result = Object.freeze([...out]);
  reverseModelsDevProvidersCache.set(provider, result);
  return result;
}

function getSyncedCapabilityForResolved(
  provider: string | null,
  model: string | null,
  rawModel: string | null,
  snapshot?: ModelCapabilityResolutionSnapshot | null
): SyncedCapabilities {
  if (!provider || !model) return null;

  const modelCandidates = Array.from(
    new Set(
      [model, rawModel, getStaticSpecCanonicalModelId(model, rawModel)]
        .filter((value): value is string => typeof value === "string" && value.length > 0)
        .flatMap((candidate) => {
          const values = [candidate];
          const stripped = stripLatestAlias(candidate);
          if (stripped) values.push(stripped);
          const leaf = leafModelId(candidate);
          if (leaf) values.push(leaf);
          // models.dev often stores OpenAI-family specialty models as qualified
          // ids under another mapped provider, e.g. vercel + "openai/whisper-1".
          if (!candidate.includes("/")) {
            values.push(`${provider}/${candidate}`);
          }
          return values;
        })
    )
  );

  // Include common host providers that re-publish OpenAI specialty models under
  // qualified ids (observed: vercel/openai/whisper-1, vercel/openai/tts-1).
  const providerCandidates = Array.from(
    new Set([provider, ...reverseModelsDevProviders(provider), "vercel"])
  );

  const bulk = snapshot?.synced ?? null;
  for (const prov of providerCandidates) {
    for (const mid of modelCandidates) {
      const found = getSyncedCapability(prov, mid, bulk);
      if (found) return found;
    }
  }
  return null;
}

/**
 * Last-resort vision fallback in resolveVisionCapability when there is no
 * synced/registry/spec capability data (e.g. Mistral Pixtral, which ships no
 * models.dev `attachment` flag and no registry `supportsVision`). Delegates to
 * the single shared source (`@/shared/constants/visionModels`, #4072) so routing,
 * the `/v1/models` listing and lite compression can never disagree on whether a
 * model is vision-capable. The list is intentionally conservative — a false
 * positive would let an image request route to a text-only model.
 */
export function modelIdLikelyVision(modelId: string | null | undefined): boolean {
  return isVisionModelId(modelId);
}

/**
 * Models that upstream catalogs (notably models.dev) mislabel as vision-capable but
 * are TEXT-ONLY per the vendor's own docs. Listed here so a wrong synced
 * `attachment:true` cannot route an image request to a blind model (the #4071 failure
 * mode). Keep this list tiny and doc-backed.
 *
 * Xiaomi MiMo: only `mimo-v2.5` and `mimo-v2-omni` accept images; the `*-pro` chat
 * models are text-only (mimo.mi.com .../image-understanding; hermes-agent#18884).
 * Anchored to the full id (`$`) and tolerant of a `provider/` prefix so `mimo-v2.5-pro`
 * never matches the multimodal `mimo-v2.5`, and `mimo-v2-pro` never matches `mimo-v2-omni`.
 */
const KNOWN_TEXT_ONLY_DESPITE_SYNC: readonly RegExp[] = [
  /(?:^|\/)mimo-v2\.5-pro$/i,
  /(?:^|\/)mimo-v2-pro$/i,
];

function isKnownTextOnlyDespiteSync(modelId: string | null | undefined): boolean {
  if (!modelId) return false;
  const id = String(modelId);
  return KNOWN_TEXT_ONLY_DESPITE_SYNC.some((pattern) => pattern.test(id));
}

/** True when a modality list declares image and/or video input/output. */
function modalitiesDeclareVision(modalities: readonly string[]): boolean {
  return modalities.some((entry) => {
    const lower = String(entry).toLowerCase();
    return lower.includes("image") || lower.includes("video");
  });
}

/**
 * #9195: Read the customModels supportsVision override for a given provider/model
 * pair from the database. Returns true/false when an explicit override exists, or
 * null if no custom model entry or no explicit flag. Sync read (better-sqlite3).
 */
function getCustomModelVisionOverride(provider: string, model: string): boolean | null {
  try {
    const db = getDbInstance();
    const row = db
      .prepare("SELECT value FROM key_value WHERE namespace = 'customModels' AND key = ?")
      .get(provider);
    if (!row) return null;
    const parsed = getKeyValue(row);
    if (!parsed.value) return null;
    const models: Array<{ id: string; supportsVision?: boolean }> = JSON.parse(parsed.value);
    const entry = models.find((m) => m.id === model);
    if (entry && typeof entry.supportsVision === "boolean") {
      return entry.supportsVision;
    }
    return null;
  } catch {
    return null;
  }
}

function resolveVisionCapability(
  spec: ModelSpec | undefined,
  registryModel: { supportsVision?: boolean } | null,
  synced: SyncedCapabilities,
  modalitiesInput: string[],
  modalitiesOutput: string[],
  modelId?: string,
  customVisionOverride?: boolean | null
): boolean | null {
  const allModalities = [...modalitiesInput, ...modalitiesOutput].map((entry) =>
    String(entry).toLowerCase()
  );

  // #9195: explicit custom model supportsVision override (from the dashboard
  // "Vision capable" toggle) is the operator's authoritative choice for a
  // self-hosted model. Check before the synced/registry/heuristic cascade so
  // an operator-flagged vision model is never rejected by the Combo vision filter.
  if (typeof customVisionOverride === "boolean") {
    return customVisionOverride;
  }

  // Hard override FIRST: a wrong synced `attachment:true` (or image modality) must not
  // win for models the vendor documents as text-only. Beats every branch below so an
  // image request can never be routed to a blind model (#4071).
  if (isKnownTextOnlyDespiteSync(modelId)) return false;

  if (typeof synced?.attachment === "boolean") {
    // #8250: models.dev sometimes ships attachment=false alongside image/video
    // modalities (observed for Kimi K3). Prefer the richer modality signal over
    // the contradictory false flag so supportsVision / attachment / modalities
    // can be reconciled to a single vision-capable verdict.
    if (synced.attachment === false && modalitiesDeclareVision(allModalities)) {
      return true;
    }
    // #8032: attachment=false without modalities must not beat authoritative
    // registry/spec vision for path-shaped custom/routed ids (e.g. Cline Pass
    // `cp/cline-pass/kimi-k3` → MODEL_SPECS["kimi-k3"].supportsVision).
    if (synced.attachment === false) {
      if (registryModel?.supportsVision === true) return true;
      if (spec?.supportsVision === true) return true;
      return false;
    }
    return synced.attachment;
  }

  if (allModalities.some((entry) => entry.includes("image"))) {
    return true;
  }

  if (allModalities.length > 0) {
    return false;
  }

  if (typeof registryModel?.supportsVision === "boolean") return registryModel.supportsVision;
  if (typeof spec?.supportsVision === "boolean") return spec.supportsVision;

  // Last resort: no capability data at all. Positively confirm known multimodal
  // families by model id so image requests can be routed to them; everything
  // else stays `null` (unknown).
  if (modelIdLikelyVision(modelId)) return true;

  return null;
}

/**
 * Resolve whether a chat model accepts audio input.
 *
 * Explicit catalog metadata wins. Synced input modalities are authoritative
 * only when they contain at least one declared modality; an empty list means
 * that no source knows the answer and remains `null` so Audio Bridge can act
 * conservatively.
 */
export function resolveAudioCapability(
  spec: Pick<ModelSpec, "supportsAudio"> | undefined,
  registryModel: { supportsAudio?: boolean } | null,
  modalitiesInput: readonly string[]
): boolean | null {
  if (typeof registryModel?.supportsAudio === "boolean") return registryModel.supportsAudio;
  if (typeof spec?.supportsAudio === "boolean") return spec.supportsAudio;
  if (modalitiesInput.length === 0) return null;
  return modalitiesInput.some((entry) => String(entry).toLowerCase().includes("audio"));
}

/**
 * Issue #6524: an operator-set `max_output_tokens` capability override (see
 * `src/lib/db/modelCapabilityOverrides.ts`) is the manual escape hatch for a
 * wrong/stale synced `limit_output` value (e.g. a provider's models.dev catalog
 * row reporting `limit_output` equal to `limit_context`). It already won over the
 * synced value in `getResolvedModelCapabilities().maxOutputTokens` — this helper
 * makes `getExplicitModelOutputCap()` (used by the reasoning-token-buffer clamp)
 * consult the same override so both read paths agree.
 */
/**
 * Exact-match capability override lookup with intentional raw-alias fallback.
 *
 * An override may be stored under either the canonical model id or the exact
 * provider-scoped raw alias the operator used (e.g. `github/claude-opus-4.5`
 * resolving to canonical `claude-opus-4-5-20251101`). We consult the canonical
 * id first, then the raw alias — both are exact provider/model matches. There is
 * deliberately NO suffix/effort/family inheritance: an override for
 * `codex/gpt-5.6` never applies to `codex/gpt-5.6-high`.
 */
function getCapabilityOverride(
  resolved: { provider: string | null; model: string | null; rawModel: string | null },
  key: "max_input_tokens" | "max_output_tokens"
): number | null {
  const canonical = getModelCapabilityOverride(resolved.provider, resolved.model, key);
  if (canonical !== null) return canonical;
  return resolved.rawModel && resolved.rawModel !== resolved.model
    ? getModelCapabilityOverride(resolved.provider, resolved.rawModel, key)
    : null;
}

function getContextOverride(resolved: {
  provider: string | null;
  model: string | null;
  rawModel: string | null;
}): number | null {
  const canonical = getModelContextOverride(resolved.provider, resolved.model);
  if (canonical !== null) return canonical;
  return resolved.rawModel && resolved.rawModel !== resolved.model
    ? getModelContextOverride(resolved.provider, resolved.rawModel)
    : null;
}

/**
 * Resolve a persisted context override by canonical id, then by the exact raw
 * alias supplied by the caller. Neither lookup inherits to related models.
 */
export function getResolvedModelContextOverride(input: CapabilityInput): number | null {
  return getContextOverride(resolveCapabilityInput(input));
}

function getInputTokenCapabilityOverride(resolved: {
  provider: string | null;
  model: string | null;
  rawModel: string | null;
}): number | null {
  return getCapabilityOverride(resolved, "max_input_tokens");
}

function getOutputTokenCapabilityOverride(resolved: {
  provider: string | null;
  model: string | null;
  rawModel: string | null;
}): number | null {
  return getCapabilityOverride(resolved, "max_output_tokens");
}

/**
 * Bulk-load friendly max_token override lookup (#9199). When a snapshot is
 * supplied its preloaded map is used; otherwise falls back to the on-demand
 * read (same precedence as getOutputTokenCapabilityOverride).
 */
function getMaxTokenCapabilityOverride(
  resolved: {
    provider: string | null;
    model: string | null;
    rawModel: string | null;
  },
  snapshot?: ModelCapabilityResolutionSnapshot | null
): number | null {
  const bulk = snapshot?.maxTokenOverrides ?? null;
  return (
    getModelCapabilityOverride(resolved.provider, resolved.model, "max_output_tokens", bulk) ??
    (resolved.rawModel && resolved.rawModel !== resolved.model
      ? getModelCapabilityOverride(resolved.provider, resolved.rawModel, "max_output_tokens", bulk)
      : null)
  );
}

export function getExplicitModelOutputCap(
  input: CapabilityInput,
  snapshot?: ModelCapabilityResolutionSnapshot | null
): number | null {
  const resolved = resolveCapabilityInput(input);
  const maxTokenOverride = snapshot
    ? getMaxTokenCapabilityOverride(resolved, snapshot)
    : getOutputTokenCapabilityOverride(resolved);
  if (maxTokenOverride !== null) return maxTokenOverride;

  const synced = getSyncedCapabilityForResolved(
    resolved.provider,
    resolved.model,
    resolved.rawModel,
    snapshot
  );
  if (synced && typeof synced.limit_output === "number") return synced.limit_output;

  const registryModel = getRegistryModel(resolved.provider, resolved.model);
  if (typeof registryModel?.maxOutputTokens === "number") return registryModel.maxOutputTokens;

  const spec = getStaticSpec(resolved.model, resolved.rawModel);
  return spec?.maxOutputTokens ?? null;
}

export function getResolvedModelCapabilities(
  input: CapabilityInput,
  options?: ResolveModelCapabilitiesOptions,
  snapshot?: ModelCapabilityResolutionSnapshot | null
): ResolvedModelCapabilities {
  // Reconciliation / auto-discovery needs the override-free catalog view so a
  // persisted override never feeds back into the comparison that (re)writes it.
  const usePersistedOverrides = options?.persistedOverrides !== false;
  const resolved = resolveCapabilityInput(input);
  const spec = getStaticSpec(resolved.model, resolved.rawModel);
  const registryModel = getRegistryModel(resolved.provider, resolved.model);
  const synced = getSyncedCapabilityForResolved(
    resolved.provider,
    resolved.model,
    resolved.rawModel,
    snapshot
  );

  const modalitiesInput = parseModalities(synced?.modalities_input);
  const modalitiesOutput = parseModalities(synced?.modalities_output);
  const lookupKey =
    toNonEmptyString(
      resolved.provider && resolved.model
        ? `${resolved.provider}/${resolved.model}`
        : resolved.model || resolved.rawModel || resolved.lookupKey
    ) || "";
  const reasoningDenied = !heuristicReasoning(lookupKey);

  // Provider-level fallback: a live-discovered model (passthroughModels
  // providers like AI Horde) has no per-model registry entry, synced
  // capability, or static spec — every source above resolves to null, so
  // toolCalling would otherwise fall through to heuristicToolCalling's
  // optimistic default (true). Reuse the same unsupportedParams signal the
  // request-time strip already relies on: if the provider declares "tools"
  // unsupported for every model it serves, that's authoritative here too.
  const providerDeniesTools =
    resolved.provider && resolved.model
      ? getUnsupportedParams(resolved.provider, resolved.model).includes("tools")
      : false;

  const supportsTools =
    synced?.tool_call ??
    (typeof registryModel?.toolCalling === "boolean" ? registryModel.toolCalling : null) ??
    (typeof spec?.supportsTools === "boolean" ? spec.supportsTools : null) ??
    (providerDeniesTools ? false : null);

  const supportsThinking = reasoningDenied
    ? false
    : (synced?.reasoning ??
      (typeof registryModel?.supportsReasoning === "boolean"
        ? registryModel.supportsReasoning
        : null) ??
      (typeof spec?.supportsThinking === "boolean" ? spec.supportsThinking : null));

  const authoritativeContextWindow = getAuthoritativeStaticContextWindow(
    resolved.provider,
    resolved.model,
    resolved.rawModel
  );
  // A persisted context-window override (operator-set or auto-discovered)
  // reflects the real *total* window and wins over every static/synced source.
  // `maxInputTokens` still follows its own precedence chain; only when that
  // chain has no narrower source does it naturally fall back to this window.
  const persistedContextWindow = usePersistedOverrides ? getContextOverride(resolved) : null;
  const contextWindow =
    persistedContextWindow ??
    authoritativeContextWindow ??
    synced?.limit_context ??
    (typeof registryModel?.contextLength === "number" ? registryModel.contextLength : null) ??
    spec?.contextWindow ??
    null;

  const maxInputOverride = usePersistedOverrides ? getInputTokenCapabilityOverride(resolved) : null;
  const maxTokenOverride = snapshot
    ? getMaxTokenCapabilityOverride(resolved, snapshot)
    : usePersistedOverrides
      ? getOutputTokenCapabilityOverride(resolved)
      : null;

  // Vision consults leaf static metadata for path-shaped ids; other capability
  // fields keep using the non-leaf `spec` from getStaticSpec() above.
  const visionSpec = getVisionStaticSpec(resolved.model, resolved.rawModel);

  // #9195: read the custom model's supportsVision override from the DB so the
  // dashboard "Vision capable" toggle affects Combo routing.
  const customVisionOverride =
    resolved.provider && resolved.model
      ? getCustomModelVisionOverride(resolved.provider, resolved.model)
      : null;

  const supportsVision = resolveVisionCapability(
    visionSpec,
    registryModel,
    synced,
    modalitiesInput,
    modalitiesOutput,
    lookupKey,
    customVisionOverride
  );
  const supportsAudio = resolveAudioCapability(spec, registryModel, modalitiesInput);

  // #8250: when resolve promoted vision over a contradictory attachment=false,
  // expose attachment=true so catalog / Vision Bridge / clients see one verdict.
  let attachment = synced?.attachment ?? null;
  if (supportsVision === true && attachment === false) {
    attachment = true;
  }

  return {
    provider: resolved.provider,
    model: resolved.model,
    rawModel: resolved.rawModel,
    toolCalling: supportsTools ?? heuristicToolCalling(lookupKey),
    reasoning: supportsThinking ?? heuristicReasoning(lookupKey),
    supportsThinking,
    supportsTools,
    supportsVision,
    supportsAudio,
    supportsMaxTokens: heuristicMaxTokens(lookupKey),
    attachment,
    structuredOutput: synced?.structured_output ?? null,
    temperature: synced?.temperature ?? null,
    contextWindow,
    maxInputTokens: (() => {
      // Input cap is input-only. An explicit `max_input_tokens` override wins;
      // otherwise fall back to the existing per-source input limits, then to the
      // total window. The effective cap can never exceed the total window
      // (input + output), so clamp it — but never double-count a requested
      // output against this input cap.
      const candidate =
        maxInputOverride ??
        (typeof registryModel?.maxInputTokens === "number" ? registryModel.maxInputTokens : null) ??
        authoritativeContextWindow ??
        synced?.limit_input ??
        contextWindow;
      return candidate !== null && contextWindow !== null
        ? Math.min(candidate, contextWindow)
        : candidate;
    })(),
    maxOutputTokens:
      maxTokenOverride ??
      synced?.limit_output ??
      (typeof registryModel?.maxOutputTokens === "number" ? registryModel.maxOutputTokens : null) ??
      spec?.maxOutputTokens ??
      null,
    defaultThinkingBudget: spec?.defaultThinkingBudget ?? 0,
    thinkingBudgetCap: spec?.thinkingBudgetCap ?? null,
    thinkingOverhead: spec?.thinkingOverhead ?? null,
    adaptiveMaxTokens: spec?.adaptiveMaxTokens ?? null,
    family: synced?.family ?? null,
    status: synced?.status ?? null,
    openWeights: synced?.open_weights ?? null,
    knowledgeCutoff: synced?.knowledge_cutoff ?? null,
    releaseDate: synced?.release_date ?? null,
    lastUpdated: synced?.last_updated ?? null,
    modalitiesInput,
    modalitiesOutput,
    interleavedField:
      synced?.interleaved_field ??
      (typeof registryModel?.interleavedField === "string" ? registryModel.interleavedField : null),
  };
}

/**
 * Input cap enforced at the request-time hard gate, with explicit combo semantics.
 *
 * Feature 5004 lets a raw, exact `model_context_overrides` entry supersede a
 * deliberately smaller catalog/client input hint for COMBO routing: the combo
 * compatibility filter (`open-sse/services/combo/contextOverrideGate.ts`) already
 * rescues such targets, so the final hard gate in handleChatCore must not turn
 * around and reject the rescued target on the very hint the filter bypassed.
 *
 * Semantics (deliberately narrow — NO suffix/effort/family inheritance):
 * - An explicit `max_input_tokens` capability override is ALWAYS enforced, for
 *   direct and combo requests alike. It is the operator's input-only ceiling and
 *   must never be bypassed by a context-window override.
 * - Otherwise, for a COMBO request with an exact persisted context override, that
 *   context override is the input cap (it reflects the real window; the smaller
 *   catalog hint does not apply). Direct requests ignore this branch.
 * - Otherwise the canonical `maxInputTokens` chain applies (registry input hint →
 *   authoritative window → synced limit_input → total window), clamped to the
 *   total window.
 *
 * `isCombo` selects the combo-rescue branch; pass `false`/omit for direct calls.
 * The returned cap is still only an *input* bound — the total-window/output
 * reserve check is enforced separately by `enforceOutputTokenBudget`.
 */
export function resolveInputTokenCapForGate(
  input: CapabilityInput,
  { isCombo = false }: { isCombo?: boolean } = {}
): number | null {
  const resolved = resolveCapabilityInput(input);

  // 1. An explicit `max_input_tokens` override always wins and is never bypassed.
  const explicitInputOverride = getInputTokenCapabilityOverride(resolved);
  if (explicitInputOverride !== null) return explicitInputOverride;

  // 2. Combo rescue: an exact persisted context override supersedes the smaller
  //    catalog/client input hint (mirrors contextOverrideGate.evaluateContextLimit).
  if (isCombo) {
    const contextOverride = getContextOverride(resolved);
    if (contextOverride !== null) return contextOverride;
  }

  // 3. Canonical chain (already clamped to the total window by the resolver).
  return getResolvedModelCapabilities(input).maxInputTokens;
}

export function supportsToolCalling(input: CapabilityInput): boolean {
  if (typeof input === "string" && !String(input || "").trim()) return false;
  return getResolvedModelCapabilities(input).toolCalling;
}

export function supportsReasoning(input: CapabilityInput): boolean {
  if (typeof input === "string" && !String(input || "").trim()) return true;
  return getResolvedModelCapabilities(input).reasoning;
}

export function supportsMaxTokens(input: CapabilityInput): boolean {
  if (typeof input === "string" && !String(input || "").trim()) return true;
  return getResolvedModelCapabilities(input).supportsMaxTokens;
}

export function capMaxOutputTokens(input: CapabilityInput, requested?: number): number | null {
  const cap = getResolvedModelCapabilities(input).maxOutputTokens;
  const hasRequested = typeof requested === "number" && Number.isFinite(requested);
  if (cap === null) return hasRequested ? requested : null;
  return hasRequested ? Math.min(requested, cap) : cap;
}

export function getDefaultThinkingBudget(input: CapabilityInput): number {
  return getResolvedModelCapabilities(input).defaultThinkingBudget;
}

/**
 * Clamp a requested thinking budget to the model's real ceiling.
 *
 * Resolution order (lowest wins):
 *  1. Registry cap (MODEL_SPECS.thinkingBudgetCap) — authoritative when present.
 *  2. Learned cap — a lower ceiling previously discovered via an upstream 400
 *     ("thinking_budget must be in the range ...") recorded by the executor
 *     (open-sse/services/learnedThinkingCaps.ts). In-memory, per provider+model.
 *  3. Gemini-family fallback — when the registry has no cap but the model id
 *     contains "gemini" (any provider: many providers host Gemini models), clamp
 *     to GEMINI_FALLBACK_THINKING_CAP (32768, the known pro-tier cap) instead of
 *     letting an xhigh budget (131072) sail through to a 400. Registered flash
 *     models already carry their explicit 24576 cap via rule 1, so this only
 *     fires for unregistered Gemini ids.
 */
export function capThinkingBudget(input: CapabilityInput, budget: number): number {
  const resolved = getResolvedModelCapabilities(input);
  let cap = resolved.thinkingBudgetCap;

  const modelId = resolved.model ?? resolved.rawModel ?? "";
  const modelLower = modelId.toLowerCase();
  // Learned-cap lookup needs a concrete provider key (the executor records under
  // `this.provider`). When the input is a bare Gemini id, `resolved.provider` is
  // null — but bare Gemini ids always route to the native Gemini provider, so
  // default to "gemini". Without this a cap learned via the executor would be
  // invisible to bare-model callers. Provider-qualified inputs keep their own
  // provider, preserving per-provider independence.
  const providerForLearned = resolved.provider ?? (modelLower.includes("gemini") ? "gemini" : null);

  const learned = getLearnedThinkingCap(providerForLearned, modelId);
  if (learned !== null) {
    cap = cap === null ? learned : Math.min(cap, learned);
  }

  if (cap === null && modelLower.includes("gemini")) {
    cap = GEMINI_FALLBACK_THINKING_CAP;
  }

  return Math.min(budget, cap ?? budget);
}

export function getModelContextLimit(
  providerOrInput: CapabilityInput,
  modelId?: string,
  snapshot?: ModelCapabilityResolutionSnapshot | null
): number | null {
  const resolved =
    typeof providerOrInput === "string" && modelId !== undefined
      ? getResolvedModelCapabilities({ provider: providerOrInput, model: modelId }, undefined, snapshot)
      : getResolvedModelCapabilities(providerOrInput, undefined, snapshot);
  // Feature 5004: a persisted override (operator-set or auto-discovered) wins over the
  // static catalog / models.dev sync. `getResolvedModelCapabilities` stays override-free
  // so the reconciler can compare the catalog value against provider-declared windows.
  const override = getModelContextOverride(
    resolved.provider,
    resolved.model,
    snapshot?.contextOverrides ?? null
  );
  return override ?? resolved.contextWindow;
}

import { createHash } from "crypto";

import {
  getProviderConnections,
  updateProviderConnection,
} from "@/lib/db/providers";
import { getCachedProviderConnectionById } from "@/lib/db/readCache";
import { clearProviderFailure, clearModelLock } from "@omniroute/open-sse/services/accountFallback";

type JsonRecord = Record<string, unknown>;

export type ProviderAutopilotSeverity = "info" | "warning" | "critical";
export type ProviderAutopilotState = "healthy" | "degraded" | "down";
export type ProviderAutopilotStatus = "healthy" | "warning" | "critical";

export type ProviderAutopilotActionType =
  | "clear_provider_breaker"
  | "clear_connection_cooldown"
  | "clear_stale_connection_error"
  | "clear_model_lockout"
  | "reactivate_connection"
  | "deactivate_connection";

export interface ProviderAutopilotTarget {
  provider: string;
  connectionId?: string;
  model?: string;
}

export interface ProviderAutopilotAction {
  type: ProviderAutopilotActionType;
  label: string;
  risk: "low" | "medium" | "high";
  requiresConfirmation: boolean;
  target: ProviderAutopilotTarget;
  preconditionsHash: string;
}

export interface ProviderAutopilotIssue {
  id: string;
  severity: ProviderAutopilotSeverity;
  kind:
    | "provider_circuit_open"
    | "provider_circuit_half_open"
    | "connection_cooldown"
    | "stale_connection_error"
    | "terminal_connection_error"
    | "inactive_connection"
    | "model_lockout"
    | "quota_monitor_warning";
  title: string;
  recommendation: string;
  target: ProviderAutopilotTarget;
  evidence: JsonRecord;
  actions: ProviderAutopilotAction[];
}

export interface ProviderAutopilotProvider {
  provider: string;
  state: ProviderAutopilotState;
  score: number;
  signals: {
    circuitBreaker: JsonRecord | null;
    connections: {
      total: number;
      active: number;
      inactive: number;
      cooldown: number;
      terminal: number;
      staleErrors: number;
    };
    modelLockouts: number;
    quotaMonitor: JsonRecord | null;
  };
  issues: ProviderAutopilotIssue[];
}

export interface ProviderAutopilotReport {
  status: ProviderAutopilotStatus;
  checkedAt: string;
  summary: {
    providerCount: number;
    connectionCount: number;
    healthyCount: number;
    issueCount: number;
    actionableCount: number;
  };
  providers: ProviderAutopilotProvider[];
}

export interface ProviderAutopilotOptions {
  provider?: string | null;
  includeHealthy?: boolean;
  includeActions?: boolean;
}

export interface ExecuteProviderAutopilotActionInput {
  type: ProviderAutopilotActionType;
  target: ProviderAutopilotTarget;
  preconditionsHash: string;
  dryRun?: boolean;
  confirm?: boolean;
}

const TERMINAL_STATUSES = new Set(["banned", "expired", "credits_exhausted"]);
const OPEN_BREAKER_STATES = new Set(["OPEN", "HALF_OPEN"]);

function toRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function toString(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function toNumber(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim()) {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

function parseTimeMs(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim()) {
    const numeric = Number(value);
    if (Number.isFinite(numeric)) return numeric;
    const parsed = new Date(value).getTime();
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map((entry) => stableStringify(entry)).join(",")}]`;
  const record = value as JsonRecord;
  return `{${Object.keys(record)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${stableStringify(record[key])}`)
    .join(",")}}`;
}

function hashPreconditions(input: unknown): string {
  return createHash("sha256").update(stableStringify(input)).digest("hex").slice(0, 16);
}

function stableEvidenceForHash(evidence: JsonRecord): JsonRecord {
  const stable: JsonRecord = { ...evidence };
  delete stable.remainingMs;
  delete stable.retryAfterMs;
  return stable;
}

function targetMatches(left: ProviderAutopilotTarget, right: ProviderAutopilotTarget): boolean {
  return (
    left.provider === right.provider &&
    (left.connectionId ?? null) === (right.connectionId ?? null) &&
    (left.model ?? null) === (right.model ?? null)
  );
}

function action(
  type: ProviderAutopilotActionType,
  label: string,
  risk: ProviderAutopilotAction["risk"],
  target: ProviderAutopilotTarget,
  evidence: JsonRecord
): ProviderAutopilotAction {
  return {
    type,
    label,
    risk,
    requiresConfirmation: true,
    target,
    preconditionsHash: hashPreconditions({
      type,
      target,
      evidence: stableEvidenceForHash(evidence),
    }),
  };
}

function issueId(kind: ProviderAutopilotIssue["kind"], target: ProviderAutopilotTarget): string {
  return ["pha", kind, target.provider, target.connectionId, target.model]
    .filter(Boolean)
    .join("_")
    .replace(/[^a-zA-Z0-9_.:-]/g, "_");
}

function sanitizeConnectionLabel(connection: JsonRecord): string {
  const label =
    toString(connection.name) ||
    toString(connection.displayName) ||
    toString(connection.email) ||
    toString(connection.id) ||
    "connection";
  const masked = label.includes("@") ? label.replace(/^(.).+(@.+)$/, "$1***$2") : label;
  return masked.length > 80 ? `${masked.slice(0, 77)}…` : masked;
}

function isTerminalConnection(connection: JsonRecord): boolean {
  const status = toString(connection.testStatus)?.toLowerCase();
  const errorType = toString(connection.lastErrorType)?.toLowerCase();
  return Boolean(
    (status && TERMINAL_STATUSES.has(status)) || (errorType && TERMINAL_STATUSES.has(errorType))
  );
}

function isConnectionInCooldown(connection: JsonRecord, now: number): boolean {
  const until = parseTimeMs(connection.rateLimitedUntil);
  return Boolean(until && until > now);
}

function hasStaleConnectionError(connection: JsonRecord, now: number): boolean {
  if (isTerminalConnection(connection)) return false;
  if (isConnectionInCooldown(connection, now)) return false;
  const until = parseTimeMs(connection.rateLimitedUntil);
  const status = toString(connection.testStatus)?.toLowerCase();
  return Boolean(
    toString(connection.lastError) ||
    toString(connection.lastErrorType) ||
    toString(connection.errorCode) ||
    (until && until <= now) ||
    status === "unavailable" ||
    status === "error"
  );
}

function providerFromLockout(lockout: JsonRecord): string | null {
  return toString(lockout.provider);
}

function buildConnectionClearPatch(): JsonRecord {
  return {
    testStatus: "active",
    errorCode: null,
    lastError: null,
    lastErrorAt: null,
    lastErrorType: null,
    lastErrorSource: null,
    backoffLevel: 0,
    rateLimitedUntil: null,
  };
}

export async function buildProviderHealthAutopilotReport(
  options: ProviderAutopilotOptions = {}
): Promise<ProviderAutopilotReport> {
  const now = Date.now();
  const checkedAt = new Date(now).toISOString();
  const includeHealthy = options.includeHealthy === true;
  const includeActions = options.includeActions !== false;
  const providerFilter = toString(options.provider);

  const [{ getAllCircuitBreakerStatuses }, { getAllModelLockouts }, quotaMonitor] =
    await Promise.all([
      import("@/shared/utils/circuitBreaker"),
      import("@omniroute/open-sse/services/accountFallback"),
      import("@omniroute/open-sse/services/quotaMonitor.ts").catch(() => null),
    ]);

  const connections = (await getProviderConnections(
    providerFilter ? { provider: providerFilter } : {}
  )) as JsonRecord[];
  const breakers = getAllCircuitBreakerStatuses().filter((breaker) => {
    const name = toString((breaker as JsonRecord).name);
    if (!name || name.startsWith("test-") || name.startsWith("test_")) return false;
    return !providerFilter || name === providerFilter;
  });
  const lockouts = (getAllModelLockouts() as JsonRecord[]).filter((lockout) => {
    const provider = providerFromLockout(lockout);
    return provider && (!providerFilter || provider === providerFilter);
  });
  const quotaSnapshots = quotaMonitor?.getQuotaMonitorSnapshots
    ? (quotaMonitor.getQuotaMonitorSnapshots() as JsonRecord[]).filter((snapshot) => {
        const provider = toString(snapshot.provider);
        return provider && (!providerFilter || provider === providerFilter);
      })
    : [];

  const providerIds = new Set<string>();
  for (const connection of connections) {
    const provider = toString(connection.provider);
    if (provider) providerIds.add(provider);
  }
  for (const breaker of breakers) {
    const provider = toString((breaker as JsonRecord).name);
    if (provider) providerIds.add(provider);
  }
  for (const lockout of lockouts) {
    const provider = providerFromLockout(lockout);
    if (provider) providerIds.add(provider);
  }
  for (const snapshot of quotaSnapshots) {
    const provider = toString(snapshot.provider);
    if (provider) providerIds.add(provider);
  }
  if (providerFilter) providerIds.add(providerFilter);

  const providers: ProviderAutopilotProvider[] = [];
  for (const provider of [...providerIds].sort()) {
    const providerConnections = connections.filter(
      (connection) => connection.provider === provider
    );
    const breaker = breakers.find((entry) => (entry as JsonRecord).name === provider) as
      | JsonRecord
      | undefined;
    const providerLockouts = lockouts.filter(
      (lockout) => providerFromLockout(lockout) === provider
    );
    const providerQuota = quotaSnapshots.filter((snapshot) => snapshot.provider === provider);
    const issues: ProviderAutopilotIssue[] = [];

    if (breaker && OPEN_BREAKER_STATES.has(String(breaker.state))) {
      const target = { provider };
      const evidence = {
        state: breaker.state,
        failureCount: toNumber(breaker.failureCount) ?? 0,
        retryAfterMs: toNumber(breaker.retryAfterMs) ?? 0,
        lastFailureTime: breaker.lastFailureTime ?? null,
      };
      const isOpen = breaker.state === "OPEN";
      issues.push({
        id: issueId(isOpen ? "provider_circuit_open" : "provider_circuit_half_open", target),
        severity: isOpen ? "critical" : "warning",
        kind: isOpen ? "provider_circuit_open" : "provider_circuit_half_open",
        title: isOpen ? "Provider circuit breaker is open" : "Provider is probing recovery",
        recommendation: isOpen
          ? "Verify upstream recovery, then reset the provider circuit breaker or wait for the retry window."
          : "Let the next probe complete or reset the breaker after manual verification.",
        target,
        evidence,
        actions: includeActions
          ? [action("clear_provider_breaker", "Reset provider breaker", "medium", target, evidence)]
          : [],
      });
    }

    for (const connection of providerConnections) {
      const connectionId = toString(connection.id);
      if (!connectionId) continue;
      const target = { provider, connectionId };
      const label = sanitizeConnectionLabel(connection);
      const cooldownUntil = parseTimeMs(connection.rateLimitedUntil);
      const terminal = isTerminalConnection(connection);
      const evidence = {
        connectionId,
        label,
        testStatus: connection.testStatus ?? null,
        lastErrorType: connection.lastErrorType ?? null,
        lastErrorAt: connection.lastErrorAt ?? null,
        lastErrorHash: toString(connection.lastError)
          ? hashPreconditions(toString(connection.lastError))
          : null,
        errorCode: connection.errorCode ?? null,
        backoffLevel: connection.backoffLevel ?? null,
        updatedAt: connection.updatedAt ?? null,
        rateLimitedUntil: connection.rateLimitedUntil ?? null,
        remainingMs: cooldownUntil ? Math.max(0, cooldownUntil - now) : 0,
        isActive: connection.isActive !== false,
      };

      if (terminal) {
        issues.push({
          id: issueId("terminal_connection_error", target),
          severity: "critical",
          kind: "terminal_connection_error",
          title: `${label} has a terminal account state`,
          recommendation:
            "Check billing, re-authenticate, or replace the credential before reactivating it.",
          target,
          evidence,
          actions: [],
        });
      } else if (isConnectionInCooldown(connection, now)) {
        issues.push({
          id: issueId("connection_cooldown", target),
          severity: "warning",
          kind: "connection_cooldown",
          title: `${label} is in temporary cooldown`,
          recommendation:
            "Wait for the upstream retry window or clear the cooldown after validating recovery.",
          target,
          evidence,
          actions: includeActions
            ? [
                action(
                  "clear_connection_cooldown",
                  "Clear connection cooldown",
                  "medium",
                  target,
                  evidence
                ),
                action(
                  "deactivate_connection",
                  "Disable this connection",
                  "medium",
                  target,
                  evidence
                ),
              ]
            : [],
        });
      } else if (hasStaleConnectionError(connection, now)) {
        issues.push({
          id: issueId("stale_connection_error", target),
          severity: "info",
          kind: "stale_connection_error",
          title: `${label} has stale error state`,
          recommendation:
            "Clear stale error fields so the connection is eligible for normal routing again.",
          target,
          evidence,
          actions: includeActions
            ? [
                action(
                  "clear_stale_connection_error",
                  "Clear stale error state",
                  "low",
                  target,
                  evidence
                ),
              ]
            : [],
        });
      }

      if (connection.isActive === false && !terminal) {
        issues.push({
          id: issueId("inactive_connection", target),
          severity: "info",
          kind: "inactive_connection",
          title: `${label} is disabled`,
          recommendation: "Reactivate only if this was not intentionally disabled.",
          target,
          evidence,
          actions: includeActions
            ? [action("reactivate_connection", "Reactivate connection", "medium", target, evidence)]
            : [],
        });
      }
    }

    for (const lockout of providerLockouts) {
      const connectionId = toString(lockout.connectionId);
      const model = toString(lockout.model);
      if (!connectionId || !model) continue;
      const connection = providerConnections.find((entry) => entry.id === connectionId);
      const terminalConnection = connection ? isTerminalConnection(connection) : false;
      const target = { provider, connectionId, model };
      const evidence = {
        reason: lockout.reason ?? null,
        remainingMs: toNumber(lockout.remainingMs) ?? 0,
        failureCount: toNumber(lockout.failureCount) ?? 0,
        lockedAt: lockout.lockedAt ?? null,
        until: lockout.until ?? null,
        connectionExists: Boolean(connection),
        terminalConnection,
      };
      issues.push({
        id: issueId("model_lockout", target),
        severity: terminalConnection || !connection ? "info" : "warning",
        kind: "model_lockout",
        title: `${model} is locked out for one connection`,
        recommendation:
          terminalConnection || !connection
            ? "Resolve the connection state before clearing model-level lockouts."
            : "Clear the model lockout after confirming the model quota or availability recovered.",
        target,
        evidence,
        actions:
          includeActions && connection && !terminalConnection
            ? [action("clear_model_lockout", "Clear model lockout", "medium", target, evidence)]
            : [],
      });
    }

    for (const snapshot of providerQuota) {
      const status = toString(snapshot.status);
      if (!status || !["warning", "exhausted", "error"].includes(status)) continue;
      const connectionId = toString(snapshot.accountId) ?? undefined;
      const sessionId = toString(snapshot.sessionId) ?? undefined;
      const target = { provider, ...(connectionId ? { connectionId } : {}) };
      issues.push({
        id: issueId("quota_monitor_warning", {
          ...target,
          ...(sessionId ? { model: sessionId } : {}),
        }),
        severity: status === "warning" ? "warning" : "critical",
        kind: "quota_monitor_warning",
        title: `Quota monitor reports ${status}`,
        recommendation:
          "Review quota usage and rotate traffic to another healthy connection if needed.",
        target,
        evidence: {
          status,
          lastQuotaPercent: snapshot.lastQuotaPercent ?? null,
          consecutiveFailures: snapshot.consecutiveFailures ?? null,
        },
        actions: [],
      });
    }

    const activeConnections = providerConnections.filter(
      (connection) => connection.isActive !== false
    );
    const cooldownCount = providerConnections.filter((connection) =>
      isConnectionInCooldown(connection, now)
    ).length;
    const terminalCount = providerConnections.filter(isTerminalConnection).length;
    const staleErrors = providerConnections.filter((connection) =>
      hasStaleConnectionError(connection, now)
    ).length;
    const breakerPenalty =
      breaker?.state === "OPEN" ? 0.35 : breaker?.state === "HALF_OPEN" ? 0.2 : 0;
    const total = Math.max(1, providerConnections.length);
    const score = Math.max(
      0,
      Math.min(
        1,
        1 -
          breakerPenalty -
          (cooldownCount / total) * 0.25 -
          (terminalCount / total) * 0.35 -
          Math.min(0.2, providerLockouts.length * 0.05) -
          Math.min(0.1, staleErrors * 0.03)
      )
    );
    const hasCritical = issues.some((issue) => issue.severity === "critical");
    const state: ProviderAutopilotState =
      hasCritical || (providerConnections.length > 0 && activeConnections.length === 0)
        ? "down"
        : issues.length > 0
          ? "degraded"
          : "healthy";

    const item: ProviderAutopilotProvider = {
      provider,
      state,
      score: Number(score.toFixed(2)),
      signals: {
        circuitBreaker: breaker
          ? {
              state: breaker.state,
              failureCount: breaker.failureCount ?? 0,
              retryAfterMs: breaker.retryAfterMs ?? 0,
            }
          : null,
        connections: {
          total: providerConnections.length,
          active: activeConnections.length,
          inactive: providerConnections.filter((connection) => connection.isActive === false)
            .length,
          cooldown: cooldownCount,
          terminal: terminalCount,
          staleErrors,
        },
        modelLockouts: providerLockouts.length,
        quotaMonitor: providerQuota.length
          ? {
              warning: providerQuota.filter((snapshot) => snapshot.status === "warning").length,
              exhausted: providerQuota.filter((snapshot) => snapshot.status === "exhausted").length,
              errors: providerQuota.filter((snapshot) => snapshot.status === "error").length,
            }
          : null,
      },
      issues,
    };

    if (includeHealthy || item.issues.length > 0) providers.push(item);
  }

  const issueCount = providers.reduce((count, provider) => count + provider.issues.length, 0);
  const actionableCount = providers.reduce(
    (count, provider) =>
      count + provider.issues.reduce((sum, issue) => sum + issue.actions.length, 0),
    0
  );
  const healthyCount = providers.filter((provider) => provider.state === "healthy").length;
  const status: ProviderAutopilotStatus = providers.some((provider) => provider.state === "down")
    ? "critical"
    : providers.some((provider) => provider.state === "degraded")
      ? "warning"
      : "healthy";

  return {
    status,
    checkedAt,
    summary: {
      providerCount: providers.length,
      connectionCount: connections.length,
      healthyCount,
      issueCount,
      actionableCount,
    },
    providers,
  };
}

function findAction(
  report: ProviderAutopilotReport,
  input: ExecuteProviderAutopilotActionInput
): ProviderAutopilotAction | null {
  for (const provider of report.providers) {
    for (const issue of provider.issues) {
      const match = issue.actions.find(
        (candidate) =>
          candidate.type === input.type && targetMatches(candidate.target, input.target)
      );
      if (match) return match;
    }
  }
  return null;
}

export async function executeProviderHealthAutopilotAction(
  input: ExecuteProviderAutopilotActionInput
) {
  const provider = toString(input.target.provider);
  if (!provider) {
    return { status: 400, body: { success: false, error: "provider is required" } };
  }
  if (!input.confirm && !input.dryRun) {
    return { status: 400, body: { success: false, error: "confirm must be true" } };
  }

  const report = await buildProviderHealthAutopilotReport({
    provider,
    includeHealthy: true,
    includeActions: true,
  });
  const matchingAction = findAction(report, input);
  if (!matchingAction) {
    return { status: 404, body: { success: false, error: "action is not currently applicable" } };
  }
  if (matchingAction.preconditionsHash !== input.preconditionsHash) {
    return {
      status: 409,
      body: {
        success: false,
        error: "autopilot observation changed; refresh before applying this action",
        currentPreconditionsHash: matchingAction.preconditionsHash,
      },
    };
  }

  if (input.dryRun) {
    return {
      status: 200,
      body: {
        success: true,
        dryRun: true,
        action: input.type,
        target: matchingAction.target,
        checkedAt: new Date().toISOString(),
      },
    };
  }

  let changed: JsonRecord = {};
  switch (input.type) {
    case "clear_provider_breaker":
      clearProviderFailure(provider);
      changed = { circuitBreaker: "CLOSED" };
      break;
    case "clear_connection_cooldown":
    case "clear_stale_connection_error": {
      const connectionId = toString(input.target.connectionId);
      if (!connectionId) {
        return { status: 400, body: { success: false, error: "connectionId is required" } };
      }
      const connection = (await getCachedProviderConnectionById(connectionId)) as JsonRecord | null;
      if (!connection || connection.provider !== provider) {
        return { status: 404, body: { success: false, error: "connection not found" } };
      }
      if (isTerminalConnection(connection)) {
        return { status: 409, body: { success: false, error: "terminal connection state" } };
      }
      await updateProviderConnection(connectionId, buildConnectionClearPatch());
      changed = buildConnectionClearPatch();
      break;
    }
    case "clear_model_lockout": {
      const connectionId = toString(input.target.connectionId);
      const model = toString(input.target.model);
      if (!connectionId || !model) {
        return {
          status: 400,
          body: { success: false, error: "connectionId and model are required" },
        };
      }
      const connection = (await getCachedProviderConnectionById(connectionId)) as JsonRecord | null;
      if (!connection || connection.provider !== provider) {
        return { status: 404, body: { success: false, error: "connection not found" } };
      }
      if (isTerminalConnection(connection)) {
        return { status: 409, body: { success: false, error: "terminal connection state" } };
      }
      const removed = clearModelLock(provider, connectionId, model);
      if (!removed) {
        return {
          status: 409,
          body: { success: false, error: "model lockout changed; refresh before retrying" },
        };
      }
      changed = { removed };
      break;
    }
    case "reactivate_connection":
    case "deactivate_connection": {
      const connectionId = toString(input.target.connectionId);
      if (!connectionId) {
        return { status: 400, body: { success: false, error: "connectionId is required" } };
      }
      const connection = (await getCachedProviderConnectionById(connectionId)) as JsonRecord | null;
      if (!connection || connection.provider !== provider) {
        return { status: 404, body: { success: false, error: "connection not found" } };
      }
      if (input.type === "reactivate_connection" && isTerminalConnection(connection)) {
        return { status: 409, body: { success: false, error: "terminal connection state" } };
      }
      const isActive = input.type === "reactivate_connection";
      await updateProviderConnection(connectionId, { isActive });
      changed = { isActive };
      break;
    }
  }

  return {
    status: 200,
    body: {
      success: true,
      dryRun: false,
      action: input.type,
      target: matchingAction.target,
      changed,
      checkedAt: new Date().toISOString(),
    },
  };
}

import { getSyncedAvailableModelsByConnection } from "@/lib/db/models";
import { getProviderConnections } from "@/lib/db/providers";
import { getDbInstance } from "@/lib/db/core";
import { getAllCircuitBreakerStatuses } from "@/shared/utils/circuitBreaker";
import { getAllModelLockouts } from "@omniroute/open-sse/services/accountFallback";
import { getWebSessionPoolHealth } from "@omniroute/open-sse/services/webSessionPoolHealth";

type JsonRecord = Record<string, unknown>;

export type ProviderHealthMatrixRange = "1h" | "24h" | "7d" | "30d";
export type ProviderHealthState = "healthy" | "degraded" | "down";
export type ProviderModelHealthStatus = "healthy" | "degraded" | "error" | "locked" | "idle";

export interface ProviderHealthMatrixOptions {
  provider?: string | null;
  range?: ProviderHealthMatrixRange | string | null;
  includeHealthy?: boolean;
}

export interface ProviderHealthMatrixModel {
  model: string;
  status: ProviderModelHealthStatus;
  isLockedOut: boolean;
  lockoutReason: string | null;
  lockoutRemainingMs: number;
  requests: number;
  successes: number;
  successRate: number | null;
  avgLatencyMs: number | null;
  lastStatus: number | null;
  lastErrorStatus: number | null;
  lastRequestAt: string | null;
  lastErrorAt: string | null;
}

export interface ProviderHealthMatrixAccount {
  connectionId: string | null;
  label: string;
  isSynthetic: boolean;
  isActive: boolean;
  state: ProviderHealthState;
  testStatus: string | null;
  rateLimitedUntil: string | null;
  cooldownRemainingMs: number;
  lastErrorType: string | null;
  errorCode: string | null;
  backoffLevel: number;
  modelCount: number;
  issueCount: number;
  models: ProviderHealthMatrixModel[];
}

export interface ProviderHealthMatrixProvider {
  provider: string;
  state: ProviderHealthState;
  score: number;
  circuitBreaker: {
    state: string;
    failureCount: number;
    retryAfterMs: number;
    lastFailureTime: number | null;
  } | null;
  connections: {
    total: number;
    active: number;
    cooldown: number;
    inactive: number;
    terminal: number;
  };
  modelLockoutCount: number;
  requests: number;
  successRate: number | null;
  avgLatencyMs: number | null;
  lastRequestAt: string | null;
  lastErrorAt: string | null;
  issueCount: number;
  accounts: ProviderHealthMatrixAccount[];
}

export interface ProviderHealthMatrixResponse {
  checkedAt: string;
  range: ProviderHealthMatrixRange;
  cutoff: string;
  summary: {
    providerCount: number;
    connectionCount: number;
    modelCount: number;
    issueCount: number;
    healthyCount: number;
    degradedCount: number;
    downCount: number;
  };
  providers: ProviderHealthMatrixProvider[];
  webSessionPools: {
    totalPools: number;
    healthyPools: number;
    degradedPools: number;
    downPools: number;
    pools: Array<{
      provider: string;
      health: "healthy" | "degraded" | "down";
      pool: Record<string, unknown> | null;
      breaker: Record<string, unknown> | null;
      sessions: Array<Record<string, unknown>>;
      issues: string[];
    }>;
  };
}

interface CallLogTargetStats {
  provider: string;
  connectionId: string | null;
  model: string;
  requests: number;
  successes: number;
  avgLatencyMs: number | null;
  lastRequestAt: string | null;
  lastErrorAt: string | null;
  lastStatus: number | null;
  lastErrorStatus: number | null;
}

const RANGE_MS: Record<ProviderHealthMatrixRange, number> = {
  "1h": 60 * 60 * 1000,
  "24h": 24 * 60 * 60 * 1000,
  "7d": 7 * 24 * 60 * 60 * 1000,
  "30d": 30 * 24 * 60 * 60 * 1000,
};

const TERMINAL_STATUSES = new Set(["banned", "expired", "credits_exhausted"]);

function toString(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function toNumber(value: unknown): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim()) {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

function parseTimeMs(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim()) {
    const numeric = Number(value);
    if (Number.isFinite(numeric)) return numeric;
    const parsed = Date.parse(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

function normalizeRange(value: ProviderHealthMatrixOptions["range"]): ProviderHealthMatrixRange {
  return value === "1h" || value === "7d" || value === "30d" ? value : "24h";
}

function isActiveConnection(value: unknown): boolean {
  return value !== false && value !== 0;
}

function isTerminalConnection(connection: JsonRecord): boolean {
  const status = toString(connection.testStatus)?.toLowerCase();
  const errorType = toString(connection.lastErrorType)?.toLowerCase();
  return Boolean(
    (status && TERMINAL_STATUSES.has(status)) || (errorType && TERMINAL_STATUSES.has(errorType))
  );
}

function sanitizeConnectionLabel(connection: JsonRecord): string {
  const label =
    toString(connection.name) ||
    toString(connection.displayName) ||
    toString(connection.email) ||
    toString(connection.id) ||
    "connection";
  const masked = label.includes("@") ? label.replace(/^(.).+(@.+)$/, "$1***$2") : label;
  return masked.length > 80 ? `${masked.slice(0, 77)}…` : masked;
}

function statsKey(provider: string, connectionId: string | null, model: string): string {
  return `${provider}\u0000${connectionId ?? ""}\u0000${model}`;
}

function accountKey(provider: string, connectionId: string | null): string {
  return `${provider}\u0000${connectionId ?? ""}`;
}

function modelLockKey(provider: string, connectionId: string | null, model: string): string {
  return `${provider}\u0000${connectionId ?? ""}\u0000${model}`;
}

function hasFailureStatus(status: number | null): boolean {
  return status !== null && (status < 200 || status >= 400);
}

function computeSuccessRate(requests: number, successes: number): number | null {
  return requests > 0 ? Math.round((successes / requests) * 100) : null;
}

function maxIso(left: string | null, right: string | null): string | null {
  if (!left) return right;
  if (!right) return left;
  return Date.parse(right) > Date.parse(left) ? right : left;
}

function queryCallLogTargetStats(
  cutoff: string,
  providerFilter: string | null
): CallLogTargetStats[] {
  const db = getDbInstance();
  const providerClause = providerFilter ? "AND c.provider = @provider" : "";
  const params = providerFilter ? { cutoff, provider: providerFilter } : { cutoff };
  const rows = db
    .prepare(
      `WITH log_targets AS (
        SELECT
          c.provider,
          COALESCE(c.connection_id, '') as connectionId,
          COALESCE(c.model, c.requested_model, 'unknown') as model,
          c.status,
          c.duration,
          c.timestamp,
          c.id,
          c.error_summary
        FROM call_logs c
        WHERE c.provider IS NOT NULL
          AND c.provider != '-'
          AND c.timestamp >= @cutoff
          ${providerClause}
      ), ranked AS (
        SELECT
          provider,
          connectionId,
          model,
          status,
          duration,
          timestamp,
          CASE
            WHEN (status IS NOT NULL AND (status < 200 OR status >= 400))
              OR error_summary IS NOT NULL
            THEN 1
            ELSE 0
          END as isError,
          ROW_NUMBER() OVER (
            PARTITION BY provider, connectionId, model
            ORDER BY timestamp DESC, id DESC
          ) as latestRank,
          ROW_NUMBER() OVER (
            PARTITION BY provider, connectionId, model,
              CASE
                WHEN (status IS NOT NULL AND (status < 200 OR status >= 400))
                  OR error_summary IS NOT NULL
                THEN 1
                ELSE 0
              END
            ORDER BY timestamp DESC, id DESC
          ) as errorRank
        FROM log_targets
      )
      SELECT
        provider,
        connectionId,
        model,
        COUNT(*) as requests,
        SUM(CASE WHEN status >= 200 AND status < 400 THEN 1 ELSE 0 END) as successes,
        ROUND(AVG(duration)) as avgLatencyMs,
        MAX(timestamp) as lastRequestAt,
        MAX(
          CASE
            WHEN isError = 1
            THEN timestamp
            ELSE NULL
          END
        ) as lastErrorAt,
        MAX(CASE WHEN latestRank = 1 THEN status ELSE NULL END) as lastStatus,
        MAX(CASE WHEN isError = 1 AND errorRank = 1 THEN status ELSE NULL END) as lastErrorStatus
      FROM ranked
      GROUP BY provider, connectionId, model`
    )
    .all(params) as JsonRecord[];

  return rows.map((row) => {
    const connectionId = toString(row.connectionId);
    return {
      provider: toString(row.provider) || "unknown",
      connectionId: connectionId || null,
      model: toString(row.model) || "unknown",
      requests: toNumber(row.requests),
      successes: toNumber(row.successes),
      avgLatencyMs: row.avgLatencyMs == null ? null : toNumber(row.avgLatencyMs),
      lastRequestAt: toString(row.lastRequestAt),
      lastErrorAt: toString(row.lastErrorAt),
      lastStatus: row.lastStatus == null ? null : toNumber(row.lastStatus),
      lastErrorStatus: row.lastErrorStatus == null ? null : toNumber(row.lastErrorStatus),
    };
  });
}

function classifyModel(
  stats: CallLogTargetStats | null,
  locked: boolean
): ProviderModelHealthStatus {
  if (locked) return "locked";
  if (!stats || stats.requests === 0) return "idle";
  if (hasFailureStatus(stats.lastStatus)) return "error";
  const successRate = computeSuccessRate(stats.requests, stats.successes);
  if (successRate !== null && successRate < 95) return "degraded";
  return "healthy";
}

function classifyAccount(
  connection: JsonRecord | null,
  models: ProviderHealthMatrixModel[],
  now: number
): ProviderHealthState {
  if (connection) {
    if (!isActiveConnection(connection.isActive) || isTerminalConnection(connection)) return "down";
    const cooldownUntil = parseTimeMs(connection.rateLimitedUntil);
    if (cooldownUntil && cooldownUntil > now) return "degraded";
  }
  if (models.some((model) => model.status === "error" || model.status === "locked")) {
    return "degraded";
  }
  return "healthy";
}

function classifyProvider(
  breaker: ProviderHealthMatrixProvider["circuitBreaker"],
  accounts: ProviderHealthMatrixAccount[]
): ProviderHealthState {
  if (breaker?.state === "OPEN") return "down";
  if (breaker?.state === "HALF_OPEN") return "degraded";
  if (accounts.length > 0 && accounts.every((account) => account.state === "down")) return "down";
  if (accounts.some((account) => account.state !== "healthy")) return "degraded";
  return "healthy";
}

export async function buildProviderHealthMatrix(
  options: ProviderHealthMatrixOptions = {}
): Promise<ProviderHealthMatrixResponse> {
  const now = Date.now();
  const checkedAt = new Date(now).toISOString();
  const range = normalizeRange(options.range);
  const cutoff = new Date(now - RANGE_MS[range]).toISOString();
  const providerFilter = toString(options.provider);
  const includeHealthy = options.includeHealthy !== false;

  const [connections, breakers, lockouts, stats] = await Promise.all([
    getProviderConnections(providerFilter ? { provider: providerFilter } : {}),
    getAllCircuitBreakerStatuses(),
    getAllModelLockouts(),
    Promise.resolve(queryCallLogTargetStats(cutoff, providerFilter)),
  ]);

  const connectionRows = (connections as JsonRecord[]).filter((connection) => {
    const provider = toString(connection.provider);
    return provider && (!providerFilter || provider === providerFilter);
  });
  const breakerRows = (breakers as JsonRecord[]).filter((breaker) => {
    const provider = toString(breaker.name);
    return provider && (!providerFilter || provider === providerFilter);
  });
  const lockoutRows = (lockouts as JsonRecord[]).filter((lockout) => {
    const provider = toString(lockout.provider);
    return provider && (!providerFilter || provider === providerFilter);
  });

  const providerIds = new Set<string>();
  for (const connection of connectionRows) {
    const provider = toString(connection.provider);
    if (provider) providerIds.add(provider);
  }
  for (const breaker of breakerRows) {
    const provider = toString(breaker.name);
    if (provider) providerIds.add(provider);
  }
  for (const lockout of lockoutRows) {
    const provider = toString(lockout.provider);
    if (provider) providerIds.add(provider);
  }
  for (const row of stats) providerIds.add(row.provider);
  if (providerFilter) providerIds.add(providerFilter);

  const syncedModelsByProvider = new Map<
    string,
    Awaited<ReturnType<typeof getSyncedAvailableModelsByConnection>>
  >();
  await Promise.all(
    [...providerIds].map(async (provider) => {
      syncedModelsByProvider.set(provider, await getSyncedAvailableModelsByConnection(provider));
    })
  );

  const statsByTarget = new Map<string, CallLogTargetStats>();
  const statsByAccount = new Map<string, CallLogTargetStats[]>();
  for (const row of stats) {
    statsByTarget.set(statsKey(row.provider, row.connectionId, row.model), row);
    const key = accountKey(row.provider, row.connectionId);
    const current = statsByAccount.get(key) ?? [];
    current.push(row);
    statsByAccount.set(key, current);
  }

  const lockoutsByTarget = new Map<string, JsonRecord>();
  const lockoutCountByProvider = new Map<string, number>();
  for (const lockout of lockoutRows) {
    const provider = toString(lockout.provider);
    const connectionId = toString(lockout.connectionId);
    const model = toString(lockout.model);
    if (!provider || !model) continue;
    lockoutsByTarget.set(modelLockKey(provider, connectionId, model), lockout);
    lockoutCountByProvider.set(provider, (lockoutCountByProvider.get(provider) ?? 0) + 1);
  }

  const providers: ProviderHealthMatrixProvider[] = [];
  for (const provider of [...providerIds].sort()) {
    const providerConnections = connectionRows.filter(
      (connection) => toString(connection.provider) === provider
    );
    const providerStats = stats.filter((row) => row.provider === provider);
    const providerBreaker = breakerRows.find((breaker) => toString(breaker.name) === provider);
    const circuitBreaker = providerBreaker
      ? {
          state: toString(providerBreaker.state) || "CLOSED",
          failureCount: toNumber(providerBreaker.failureCount),
          retryAfterMs: toNumber(providerBreaker.retryAfterMs),
          lastFailureTime:
            providerBreaker.lastFailureTime == null
              ? null
              : toNumber(providerBreaker.lastFailureTime),
        }
      : null;

    const accountRows = new Map<string, JsonRecord | null>();
    for (const connection of providerConnections) {
      accountRows.set(accountKey(provider, toString(connection.id)), connection);
    }
    for (const stat of providerStats) {
      const key = accountKey(provider, stat.connectionId);
      if (!accountRows.has(key)) accountRows.set(key, null);
    }
    for (const lockout of lockoutRows) {
      if (toString(lockout.provider) !== provider) continue;
      const key = accountKey(provider, toString(lockout.connectionId));
      if (!accountRows.has(key)) accountRows.set(key, null);
    }

    const accounts: ProviderHealthMatrixAccount[] = [];
    const providerSyncedModels = syncedModelsByProvider.get(provider) ?? {};
    for (const [key, connection] of [...accountRows.entries()].sort()) {
      const [, connectionPart] = key.split("\u0000");
      const connectionId = connection ? toString(connection.id) : connectionPart || null;
      const modelIds = new Set<string>();
      if (connectionId && connection) {
        const syncedModels = providerSyncedModels[connectionId] ?? [];
        for (const model of syncedModels) {
          if (model.id) modelIds.add(model.id);
        }
        const defaultModel = toString(connection.defaultModel);
        if (defaultModel) modelIds.add(defaultModel);
      }
      for (const stat of statsByAccount.get(accountKey(provider, connectionId)) ?? []) {
        modelIds.add(stat.model);
      }
      for (const lockout of lockoutRows) {
        if (toString(lockout.provider) !== provider) continue;
        if ((toString(lockout.connectionId) ?? "") !== (connectionId ?? "")) continue;
        const model = toString(lockout.model);
        if (model) modelIds.add(model);
      }

      const models = [...modelIds].sort().map((model): ProviderHealthMatrixModel => {
        const stat = statsByTarget.get(statsKey(provider, connectionId, model)) ?? null;
        const lockout = lockoutsByTarget.get(modelLockKey(provider, connectionId, model)) ?? null;
        const isLockedOut = Boolean(lockout);
        const status = classifyModel(stat, isLockedOut);
        return {
          model,
          status,
          isLockedOut,
          lockoutReason: lockout ? toString(lockout.reason) : null,
          lockoutRemainingMs: lockout ? Math.max(0, toNumber(lockout.remainingMs)) : 0,
          requests: stat?.requests ?? 0,
          successes: stat?.successes ?? 0,
          successRate: stat ? computeSuccessRate(stat.requests, stat.successes) : null,
          avgLatencyMs: stat?.avgLatencyMs ?? null,
          lastStatus: stat?.lastStatus ?? null,
          lastErrorStatus: stat?.lastErrorStatus ?? null,
          lastRequestAt: stat?.lastRequestAt ?? null,
          lastErrorAt: stat?.lastErrorAt ?? null,
        };
      });

      const cooldownUntil = connection ? parseTimeMs(connection.rateLimitedUntil) : null;
      const cooldownRemainingMs = cooldownUntil ? Math.max(0, cooldownUntil - now) : 0;
      const state = classifyAccount(connection, models, now);
      const issueCount =
        (state === "healthy" ? 0 : 1) +
        models.filter((model) => model.status === "error" || model.status === "locked").length;
      accounts.push({
        connectionId,
        label: connection
          ? sanitizeConnectionLabel(connection)
          : connectionId || "Unattributed traffic",
        isSynthetic: !connection,
        isActive: connection ? isActiveConnection(connection.isActive) : true,
        state,
        testStatus: connection ? toString(connection.testStatus) : null,
        rateLimitedUntil: connection ? toString(connection.rateLimitedUntil) : null,
        cooldownRemainingMs,
        lastErrorType: connection ? toString(connection.lastErrorType) : null,
        errorCode: connection ? toString(connection.errorCode) : null,
        backoffLevel: connection ? toNumber(connection.backoffLevel) : 0,
        modelCount: models.length,
        issueCount,
        models,
      });
    }

    const requests = providerStats.reduce((sum, row) => sum + row.requests, 0);
    const successes = providerStats.reduce((sum, row) => sum + row.successes, 0);
    const weightedLatency = providerStats.reduce(
      (sum, row) => sum + (row.avgLatencyMs ?? 0) * row.requests,
      0
    );
    const state = classifyProvider(circuitBreaker, accounts);
    const issueCount =
      (state === "healthy" ? 0 : 1) +
      accounts.reduce((sum, account) => sum + account.issueCount, 0);
    const totalConnections = providerConnections.length;
    const activeConnections = providerConnections.filter((connection) =>
      isActiveConnection(connection.isActive)
    ).length;
    const cooldownConnections = providerConnections.filter((connection) => {
      const until = parseTimeMs(connection.rateLimitedUntil);
      return Boolean(until && until > now);
    }).length;
    const terminalConnections = providerConnections.filter(isTerminalConnection).length;
    const modelLockoutCount = lockoutCountByProvider.get(provider) ?? 0;
    const scorePenalty =
      (circuitBreaker?.state === "OPEN" ? 0.4 : circuitBreaker?.state === "HALF_OPEN" ? 0.2 : 0) +
      (totalConnections > 0 ? (cooldownConnections / totalConnections) * 0.2 : 0) +
      (totalConnections > 0 ? (terminalConnections / totalConnections) * 0.25 : 0) +
      Math.min(0.2, modelLockoutCount * 0.05) +
      Math.min(0.15, accounts.filter((account) => account.state === "down").length * 0.05);

    const providerRow: ProviderHealthMatrixProvider = {
      provider,
      state,
      score: Number(Math.max(0, Math.min(1, 1 - scorePenalty)).toFixed(2)),
      circuitBreaker,
      connections: {
        total: totalConnections,
        active: activeConnections,
        cooldown: cooldownConnections,
        inactive: providerConnections.filter(
          (connection) => !isActiveConnection(connection.isActive)
        ).length,
        terminal: terminalConnections,
      },
      modelLockoutCount,
      requests,
      successRate: computeSuccessRate(requests, successes),
      avgLatencyMs: requests > 0 ? Math.round(weightedLatency / requests) : null,
      lastRequestAt: providerStats.reduce<string | null>(
        (latest, row) => maxIso(latest, row.lastRequestAt),
        null
      ),
      lastErrorAt: providerStats.reduce<string | null>(
        (latest, row) => maxIso(latest, row.lastErrorAt),
        null
      ),
      issueCount,
      accounts,
    };

    if (includeHealthy || providerRow.state !== "healthy" || providerRow.issueCount > 0) {
      providers.push(providerRow);
    }
  }

  const poolReport = getWebSessionPoolHealth(providerFilter ?? undefined);

  return {
    checkedAt,
    range,
    cutoff,
    summary: {
      providerCount: providers.length,
      connectionCount: providers.reduce((sum, provider) => sum + provider.connections.total, 0),
      modelCount: providers.reduce(
        (sum, provider) =>
          sum +
          provider.accounts.reduce((accountSum, account) => accountSum + account.modelCount, 0),
        0
      ),
      issueCount: providers.reduce((sum, provider) => sum + provider.issueCount, 0),
      healthyCount: providers.filter((provider) => provider.state === "healthy").length,
      degradedCount: providers.filter((provider) => provider.state === "degraded").length,
      downCount: providers.filter((provider) => provider.state === "down").length,
    },
    providers,
    webSessionPools: {
      totalPools: poolReport.providers.length,
      healthyPools: poolReport.providers.filter((p) => p.health === "healthy").length,
      degradedPools: poolReport.providers.filter((p) => p.health === "degraded").length,
      downPools: poolReport.providers.filter((p) => p.health === "down").length,
      pools: poolReport.providers.map((p) => ({
        provider: p.provider,
        health: p.health,
        pool: p.pool as Record<string, unknown> | null,
        breaker: p.breaker as Record<string, unknown> | null,
        sessions: p.sessions as Array<Record<string, unknown>>,
        issues: p.issues,
      })),
    },
  };
}

type JsonRecord = Record<string, unknown>;

export type GitLabDirectAccessDetails = {
  token: string;
  baseUrl: string;
  expiresAt: string | null;
  headers: Record<string, string>;
};

export const GITLAB_DUO_DEFAULT_BASE_URL =
  process.env.GITLAB_DUO_BASE_URL || process.env.GITLAB_BASE_URL || "https://gitlab.com";

function asRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

export function normalizeGitLabBaseUrl(baseUrl?: unknown): string {
  const raw = typeof baseUrl === "string" ? baseUrl.trim() : "";
  return (raw || GITLAB_DUO_DEFAULT_BASE_URL).replace(/\/$/, "");
}

export function resolveGitLabOAuthBaseUrl(providerSpecificData?: unknown): string {
  const data = asRecord(providerSpecificData);
  return normalizeGitLabBaseUrl(data.baseUrl);
}

export function buildGitLabOAuthEndpoints(baseUrl?: unknown) {
  const root = normalizeGitLabBaseUrl(baseUrl);
  return {
    root,
    authorizeUrl: `${root}/oauth/authorize`,
    tokenUrl: `${root}/oauth/token`,
    userUrl: `${root}/api/v4/user`,
    directAccessUrl: `${root}/api/v4/code_suggestions/direct_access`,
    publicCompletionsUrl: `${root}/api/v4/code_suggestions/completions`,
  };
}

export function buildGitLabDirectGatewayUrl(baseUrl: string): string {
  const normalized = normalizeGitLabBaseUrl(baseUrl);
  if (normalized.endsWith("/ai/v2/completions")) {
    return normalized;
  }
  if (normalized.endsWith("/ai/v2")) {
    return `${normalized}/completions`;
  }
  return `${normalized}/ai/v2/completions`;
}

export function parseGitLabDirectAccessDetails(payload: unknown): GitLabDirectAccessDetails | null {
  const data = asRecord(payload);
  const token = typeof data.token === "string" ? data.token.trim() : "";
  const baseUrl = typeof data.base_url === "string" ? data.base_url.trim() : "";
  if (!token || !baseUrl) {
    return null;
  }

  const rawHeaders = asRecord(data.headers);
  const headers = Object.fromEntries(
    Object.entries(rawHeaders).filter(
      (entry): entry is [string, string] =>
        typeof entry[0] === "string" && typeof entry[1] === "string"
    )
  );

  const expiresAt =
    typeof data.expires_at === "number" && Number.isFinite(data.expires_at)
      ? new Date(data.expires_at * 1000).toISOString()
      : null;

  return {
    token,
    baseUrl: normalizeGitLabBaseUrl(baseUrl),
    expiresAt,
    headers,
  };
}

export function getCachedGitLabDirectAccess(
  providerSpecificData?: unknown,
  minValidityMs = 60_000
): GitLabDirectAccessDetails | null {
  const data = asRecord(providerSpecificData);
  const cache = data.gitlabDirectAccess ?? data.directAccessCache;
  const parsed = parseGitLabDirectAccessDetails(cache);
  if (!parsed) {
    return null;
  }
  if (!parsed.expiresAt) {
    return parsed;
  }

  const expiresAtMs = new Date(parsed.expiresAt).getTime();
  if (!Number.isFinite(expiresAtMs) || expiresAtMs <= Date.now() + minValidityMs) {
    return null;
  }

  return parsed;
}

export function isGitLabDirectAccessDisabled(status: number, bodyText: string): boolean {
  return status === 403 && bodyText.toLowerCase().includes("direct connections are disabled");
}

import crypto from "node:crypto";
import { CLAUDE_CONFIG } from "../constants/oauth";
import { CLAUDE_CODE_VERSION } from "@omniroute/open-sse/executors/claudeIdentity.ts";

const BOOTSTRAP_FETCH_TIMEOUT_MS = 10_000;

// Best-effort: failure must not block OAuth — the access token is valid.
async function fetchClaudeBootstrap(accessToken) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), BOOTSTRAP_FETCH_TIMEOUT_MS);
  try {
    const res = await fetch("https://api.anthropic.com/api/claude_cli/bootstrap", {
      method: "GET",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        Accept: "application/json",
        "User-Agent": `claude-cli/${CLAUDE_CODE_VERSION} (external, cli)`,
        "anthropic-beta": "oauth-2025-04-20",
      },
      signal: ctrl.signal,
    });
    if (!res.ok) return null;
    const data = await res.json();
    const acct = data?.oauth_account;
    if (!acct || typeof acct !== "object") return null;
    return {
      account_uuid: acct.account_uuid || null,
      account_email: acct.account_email || null,
      organization_uuid: acct.organization_uuid || null,
      organization_name: acct.organization_name || null,
      organization_type: acct.organization_type || null,
      organization_rate_limit_tier: acct.organization_rate_limit_tier || null,
    };
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

function toRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function firstNonEmptyString(...values: unknown[]): string | undefined {
  for (const value of values) {
    if (typeof value !== "string") {
      continue;
    }

    const trimmed = value.trim();
    if (trimmed) {
      return trimmed;
    }
  }

  return undefined;
}

function extractPlanFromPayload(payload: unknown): string | undefined {
  const data = toRecord(payload);
  const billing = toRecord(data.billing);

  return firstNonEmptyString(data.account_tier, data.plan, data.subscription_type, billing.plan);
}

function extractClaudePlan(tokens: unknown, extra: unknown): string | undefined {
  const extraData = toRecord(extra);

  return firstNonEmptyString(
    extractPlanFromPayload(tokens),
    extractPlanFromPayload(extraData.userInfo),
    extractPlanFromPayload(extra)
  );
}

export const claude = {
  config: CLAUDE_CONFIG,
  flowType: "authorization_code_pkce",
  buildAuthUrl: (config, _redirectUri, state, codeChallenge) => {
    const params = new URLSearchParams({
      code: "true",
      client_id: config.clientId,
      response_type: "code",
      redirect_uri: config.redirectUri,
      scope: config.scopes.join(" "),
      code_challenge: codeChallenge,
      code_challenge_method: config.codeChallengeMethod,
      state: state,
      // prompt=login forces Anthropic IdP to RE-AUTHENTICATE the user on each
      // OAuth flow instead of silently reusing the browser session. Prevents
      // the "session takeover" that invalidates the previous account's
      // refresh_token family on the same client_id. Same pattern that unlocked
      // multi-account Codex — applied defensively here because Anthropic's
      // OAuth uses the same client_id across all accounts AND the user reports
      // Claude tokens expiring in multi-account scenarios.
      prompt: "login",
    });
    return `${config.authorizeUrl}?${params.toString()}`;
  },
  exchangeToken: async (config, code, _redirectUri, codeVerifier, state) => {
    let authCode = code;
    let codeState = "";
    if (authCode.includes("#")) {
      const parts = authCode.split("#");
      authCode = parts[0];
      codeState = parts[1] || "";
    }

    const response = await fetch(config.tokenUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify({
        code: authCode,
        state: codeState || state,
        grant_type: "authorization_code",
        client_id: config.clientId,
        redirect_uri: config.redirectUri,
        code_verifier: codeVerifier,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      throw new Error(`Token exchange failed: ${error}`);
    }

    return await response.json();
  },
  // Runs after exchangeToken; result is passed as `extra` to mapTokens.
  postExchange: async (tokens) => {
    if (!tokens?.access_token) return null;
    return await fetchClaudeBootstrap(tokens.access_token);
  },
  mapTokens: (tokens, extra) => {
    const plan = extractClaudePlan(tokens, extra);
    const bs = extra || {};
    const providerSpecificData: any = {
      // Generated once at provisioning; preserved across token refresh.
      cliUserID: crypto.randomBytes(32).toString("hex"),
    };
    if (bs.account_uuid) providerSpecificData.accountUUID = bs.account_uuid;
    if (bs.organization_uuid) providerSpecificData.organizationUUID = bs.organization_uuid;
    if (bs.organization_name) providerSpecificData.organizationName = bs.organization_name;
    if (bs.organization_type) providerSpecificData.organizationType = bs.organization_type;
    if (bs.organization_rate_limit_tier)
      providerSpecificData.organizationRateLimitTier = bs.organization_rate_limit_tier;
    if (plan) providerSpecificData.plan = plan;

    const result: any = {
      accessToken: tokens.access_token,
      refreshToken: tokens.refresh_token,
      expiresIn: tokens.expires_in,
      scope: tokens.scope,
    };
    if (bs.account_email) {
      result.email = bs.account_email;
      result.displayName = bs.account_email;
    }
    if (Object.keys(providerSpecificData).length > 0) {
      result.providerSpecificData = providerSpecificData;
    }
    return result;
  },
};

import { getProviderConnections, updateProviderConnection } from "@/lib/db/providers"
import { createProviderConnection } from "@/lib/localDb";
import { AGY_CONFIG } from "@/lib/oauth/constants/oauth";
import {
  getAntigravityContentHeaders,
  getAntigravityLoadCodeAssistMetadata,
} from "@omniroute/open-sse/services/antigravityHeaders.ts";
import { extractCodeAssistOnboardTierId } from "@omniroute/open-sse/services/codeAssistSubscription.ts";

type JsonRecord = Record<string, unknown>;

function toRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function toNonEmptyString(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
}

/**
 * Error carrying an HTTP status + machine code so the
 * agy-auth routes can translate it to a clean response (never a raw stack trace).
 */
export class AgyAuthFileError extends Error {
  status: number;
  code: string;

  constructor(message: string, status = 400, code = "invalid_request") {
    super(message);
    this.name = "AgyAuthFileError";
    this.status = status;
    this.code = code;
  }
}

// ──── Public types ────────────────────────────────────────────────────────────

export interface ParsedAgyAuth {
  accessToken: string;
  refreshToken: string;
  tokenType: string;
  expiresAt: string | null;
  authMethod: string | null;
}

export interface EnrichedAgyAuth extends ParsedAgyAuth {
  email: string | null;
  projectId: string | null;
  tier: string | null;
}

export interface CreateAgyConnectionOptions {
  name?: string;
  email?: string;
  overwriteExisting?: boolean;
}

// ──── Parse & validate ────────────────────────────────────────────────────────

/**
 * Parse the Antigravity CLI (`agy`) token file. It nests the token under `.token`,
 * uses an ISO `expiry` string, and has NO `id_token`. A flat top-level shape is
 * accepted as a fallback.
 */
export function parseAndValidateAgyToken(raw: unknown): ParsedAgyAuth {
  const doc = toRecord(raw);
  // agy nests credentials under `.token`; fall back to the top level for flat exports.
  const token = doc.token && typeof doc.token === "object" ? toRecord(doc.token) : doc;

  const accessToken = toNonEmptyString(token.access_token);
  const refreshToken = toNonEmptyString(token.refresh_token);

  if (!accessToken) {
    throw new AgyAuthFileError(
      "access_token is missing or empty in the agy token file",
      400,
      "missing_access_token"
    );
  }

  if (!refreshToken) {
    throw new AgyAuthFileError(
      "refresh_token is missing or empty in the agy token file",
      400,
      "missing_refresh_token"
    );
  }

  // agy uses an ISO `expiry`; also accept a unix-ms `expiry_date`/`expires_at` for safety.
  let expiresAt: string | null = null;
  const isoExpiry = toNonEmptyString(token.expiry) ?? toNonEmptyString(token.expires_at);
  if (isoExpiry) {
    const ms = new Date(isoExpiry).getTime();
    expiresAt = Number.isNaN(ms) ? null : new Date(ms).toISOString();
  } else if (typeof token.expiry_date === "number" && Number.isFinite(token.expiry_date)) {
    expiresAt = new Date(token.expiry_date).toISOString();
  }

  const tokenType = toNonEmptyString(token.token_type) ?? "Bearer";
  const authMethod = toNonEmptyString(doc.auth_method) ?? toNonEmptyString(token.auth_method);

  return { accessToken, refreshToken, tokenType, expiresAt, authMethod };
}

// ──── Enrich with the Antigravity Code Assist backend ─────────────────────────

/**
 * Resolve the account email (userinfo) and GCP project id (loadCodeAssist) for the token.
 * Best-effort + time-boxed; the agy CLI has already onboarded the project, so we do NOT
 * run the onboardUser provisioning loop here (that can take up to ~50s).
 */
export async function enrichWithAntigravityBackend(
  parsed: ParsedAgyAuth
): Promise<EnrichedAgyAuth> {
  let email: string | null = null;
  let projectId: string | null = null;
  let tier: string | null = null;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);
  try {
    const userInfoRes = await fetch(`${AGY_CONFIG.userInfoUrl}?alt=json`, {
      headers: { Authorization: `Bearer ${parsed.accessToken}` },
      signal: controller.signal,
    });
    if (userInfoRes.ok) {
      email = toNonEmptyString(toRecord(await userInfoRes.json()).email);
    }
  } catch {
    // best effort — email stays null
  } finally {
    clearTimeout(timer);
  }

  const loadController = new AbortController();
  const loadTimer = setTimeout(() => loadController.abort(), 8000);
  try {
    const headers = getAntigravityContentHeaders("cli", parsed.accessToken);
    const metadata = getAntigravityLoadCodeAssistMetadata();
    for (const endpoint of AGY_CONFIG.loadCodeAssistEndpoints) {
      try {
        const res = await fetch(endpoint, {
          method: "POST",
          headers,
          body: JSON.stringify({ metadata }),
          signal: loadController.signal,
        });
        if (!res.ok) continue;
        const data = toRecord(await res.json());
        const project = data.cloudaicompanionProject;
        projectId =
          (typeof project === "string" ? toNonEmptyString(project) : null) ??
          toNonEmptyString(toRecord(project).id);
        tier = extractCodeAssistOnboardTierId(data) || null;
        break;
      } catch {
        // try next endpoint
      }
    }
  } catch {
    // best effort — projectId stays null
  } finally {
    clearTimeout(loadTimer);
  }

  return { ...parsed, email, projectId, tier };
}

// ──── Find existing connection ────────────────────────────────────────────────

export async function findExistingAgyConnection(email: string): Promise<JsonRecord | null> {
  const connections = await getProviderConnections({ provider: "agy" });
  const lowerEmail = email.toLowerCase();
  return (
    (connections.find((c) => {
      const conn = c as JsonRecord;
      return toNonEmptyString(conn.email)?.toLowerCase() === lowerEmail;
    }) as JsonRecord | undefined) ?? null
  );
}

// ──── Create / update connection ──────────────────────────────────────────────

export async function createConnectionFromAgyToken(
  enriched: EnrichedAgyAuth,
  options: CreateAgyConnectionOptions
): Promise<{ connection: JsonRecord; created: boolean }> {
  const resolvedEmail = options.email || enriched.email;

  if (resolvedEmail) {
    const existing = await findExistingAgyConnection(resolvedEmail);
    if (existing) {
      if (!options.overwriteExisting) {
        throw new AgyAuthFileError(
          "An Antigravity CLI connection for this account already exists. Pass overwriteExisting: true to replace it.",
          409,
          "duplicate_account"
        );
      }

      const updated = await updateProviderConnection(existing.id as string, {
        accessToken: enriched.accessToken,
        refreshToken: enriched.refreshToken,
        expiresAt: enriched.expiresAt,
        email: resolvedEmail || (existing.email as string | undefined),
        name:
          options.name ||
          (existing.name as string | undefined) ||
          resolvedEmail ||
          "Antigravity CLI (imported)",
        testStatus: "active",
        isActive: true,
        providerSpecificData: {
          ...toRecord(existing.providerSpecificData),
          clientProfile: "cli",
          tokenType: enriched.tokenType,
          authMethod: enriched.authMethod,
          projectId: enriched.projectId ?? toRecord(existing.providerSpecificData).projectId,
          tier: enriched.tier ?? toRecord(existing.providerSpecificData).tier,
          importedAt: new Date().toISOString(),
        },
      });

      return { connection: updated || existing, created: false };
    }
  } else if (!options.overwriteExisting) {
    throw new AgyAuthFileError(
      "Could not verify the account email from the agy token (no userinfo). Pass overwriteExisting: true to import without email verification.",
      409,
      "identity_unverified"
    );
  }

  const name = options.name || resolvedEmail || "Antigravity CLI (imported)";

  const connection = await createProviderConnection({
    provider: "agy",
    authType: "oauth",
    name,
    email: resolvedEmail || undefined,
    accessToken: enriched.accessToken,
    refreshToken: enriched.refreshToken,
    expiresAt: enriched.expiresAt,
    isActive: true,
    testStatus: "active",
    providerSpecificData: {
      clientProfile: "cli",
      tokenType: enriched.tokenType,
      authMethod: enriched.authMethod,
      projectId: enriched.projectId,
      tier: enriched.tier,
      importedAt: new Date().toISOString(),
    },
  });

  return { connection, created: true };
}

import { getProviderConnections, updateProviderConnection } from "@/lib/db/providers"
import { createProviderConnection } from "@/lib/localDb";
import { ClaudeAuthFileError } from "@/lib/oauth/utils/claudeAuthFile";

type JsonRecord = Record<string, unknown>;

function toRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function toNonEmptyString(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
}

// ──── Public types ────────────────────────────────────────────────────────────

export interface ParsedClaudeAuth {
  accessToken: string;
  refreshToken: string;
  expiresAt: string | null; // ISO (converted from ms)
  scopes: string[];
  subscriptionType: string | null;
  rateLimitTier: string | null;
  email: string | null; // from bootstrap enrichment
}

export interface EnrichedClaudeAuth extends ParsedClaudeAuth {
  accountUUID: string | null;
  organizationUUID: string | null;
  organizationName: string | null;
  organizationType: string | null;
  rateLimitTier: string | null;
}

export interface CreateConnectionOptions {
  name?: string;
  email?: string;
  overwriteExisting?: boolean;
}

// ──── Parse & validate ────────────────────────────────────────────────────────

export function parseAndValidateClaudeAuth(raw: unknown): ParsedClaudeAuth {
  const doc = toRecord(raw);
  const oauthBlock = toRecord(doc.claudeAiOauth);

  const accessToken = toNonEmptyString(oauthBlock.accessToken);
  const refreshToken = toNonEmptyString(oauthBlock.refreshToken);

  if (!accessToken) {
    throw new ClaudeAuthFileError(
      "accessToken is missing or empty in claudeAiOauth",
      400,
      "missing_access_token"
    );
  }

  if (!refreshToken) {
    throw new ClaudeAuthFileError(
      "refreshToken is missing or empty in claudeAiOauth",
      400,
      "missing_refresh_token"
    );
  }

  // expiresAt in the file is ms epoch; store as ISO in DB
  let expiresAt: string | null = null;
  const rawExpiresAt = oauthBlock.expiresAt;
  if (typeof rawExpiresAt === "number" && Number.isFinite(rawExpiresAt)) {
    expiresAt = new Date(rawExpiresAt).toISOString();
  } else if (typeof rawExpiresAt === "string" && rawExpiresAt.trim()) {
    expiresAt = rawExpiresAt.trim();
  }

  const rawScopes = oauthBlock.scopes;
  const scopes: string[] = Array.isArray(rawScopes)
    ? rawScopes.filter((s): s is string => typeof s === "string")
    : [];

  return {
    accessToken,
    refreshToken,
    expiresAt,
    scopes,
    subscriptionType: toNonEmptyString(oauthBlock.subscriptionType),
    rateLimitTier: toNonEmptyString(oauthBlock.rateLimitTier),
    email: null,
  };
}

// ──── Bootstrap enrichment ────────────────────────────────────────────────────

export async function enrichWithBootstrap(
  parsed: ParsedClaudeAuth,
  // proxyConfig reserved for future authenticated-proxy support
  proxyConfig?: null
): Promise<EnrichedClaudeAuth> {
  const base: EnrichedClaudeAuth = {
    ...parsed,
    accountUUID: null,
    organizationUUID: null,
    organizationName: null,
    organizationType: null,
    rateLimitTier: parsed.rateLimitTier,
  };

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 8000);

  try {
    const res = await fetch("https://api.anthropic.com/api/claude_cli/bootstrap", {
      method: "GET",
      headers: {
        Authorization: `Bearer ${parsed.accessToken}`,
        "anthropic-version": "2023-06-01",
        "Content-Type": "application/json",
      },
      signal: controller.signal,
    });

    if (!res.ok) {
      return base;
    }

    const body = toRecord(await res.json());

    const accountUUID = toNonEmptyString(body.account_uuid);
    const organizationUUID = toNonEmptyString(body.organization_uuid);
    const organizationName = toNonEmptyString(body.organization_name);
    const organizationType = toNonEmptyString(body.organization_type);
    const rateLimitTier = toNonEmptyString(body.rate_limit_tier) || parsed.rateLimitTier;
    const bootstrapEmail = toNonEmptyString(body.account_email);

    return {
      ...base,
      accountUUID,
      organizationUUID,
      organizationName,
      organizationType,
      rateLimitTier,
      email: parsed.email || bootstrapEmail,
    };
  } catch {
    // Network error, timeout, or parse failure — best-effort; callers handle null fields
    return base;
  } finally {
    clearTimeout(timer);
  }
}

// ──── Lookup ──────────────────────────────────────────────────────────────────

export async function findExistingClaudeConnection(
  accountUUID: string
): Promise<JsonRecord | null> {
  const connections = await getProviderConnections({ provider: "claude" });
  const lower = accountUUID.toLowerCase();
  return (
    (connections.find((c) => {
      const psd = toRecord((c as JsonRecord).providerSpecificData);
      const stored = toNonEmptyString(psd.accountUUID);
      return stored !== null && stored.toLowerCase() === lower;
    }) as JsonRecord | undefined) ?? null
  );
}

// ──── Create / update connection ──────────────────────────────────────────────

export async function createConnectionFromAuthFile(
  enriched: EnrichedClaudeAuth,
  options: CreateConnectionOptions
): Promise<{ connection: JsonRecord; created: boolean }> {
  // Duplicate detection by accountUUID (skipped when bootstrap failed)
  if (enriched.accountUUID) {
    const existing = await findExistingClaudeConnection(enriched.accountUUID);

    if (existing) {
      if (!options.overwriteExisting) {
        throw new ClaudeAuthFileError(
          "A Claude connection for this account already exists. Pass overwriteExisting: true to replace it.",
          409,
          "duplicate_account"
        );
      }

      const updated = await updateProviderConnection(existing.id as string, {
        accessToken: enriched.accessToken,
        refreshToken: enriched.refreshToken,
        expiresAt: enriched.expiresAt,
        email:
          options.email || enriched.email || (existing.email as string | undefined) || undefined,
        name:
          options.name ||
          (existing.name as string | undefined) ||
          options.email ||
          enriched.email ||
          "Claude (imported)",
        testStatus: "active",
        providerSpecificData: {
          ...toRecord(existing.providerSpecificData),
          accountUUID: enriched.accountUUID,
          organizationUUID: enriched.organizationUUID,
          organizationName: enriched.organizationName,
          organizationType: enriched.organizationType,
          rateLimitTier: enriched.rateLimitTier,
          scopes: enriched.scopes,
          subscriptionType: enriched.subscriptionType,
          bootstrapEmail: enriched.email,
          importedAt: new Date().toISOString(),
        },
      });

      return { connection: updated || existing, created: false };
    }
  }

  // Identity check: when bootstrap failed and we have no email, refuse unless
  // the caller has explicitly opted into overwrite mode (they know what they're doing).
  if (!enriched.email && !enriched.accountUUID && !options.overwriteExisting) {
    throw new ClaudeAuthFileError(
      "Could not verify the account identity (bootstrap failed and no email/accountUUID available). Pass overwriteExisting: true to import anyway.",
      409,
      "identity_unverified"
    );
  }

  const email = options.email || enriched.email || undefined;
  const name = options.name || options.email || enriched.email || "Claude (imported)";

  const connection = await createProviderConnection({
    provider: "claude",
    authType: "oauth",
    name,
    email,
    accessToken: enriched.accessToken,
    refreshToken: enriched.refreshToken,
    expiresAt: enriched.expiresAt,
    isActive: true,
    testStatus: "active",
    providerSpecificData: {
      accountUUID: enriched.accountUUID,
      organizationUUID: enriched.organizationUUID,
      organizationName: enriched.organizationName,
      organizationType: enriched.organizationType,
      rateLimitTier: enriched.rateLimitTier,
      scopes: enriched.scopes,
      subscriptionType: enriched.subscriptionType,
      bootstrapEmail: enriched.email,
      importedAt: new Date().toISOString(),
    },
  });

  return { connection, created: true };
}

import { getProviderConnections, updateProviderConnection } from "@/lib/db/providers"
import { createProviderConnection } from "@/lib/localDb";
import { CodexAuthFileError } from "@/lib/oauth/utils/codexAuthFile";
import { pickCodexConnectionForUser } from "@/lib/oauth/utils/codexConnectionSelection";

type JsonRecord = Record<string, unknown>;

function toRecord(value: unknown): JsonRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

function toNonEmptyString(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
}

function decodeJwtPayload(jwt: string): JsonRecord | null {
  try {
    const parts = jwt.split(".");
    if (parts.length !== 3) return null;
    const payload = Buffer.from(parts[1], "base64url").toString("utf8");
    return toRecord(JSON.parse(payload));
  } catch {
    return null;
  }
}

function extractExpFromJwt(jwt: string): number | null {
  const payload = decodeJwtPayload(jwt);
  if (!payload) return null;
  const exp = payload.exp;
  return typeof exp === "number" && Number.isFinite(exp) ? exp : null;
}

// Prefer access_token.exp over id_token.exp — the id_token may be expired
// while the access_token (and refresh_token) are still valid. Using a stale
// id_token expiry would mark the connection as expired immediately after import
// and trigger an unnecessary refresh (which can invalidate the token family).
function extractExpiresAt(accessToken: string, idToken: string): string | null {
  const accessExp = extractExpFromJwt(accessToken);
  if (accessExp !== null) return new Date(accessExp * 1000).toISOString();
  const idExp = extractExpFromJwt(idToken);
  if (idExp !== null) return new Date(idExp * 1000).toISOString();
  return null;
}

function extractJwtEmail(idToken: string): string | null {
  const payload = decodeJwtPayload(idToken);
  if (!payload) return null;
  return toNonEmptyString(payload.email);
}

function extractCodexAccountId(
  idToken: string,
  tokensAccountId: string | undefined
): string | null {
  if (tokensAccountId && tokensAccountId.trim()) return tokensAccountId.trim();
  const payload = decodeJwtPayload(idToken);
  const authInfo = payload ? toRecord(payload["https://api.openai.com/auth"]) : {};
  return (
    toNonEmptyString(authInfo.chatgpt_account_id) || toNonEmptyString(authInfo.account_id) || null
  );
}

// Two DISTINCT users can share the SAME workspace/account id (e.g. two members of the
// same ChatGPT Team). The account id alone is NOT a unique connection key. The id_token
// auth claim carries the per-user `chatgpt_user_id`; use it (falling back to `user_id`,
// then the JWT `sub`) so imports can be deduped by workspace AND user. See #6301.
function extractCodexUserId(idToken: string): string | null {
  const payload = decodeJwtPayload(idToken);
  if (!payload) return null;
  const authInfo = toRecord(payload["https://api.openai.com/auth"]);
  return (
    toNonEmptyString(authInfo.chatgpt_user_id) ||
    toNonEmptyString(authInfo.user_id) ||
    toNonEmptyString(payload.sub) ||
    null
  );
}

// On overwrite, keep the incoming per-user id but fall back to the one already stored
// on the existing connection (legacy imports carried none) rather than dropping it (#6301).
function mergeCodexUserId(incomingUserId: string | null, existing: JsonRecord): string | null {
  return incomingUserId ?? toNonEmptyString(toRecord(existing.providerSpecificData).chatgptUserId);
}

// ──── Public types ────────────────────────────────────────────────────────────

export interface ParsedCodexAuth {
  idToken: string;
  accessToken: string;
  refreshToken: string;
  accountId: string;
  // Per-user identity within the workspace (chatgpt_user_id / user_id / JWT sub).
  // Distinct users can share the same accountId, so this disambiguates them (#6301).
  userId: string | null;
  email: string | null;
  expiresAt: string | null;
}

export interface CreateConnectionOptions {
  name?: string;
  email?: string;
  overwriteExisting?: boolean;
}

// ──── Parse & validate ────────────────────────────────────────────────────────

export function parseAndValidateCodexAuth(raw: unknown): ParsedCodexAuth {
  const doc = toRecord(raw);

  // Codex CLI no longer writes auth_mode in auth.json (only OmniRoute's own export
  // includes it). Accept both formats as long as the required tokens are present.
  if (doc.auth_mode !== undefined && doc.auth_mode !== null && doc.auth_mode !== "chatgpt") {
    throw new CodexAuthFileError(
      "Not a Codex auth.json — unexpected auth_mode value",
      400,
      "invalid_auth_file"
    );
  }

  const tokens = toRecord(doc.tokens);
  const idToken = toNonEmptyString(tokens.id_token);
  const accessToken = toNonEmptyString(tokens.access_token);
  const refreshToken = toNonEmptyString(tokens.refresh_token);

  if (!idToken) {
    throw new CodexAuthFileError(
      "id_token is missing or empty in the auth.json",
      400,
      "missing_id_token"
    );
  }

  if (!accessToken) {
    throw new CodexAuthFileError(
      "access_token is missing or empty in the auth.json",
      400,
      "missing_access_token"
    );
  }

  if (!refreshToken) {
    throw new CodexAuthFileError(
      "refresh_token is missing or empty in the auth.json",
      400,
      "missing_refresh_token"
    );
  }

  const tokensAccountId = toNonEmptyString(tokens.account_id) ?? undefined;
  const accountId = extractCodexAccountId(idToken, tokensAccountId);

  if (!accountId) {
    throw new CodexAuthFileError(
      "Unable to derive account_id from the auth.json tokens",
      400,
      "missing_account_id"
    );
  }

  return {
    idToken,
    accessToken,
    refreshToken,
    accountId,
    userId: extractCodexUserId(idToken),
    email: extractJwtEmail(idToken),
    expiresAt: extractExpiresAt(accessToken, idToken),
  };
}

// ──── Create / update connection ──────────────────────────────────────────────

export async function createConnectionFromAuthFile(
  parsed: ParsedCodexAuth,
  options: CreateConnectionOptions
): Promise<{ connection: JsonRecord; created: boolean }> {
  const existing = await findExistingCodexConnection(
    parsed.accountId,
    parsed.userId,
    options.email || parsed.email || null
  );

  if (existing) {
    if (!options.overwriteExisting) {
      throw new CodexAuthFileError(
        "A Codex connection for this account already exists. Pass overwriteExisting: true to replace it.",
        409,
        "duplicate_account"
      );
    }

    const updated = await updateProviderConnection(existing.id as string, {
      accessToken: parsed.accessToken,
      refreshToken: parsed.refreshToken,
      idToken: parsed.idToken,
      expiresAt: parsed.expiresAt,
      email: options.email || parsed.email || (existing.email as string | undefined),
      name:
        options.name ||
        (existing.name as string | undefined) ||
        options.email ||
        parsed.email ||
        "Codex (imported)",
      testStatus: "active",
      providerSpecificData: {
        ...toRecord(existing.providerSpecificData),
        workspaceId: parsed.accountId,
        chatgptUserId: mergeCodexUserId(parsed.userId, existing),
        importedAt: new Date().toISOString(),
      },
    });

    return { connection: updated || existing, created: false };
  }

  const name = options.name || options.email || parsed.email || "Codex (imported)";

  const connection = await createProviderConnection({
    provider: "codex",
    authType: "oauth",
    name,
    email: options.email || parsed.email || undefined,
    accessToken: parsed.accessToken,
    refreshToken: parsed.refreshToken,
    idToken: parsed.idToken,
    expiresAt: parsed.expiresAt,
    isActive: true,
    testStatus: "active",
    providerSpecificData: {
      workspaceId: parsed.accountId,
      chatgptUserId: parsed.userId,
      importedAt: new Date().toISOString(),
    },
  });

  // Fix C REVERTED: do NOT refresh-on-import.
  //
  // Reason: production tests showed that auth.json files exported from the
  // Codex CLI are often already partially rotated (the CLI continues to use
  // the tokens after export). Calling the OpenAI refresh endpoint with a
  // stale refresh_token returns "invalid_grant" / "refresh_token_reused" /
  // "refresh_token_invalidated" AND has been observed to invalidate the
  // entire token family upstream — causing every freshly imported account
  // to land in a permanently-broken state, with the only working connection
  // being whichever auth.json the user re-exported most recently.
  //
  // The id_token's `exp` claim is now used as the initial `expiresAt`. In
  // practice OpenAI Codex id_tokens carry a multi-day lifetime, so this
  // does NOT trigger the import-burst proactive-refresh storm that Fix C
  // originally tried to prevent. When the access_token actually expires,
  // the reactive 401 path in chatCore.ts (with the per-connection mutex)
  // handles a single, atomic rotation — that mechanism is intact via the
  // Fix A `runWithOnPersist` plumbing.

  return { connection, created: true };
}

// Dedup key is the workspace/account id AND the per-user id. Two distinct users in the
// same workspace share an accountId but have different userIds, so they must NOT collide
// (#6301). Backward-compat: connections imported before the chatgptUserId field existed
// carry no stored userId — when NONE of the workspace matches has a stored userId we
// promote the legacy row with a compatible email, or an email-less legacy row. From the
// connections already matched on workspace/account id, pick the one that belongs to the
// incoming user. A different user in the same workspace is NOT a duplicate — refuse to
// dedup when some stored connection actually records a different userId.
async function findExistingCodexConnection(
  accountId: string,
  userId: string | null,
  email: string | null
): Promise<JsonRecord | null> {
  const connections = await getProviderConnections({
    provider: "codex",
    authType: "oauth",
  });
  const workspaceMatches = (connections as JsonRecord[]).filter(
    (c) => toNonEmptyString(toRecord(c.providerSpecificData).workspaceId) === accountId
  );
  if (workspaceMatches.length === 0) return null;
  // No incoming userId → legacy accountId-only dedup with the first workspace match.
  if (!userId) return workspaceMatches[0];
  return pickCodexConnectionForUser(workspaceMatches, userId, email);
}

