function asExplainLog(value: unknown): ExplainLog | null {
  if (!value || typeof value !== "object") return null;
  const record = value as JsonRecord;
  return typeof record.id === "string" ? (record as ExplainLog) : null;
}

function toNumber(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function toStringOrNull(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : null;
}

function isSuccessStatus(status: number): boolean {
  return status >= 200 && status < 400;
}

function getErrorText(error: unknown): string | null {
  if (typeof error === "string" && error.trim().length > 0) return error.trim();
  if (error && typeof error === "object") {
    try {
      return JSON.stringify(error).slice(0, 240);
    } catch {
      return null;
    }
  }
  return null;
}

function calculateScore(log: ExplainLog, targetStats: TargetStats): number {
  const statusScore = isSuccessStatus(toNumber(log.status)) ? 0.4 : 0;
  const latency = toNumber(log.duration);
  const latencyScore = latency > 0 ? Math.max(0, 0.25 - Math.min(latency, 15000) / 60000) : 0.1;
  const statsScore = targetStats.sampleSize > 0 ? (targetStats.successRate / 100) * 0.25 : 0.1;
  const cacheScore = log.cacheSource === "semantic" ? 0.1 : 0.05;
  return Number(Math.min(1, statusScore + latencyScore + statsScore + cacheScore).toFixed(3));
}

function summarizeTokens(log: ExplainLog): string {
  const input = toNumber(log.tokens?.in);
  const output = toNumber(log.tokens?.out);
  const compressed = toNumber(log.tokens?.compressed);
  const parts = [`${input.toLocaleString()} in`, `${output.toLocaleString()} out`];
  if (compressed > 0) parts.push(`${compressed.toLocaleString()} compressed`);
  return parts.join(" · ");
}

function buildRelatedTarget(log: ExplainLog, selectedId: string): ExplainTarget {
  const status = toNumber(log.status);
  return {
    id: log.id,
    timestamp: log.timestamp ?? null,
    status,
    provider: log.provider ?? null,
    model: log.model ?? null,
    comboStepId: log.comboStepId ?? null,
    comboExecutionKey: log.comboExecutionKey ?? null,
    durationMs: toNumber(log.duration),
    outcome: log.id === selectedId ? "selected" : "related",
    reason:
      log.id === selectedId
        ? "Selected target for this persisted request log."
        : isSuccessStatus(status)
          ? "Nearby successful target for the same combo."
          : "Nearby failed target for the same combo; likely fallback evidence if timestamps match.",
  };
}

function buildTargetStats(selected: ExplainLog, relatedLogs: ExplainLog[]): TargetStats {
  const executionKey =
    toStringOrNull(selected.comboExecutionKey) || toStringOrNull(selected.comboStepId);
  const comparable = relatedLogs.filter((entry) => {
    const entryKey = toStringOrNull(entry.comboExecutionKey) || toStringOrNull(entry.comboStepId);
    if (executionKey) return entryKey === executionKey;
    return entry.provider === selected.provider && entry.model === selected.model;
  });

  const sample = comparable.length > 0 ? comparable : [selected];
  const successCount = sample.filter((entry) => isSuccessStatus(toNumber(entry.status))).length;
  const totalLatency = sample.reduce((sum, entry) => sum + toNumber(entry.duration), 0);
  const latest = [...sample].sort((left, right) => {
    return String(right.timestamp || "").localeCompare(String(left.timestamp || ""));
  })[0];

  return {
    sampleSize: sample.length,
    successRate: sample.length > 0 ? Math.round((successCount / sample.length) * 100) : 0,
    avgLatencyMs: sample.length > 0 ? Math.round(totalLatency / sample.length) : 0,
    lastStatus: latest ? (isSuccessStatus(toNumber(latest.status)) ? "ok" : "error") : null,
    lastUsedAt: latest?.timestamp ?? null,
  };
}

function buildFactors(log: ExplainLog, targetStats: TargetStats): ExplanationFactor[] {
  const status = toNumber(log.status);
  const factors: ExplanationFactor[] = [];

  factors.push({
    name: log.comboName ? "Combo routing" : "Direct routing",
    value: log.comboName || "Direct provider request",
    status: log.comboName ? "positive" : "neutral",
    weight: 0.25,
    contribution: log.comboName ? 0.25 : 0.15,
    details: log.comboName
      ? `Request matched combo ${log.comboName}${log.comboStepId ? ` at step ${log.comboStepId}` : ""}.`
      : "No combo metadata was persisted, so OmniRoute treated this as direct routing.",
  });

  factors.push({
    name: "Provider target",
    value: [log.provider, log.model].filter(Boolean).join(" / ") || "unknown",
    status: log.provider && log.model ? "positive" : "warning",
    weight: 0.2,
    contribution: log.provider && log.model ? 0.2 : 0.08,
    details: `Selected provider ${log.provider || "unknown"} with resolved model ${log.model || "unknown"}.`,
  });

  factors.push({
    name: "Runtime health",
    value: targetStats.sampleSize > 0 ? `${targetStats.successRate}% recent success` : "No history",
    status:
      targetStats.sampleSize === 0
        ? "neutral"
        : targetStats.successRate >= 90
          ? "positive"
          : targetStats.successRate >= 60
            ? "warning"
            : "negative",
    weight: 0.2,
    contribution: Number(((targetStats.successRate / 100) * 0.2).toFixed(3)),
    details: `${targetStats.sampleSize} comparable recent log entries, average latency ${targetStats.avgLatencyMs}ms.`,
  });

  factors.push({
    name: "Request outcome",
    value: status > 0 ? `HTTP ${status}` : "Unknown status",
    status: isSuccessStatus(status) ? "positive" : "negative",
    weight: 0.2,
    contribution: isSuccessStatus(status) ? 0.2 : 0,
    details: isSuccessStatus(status)
      ? "The selected target completed successfully."
      : getErrorText(log.error) ||
        "The selected target failed or did not return a successful status.",
  });

  factors.push({
    name: "Latency",
    value: `${toNumber(log.duration).toLocaleString()}ms`,
    status:
      toNumber(log.duration) <= 5000
        ? "positive"
        : toNumber(log.duration) <= 15000
          ? "warning"
          : "negative",
    weight: 0.1,
    contribution:
      toNumber(log.duration) <= 5000 ? 0.1 : toNumber(log.duration) <= 15000 ? 0.05 : 0.02,
    details: "Measured end-to-end duration for the persisted call log.",
  });

  factors.push({
    name: "Cache and tokens",
    value: `${log.cacheSource || "upstream"} · ${summarizeTokens(log)}`,
    status:
      log.cacheSource === "semantic" || toNumber(log.tokens?.compressed) > 0
        ? "positive"
        : "neutral",
    weight: 0.05,
    contribution:
      log.cacheSource === "semantic" || toNumber(log.tokens?.compressed) > 0 ? 0.05 : 0.025,
    details: "Shows whether OmniRoute cache or compression affected cost/latency for this route.",
  });

  return factors;
}

function buildEvidence(
  log: ExplainLog,
  targetStats: TargetStats
): RouteExplainabilityResponse["evidence"] {
  return [
    { label: "Requested model", value: log.requestedModel || "n/a", tone: "neutral" },
    {
      label: "Resolved model",
      value: log.model || "n/a",
      tone: log.model ? "positive" : "warning",
    },
    {
      label: "Provider",
      value: log.provider || "n/a",
      tone: log.provider ? "positive" : "warning",
    },
    {
      label: "Combo",
      value: log.comboName || "Direct",
      tone: log.comboName ? "positive" : "neutral",
    },
    {
      label: "Recent target success",
      value: `${targetStats.successRate}% over ${targetStats.sampleSize} samples`,
      tone:
        targetStats.successRate >= 90
          ? "positive"
          : targetStats.successRate >= 60
            ? "warning"
            : "negative",
    },
    {
      label: "Formats",
      value: `${log.sourceFormat || "unknown"} → ${log.targetFormat || "unknown"}`,
      tone: "neutral",
    },
  ];
}

function buildRecommendations(log: ExplainLog, targetStats: TargetStats): string[] {
  const recommendations: string[] = [];
  const status = toNumber(log.status);

  if (!isSuccessStatus(status)) {
    recommendations.push(
      "Inspect the provider error and consider moving this target later in the combo until it recovers."
    );
  }
  if (targetStats.sampleSize >= 3 && targetStats.successRate < 80) {
    recommendations.push(
      "Recent success rate is low; review account cooldowns, model lockouts, or provider circuit breaker state."
    );
  }
  if (toNumber(log.duration) > 15000) {
    recommendations.push(
      "Latency is high; compare this target with a faster provider in Combo Health before increasing traffic."
    );
  }
  if (!log.comboName) {
    recommendations.push(
      "Use a combo when you want fallback visibility and multi-provider route explanations."
    );
  }
  if (recommendations.length === 0) {
    recommendations.push(
      "Route looks healthy. Keep monitoring target success rate and quota pressure in Combo Health."
    );
  }

  return recommendations;
}

function buildLimitations(log: ExplainLog, relatedTargets: ExplainTarget[]): string[] {
  const limitations: string[] = [];
  if (!log.hasPipelineDetails) {
    limitations.push("Detailed request pipeline payloads were not persisted for this log entry.");
  }
  if (!log.comboName) {
    limitations.push("Direct requests do not include combo fallback ordering metadata.");
  }
  if (relatedTargets.length <= 1) {
    limitations.push(
      "No shared request correlation id is available yet; fallback evidence is inferred from the persisted call log metadata."
    );
  }
  return limitations;
}

function buildDecisionReplayRuntime(log: ExplainLog): DecisionReplay["runtime"] {
  return {
    source: "call_logs",
    exact: true,
    selectedCallLogId: log.id,
    comboName: log.comboName ?? null,
    comboStepId: log.comboStepId ?? null,
    comboExecutionKey: log.comboExecutionKey ?? null,
    provider: log.provider ?? null,
    model: log.model ?? null,
    connectionId: log.connectionId ?? null,
    status: toNumber(log.status),
    timestamp: log.timestamp ?? null,
    durationMs: toNumber(log.duration),
  };
}

function comboIdFromRecord(combo: unknown): string | null {
  if (!combo || typeof combo !== "object") return null;
  const record = combo as JsonRecord;
  return toStringOrNull(record.id);
}

function targetMatchesRuntime(target: ComboScoringInspectorTarget, log: ExplainLog): boolean {
  const runtimeExecutionKey = toStringOrNull(log.comboExecutionKey);
  if (runtimeExecutionKey && target.executionKey === runtimeExecutionKey) return true;

  const runtimeStepId = toStringOrNull(log.comboStepId);
  if (runtimeStepId && target.stepId === runtimeStepId) return true;

  if (target.provider !== log.provider || target.model !== log.model) return false;
  if (target.connectionId && log.connectionId && target.connectionId !== log.connectionId) {
    return false;
  }
  return true;
}

function buildReplayCandidates(
  targets: ComboScoringInspectorTarget[],
  runtimeTarget: ComboScoringInspectorTarget | undefined
): DecisionReplayCandidate[] {
  const selectedExecutionKey = targets[0]?.executionKey ?? null;
  const limited = targets.slice(0, 10);
  if (
    runtimeTarget &&
    !limited.some((target) => target.executionKey === runtimeTarget.executionKey)
  ) {
    limited.push(runtimeTarget);
  }

  return limited.map((target) => ({
    executionKey: target.executionKey,
    stepId: target.stepId,
    provider: target.provider,
    model: target.model,
    connectionId: target.connectionId,
    label: target.label,
    rank: target.rank,
    score: target.score,
    isRuntimeSelected: runtimeTarget?.executionKey === target.executionKey,
    wouldSelectNow: selectedExecutionKey === target.executionKey,
    factors: target.factors,
    signals: target.signals,
  }));
}

function buildReplayWarnings(log: ExplainLog, comboWarnings: string[]): string[] {
  const warnings = [
    "Runtime fields are exact only for metadata persisted in the selected call log row.",
    "Read-only recompute is not a historical routing snapshot; it uses current combo, health, quota, and scoring state.",
  ];

  if (log.comboName) {
    warnings.push(
      "No shared request correlation id is available yet; fallback ordering is inferred from persisted combo log metadata."
    );
  }

  return Array.from(new Set([...warnings, ...comboWarnings]));
}

async function buildDecisionReplay(log: ExplainLog): Promise<DecisionReplay> {
  const runtime = buildDecisionReplayRuntime(log);
  const warnings = buildReplayWarnings(log, []);

  if (!log.comboName) {
    return {
      runtime,
      recompute: null,
      warnings: [...warnings, "Direct routing has no combo candidate ranking to recompute."],
    };
  }

  const combo = await getComboByName(log.comboName);
  const comboId = comboIdFromRecord(combo);
  if (!comboId) {
    return {
      runtime,
      recompute: null,
      warnings: [
        ...warnings,
        "Combo definition could not be found; runtime target is shown without recomputed candidates.",
      ],
    };
  }

  const inspector = await buildComboScoringInspectorResponse({
    range: "24h",
    horizon: "7d",
    comboId,
    taskType: "default",
  });
  const inspectorCombo = inspector.combos[0] ?? null;
  if (!inspectorCombo) {
    return {
      runtime,
      recompute: null,
      warnings: [
        ...warnings,
        "Scoring inspector returned no combo data; runtime target is shown without recomputed candidates.",
      ],
    };
  }

  const runtimeTarget = inspectorCombo.targets.find((target) => targetMatchesRuntime(target, log));
  const topTarget = inspectorCombo.targets[0] ?? null;
  const alignment: DecisionReplayAlignment = runtimeTarget
    ? topTarget?.executionKey === runtimeTarget.executionKey
      ? "matches_recomputed_top_target"
      : "differs_from_recomputed_top_target"
    : "runtime_target_missing_from_recompute";
  const recomputeWarnings = buildReplayWarnings(log, inspectorCombo.warnings);
  if (alignment === "differs_from_recomputed_top_target") {
    recomputeWarnings.push(
      "Persisted runtime target differs from the target the inspector would rank first now."
    );
  } else if (alignment === "runtime_target_missing_from_recompute") {
    recomputeWarnings.push(
      "Persisted runtime target could not be matched to current combo targets; combo configuration may have changed."
    );
  }

  return {
    runtime,
    recompute: {
      source: "comboScoringInspector",
      method: inspector.method,
      exactRuntimeReplay: false,
      asOf: inspector.asOf,
      timeRange: "24h",
      horizon: "7d",
      comboId: inspectorCombo.comboId,
      comboName: inspectorCombo.comboName,
      strategy: inspectorCombo.strategy,
      taskType: "default",
      recomputedSelectedExecutionKey: inspectorCombo.selectedExecutionKey,
      runtimeSelectedRank: runtimeTarget?.rank ?? null,
      runtimeSelectedScore: runtimeTarget?.score ?? null,
      alignment,
      candidates: buildReplayCandidates(inspectorCombo.targets, runtimeTarget),
      warnings: recomputeWarnings,
    },
    warnings: recomputeWarnings,
  };
}

async function buildSelectedResilience(log: ExplainLog): Promise<ResilienceExplanation | null> {
  if (!log.provider || !log.model) return null;
  return inspectTargetResilience({
    provider: log.provider,
    model: log.model,
    connectionId: log.connectionId ?? null,
  });
}

async function getRelatedLogs(log: ExplainLog): Promise<ExplainLog[]> {
  const selectedTime = log.timestamp ? new Date(log.timestamp).getTime() : 0;
  const windowMs = 15 * 60 * 1000;
  const filter: JsonRecord = { limit: 200 };
  if (Number.isFinite(selectedTime) && selectedTime > 0) {
    filter.since = new Date(selectedTime - windowMs).toISOString();
    filter.until = new Date(selectedTime + windowMs).toISOString();
  }
  if (log.comboName) {
    filter.combo = "1";
    filter.search = log.comboName;
  } else if (log.provider) {
    filter.provider = log.provider;
  }

  const rawLogs = await getCallLogs(filter);
  const logs = rawLogs.map(asExplainLog).filter((entry): entry is ExplainLog => entry !== null);

  return logs.filter((entry) => {
    if (entry.id === log.id) return true;
    if (log.comboName && entry.comboName !== log.comboName) return false;
    if (!log.comboName && entry.provider !== log.provider) return false;
    if (!selectedTime || !entry.timestamp) return true;
    const entryTime = new Date(entry.timestamp).getTime();
    return Number.isFinite(entryTime) && Math.abs(entryTime - selectedTime) <= windowMs;
  });
}

export async function explainRouteByRequestId(
  requestId: string
): Promise<RouteExplainabilityResponse | null> {
  const log = asExplainLog(await getCallLogById(requestId));
  if (!log) return null;

  const relatedLogs = await getRelatedLogs(log);
  const targetStats = buildTargetStats(log, relatedLogs);
  const relatedTargets = relatedLogs
    .map((entry) => buildRelatedTarget(entry, log.id))
    .sort((left, right) =>
      String(left.timestamp || "").localeCompare(String(right.timestamp || ""))
    );
  const fallbacksTriggered = relatedTargets.filter(
    (target) => target.outcome !== "selected" && target.status >= 400
  );
  const factors = buildFactors(log, targetStats);
  const score = calculateScore(log, targetStats);
  const [decisionReplay, resilience] = await Promise.all([
    buildDecisionReplay(log),
    buildSelectedResilience(log),
  ]);
  const routeType = log.comboName ? "combo" : "direct";
  const confidence = log.hasPipelineDetails
    ? "high"
    : log.comboName || relatedTargets.length > 1
      ? "medium"
      : "low";
  const summary = log.comboName
    ? `Request ${log.id} was routed through combo ${log.comboName} to ${log.provider || "unknown"}/${log.model || "unknown"}.`
    : `Request ${log.id} was routed directly to ${log.provider || "unknown"}/${log.model || "unknown"}.`;

  return {
    requestId: log.id,
    generatedAt: new Date().toISOString(),
    routeType,
    confidence,
    summary,
    comboUsed: log.comboName ?? null,
    providerSelected: log.provider ?? null,
    modelUsed: log.model ?? null,
    score,
    costActual: 0,
    latencyActual: toNumber(log.duration),
    decision: {
      comboUsed: log.comboName ?? null,
      providerSelected: log.provider ?? null,
      modelUsed: log.model ?? null,
      status: toNumber(log.status),
      score,
      factors,
      fallbacksTriggered,
      costActual: 0,
      latencyActual: toNumber(log.duration),
    },
    request: {
      id: log.id,
      timestamp: log.timestamp ?? null,
      method: log.method ?? null,
      path: log.path ?? null,
      requestedModel: log.requestedModel ?? null,
      requestType: log.requestType ?? null,
      sourceFormat: log.sourceFormat ?? null,
      targetFormat: log.targetFormat ?? null,
      cacheSource: log.cacheSource ?? null,
      apiKeyName: log.apiKeyName ?? null,
    },
    selectedTarget: {
      provider: log.provider ?? null,
      model: log.model ?? null,
      account: log.account ?? null,
      connectionId: log.connectionId ?? null,
      comboStepId: log.comboStepId ?? null,
      comboExecutionKey: log.comboExecutionKey ?? null,
      durationMs: toNumber(log.duration),
      status: toNumber(log.status),
      tokensIn: toNumber(log.tokens?.in),
      tokensOut: toNumber(log.tokens?.out),
    },
    targetStats,
    fallbacksTriggered,
    relatedTargets,
    evidence: buildEvidence(log, targetStats),
    recommendations: buildRecommendations(log, targetStats),
    limitations: buildLimitations(log, relatedTargets),
    decisionReplay,
    resilience,
    reasoningRouting:
      log.pipelinePayloads?.routeDecision && typeof log.pipelinePayloads.routeDecision === "object"
        ? log.pipelinePayloads.routeDecision
        : null,
  };
}

import { jwtVerify } from "jose";
import { getSettings } from "@/lib/localDb";
import { validateApiKey } from "@/lib/db/apiKeys";

export const DEFAULT_WS_PATH = "/v1/ws";
const WS_QUERY_TOKEN_KEYS = ["api_key", "token", "access_token"];

export type WsAuthType = "none" | "api_key" | "session";

export interface WsRuntimeConfig {
  wsAuth: boolean;
  wsPath: string;
}

export interface WsHandshakeAuthResult extends WsRuntimeConfig {
  authorized: boolean;
  authenticated: boolean;
  authType: WsAuthType;
  hasCredential: boolean;
}

function getCookieValue(cookieHeader: string | null, cookieName: string): string | null {
  if (typeof cookieHeader !== "string" || cookieHeader.trim().length === 0) {
    return null;
  }

  for (const part of cookieHeader.split(";")) {
    const [rawName, ...rest] = part.trim().split("=");
    if (rawName === cookieName) {
      const value = rest.join("=").trim();
      return value || null;
    }
  }

  return null;
}

async function hasValidSessionCookie(request: Request): Promise<boolean> {
  const secretValue = process.env.JWT_SECRET;
  if (typeof secretValue !== "string" || secretValue.trim().length === 0) {
    return false;
  }

  const token = getCookieValue(request.headers.get("cookie"), "auth_token");
  if (!token) return false;

  try {
    await jwtVerify(token, new TextEncoder().encode(secretValue));
    return true;
  } catch {
    return false;
  }
}

export function extractWsTokenFromUrl(input: string | URL): string | null {
  const url = input instanceof URL ? input : new URL(input);
  for (const key of WS_QUERY_TOKEN_KEYS) {
    const value = url.searchParams.get(key);
    if (typeof value === "string" && value.trim().length > 0) {
      return value.trim();
    }
  }
  return null;
}

export function extractWsTokenFromRequest(request: Request): string | null {
  const authHeader = request.headers.get("authorization") || request.headers.get("Authorization");
  if (typeof authHeader === "string" && authHeader.trim().toLowerCase().startsWith("bearer ")) {
    const token = authHeader.slice(7).trim();
    if (token) return token;
  }

  return extractWsTokenFromUrl(request.url);
}

export async function getWsRuntimeConfig(): Promise<WsRuntimeConfig> {
  const settings = await getSettings().catch(() => ({}));
  return {
    wsAuth: settings.wsAuth === true,
    wsPath: DEFAULT_WS_PATH,
  };
}

export async function authorizeWebSocketHandshake(
  request: Request
): Promise<WsHandshakeAuthResult> {
  const config = await getWsRuntimeConfig();
  const token = extractWsTokenFromRequest(request);
  const hasCredential = typeof token === "string" && token.length > 0;
  const validApiKey = hasCredential ? await validateApiKey(token) : false;

  if (!config.wsAuth) {
    return {
      ...config,
      authorized: true,
      authenticated: validApiKey,
      authType: validApiKey ? "api_key" : "none",
      hasCredential,
    };
  }

  if (validApiKey) {
    return {
      ...config,
      authorized: true,
      authenticated: true,
      authType: "api_key",
      hasCredential: true,
    };
  }

  if (await hasValidSessionCookie(request)) {
    return {
      ...config,
      authorized: true,
      authenticated: true,
      authType: "session",
      hasCredential,
    };
  }

  return {
    ...config,
    authorized: false,
    authenticated: false,
    authType: "none",
    hasCredential,
  };
}

/**
 * Zed IDE OAuth Token Extractor
 *
 * Extracts OAuth credentials from OS keychain where Zed IDE stores them.
 * Supports macOS (Keychain), Windows (Credential Manager), and Linux (libsecret).
 *
 * `keytar` is a native module (e.g. libsecret on Linux). Load it only via dynamic import
 * so `next build` / CI without those libs does not fail when this module is analyzed.
 *
 * @see https://zed.dev/docs/ai/llm-providers - Official Zed documentation confirming keychain storage
 */

import fs from "fs";
import os from "os";
import path from "path";
import { isRunningInDocker } from "./dockerDetect";

/** Minimal keytar surface (CJS/native; typings may not expose `default`). */
type KeytarModule = {
  findCredentials: (service: string) => Promise<Array<{ account: string; password: string }>>;
  getPassword: (service: string, account: string) => Promise<string | null>;
};

async function loadKeytar(): Promise<KeytarModule | null> {
  try {
    const mod = (await import("keytar")) as { default?: KeytarModule } & KeytarModule;
    return mod.default ?? mod;
  } catch {
    return null;
  }
}

export interface ZedCredential {
  provider: string;
  service: string;
  account: string;
  token: string;
}

/**
 * Common service name patterns used by Zed IDE for storing OAuth tokens
 */
const ZED_SERVICE_PATTERNS = [
  // OpenAI
  "zed-openai",
  "ai.zed.openai",
  "zed.openai",
  "Zed-OpenAI",

  // Anthropic
  "zed-anthropic",
  "ai.zed.anthropic",
  "zed.anthropic",
  "Zed-Anthropic",

  // Google AI
  "zed-google",
  "ai.zed.google",
  "zed.google",
  "Zed-Google",

  // Mistral
  "zed-mistral",
  "ai.zed.mistral",
  "zed.mistral",
  "Zed-Mistral",

  // xAI
  "zed-xai",
  "ai.zed.xai",
  "zed.xai",
  "Zed-xAI",

  // OpenRouter
  "zed-openrouter",
  "ai.zed.openrouter",
  "zed.openrouter",
  "Zed-OpenRouter",

  // DeepSeek
  "zed-deepseek",
  "ai.zed.deepseek",
  "zed.deepseek",
  "Zed-DeepSeek",
];

/**
 * Maps Zed service names to OmniRoute provider IDs
 */
function extractProviderFromService(service: string): string {
  const lower = service.toLowerCase();
  if (lower.includes("openai")) return "openai";
  if (lower.includes("anthropic")) return "anthropic";
  if (lower.includes("google")) return "google";
  if (lower.includes("mistral")) return "mistral";
  if (lower.includes("xai")) return "xai";
  if (lower.includes("openrouter")) return "openrouter";
  if (lower.includes("deepseek")) return "deepseek";
  return "unknown";
}

/**
 * Discovers all Zed OAuth credentials stored in the system keychain.
 *
 * SECURITY-AUDITOR-NOTE: This function appears in Socket.dev finding for
 * `app/.next/server/app/api/providers/zed/import/route.js`. Behaviour:
 *   - Called from `POST /api/providers/zed/discover` and `POST /api/providers/zed/import`,
 *     which are gated by `requireManagementAuth`.
 *   - From v3.8.6 onward, `/import` requires `confirmedAccounts` (per-account
 *     user consent) before persisting any credential. See the matching note in
 *     `src/app/api/providers/zed/import/route.ts`.
 *   - Reads only Zed editor patterns (`zed-openai`, `ai.zed.anthropic`, …).
 *     The raw token never leaves the host — the `/discover` response carries
 *     only a 16-char fingerprint.
 *   - See docs/security/SOCKET_DEV_FINDINGS.md §2 for the full attestation.
 *
 * @returns Array of discovered credentials with provider, service, and token
 */
export async function discoverZedCredentials(): Promise<ZedCredential[]> {
  const keytar = await loadKeytar();
  if (!keytar) {
    console.debug("[Zed keychain] keytar not available — skipping keychain read");
    return [];
  }

  const credentials: ZedCredential[] = [];

  for (const pattern of ZED_SERVICE_PATTERNS) {
    try {
      // Try to find credentials for this service
      const creds = await keytar.findCredentials(pattern);

      for (const cred of creds) {
        // FIX #1: Add null check for cred.password
        if (!cred.password) {
          console.debug(`Skipping credential with missing password: ${pattern}/${cred.account}`);
          continue;
        }

        credentials.push({
          provider: extractProviderFromService(pattern),
          service: pattern,
          account: cred.account,
          token: cred.password,
        });
      }
    } catch (error: any) {
      console.debug("No credentials found for %s:", pattern, error?.message || error);
      // Continue to next pattern
    }
  }

  return credentials;
}

/**
 * Gets a specific Zed credential for a provider
 *
 * FIX #2: Instead of hardcoded account names, first try findCredentials
 * which will return all actual credentials for the service, then fallback
 * to common patterns only if needed.
 *
 * @param provider - Provider name (openai, anthropic, google, etc.)
 * @returns The credential if found, null otherwise
 */
export async function getZedCredential(provider: string): Promise<ZedCredential | null> {
  const keytar = await loadKeytar();
  if (!keytar) return null;

  const patterns = ZED_SERVICE_PATTERNS.filter((p) =>
    p.toLowerCase().includes(provider.toLowerCase())
  );

  for (const pattern of patterns) {
    try {
      // First, try findCredentials to get all actual credentials
      const creds = await keytar.findCredentials(pattern);
      if (creds.length > 0 && creds[0].password) {
        return {
          provider,
          service: pattern,
          account: creds[0].account,
          token: creds[0].password,
        };
      }

      // Fallback: Try common account name patterns
      const accountNames = ["api-key", "token", "oauth", provider];

      for (const account of accountNames) {
        const token = await keytar.getPassword(pattern, account);
        if (token) {
          return {
            provider,
            service: pattern,
            account,
            token,
          };
        }
      }
    } catch (error: any) {
      console.debug("Failed to get credential for %s:", pattern, error?.message || error);
    }
  }

  return null;
}

/**
 * Checks if Zed IDE appears to be installed and configured
 *
 * FIX #3: Convert to ES imports instead of CommonJS require()
 *
 * @returns true if Zed config directory exists
 */
export async function isZedInstalled(): Promise<boolean> {
  const homeDir = os.homedir();
  const zedConfigPaths = [
    path.join(homeDir, ".config", "zed"), // Linux
    path.join(homeDir, "Library", "Application Support", "Zed"), // macOS
    path.join(homeDir, "AppData", "Roaming", "Zed"), // Windows
  ];

  for (const configPath of zedConfigPaths) {
    if (fs.existsSync(/* turbopackIgnore: true */ configPath)) {
      return true;
    }
  }

  return false;
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { useTranslations } from "next-intl";
import {
  SIDEBAR_SECTIONS,
  HIDDEN_SIDEBAR_ITEMS_SETTING_KEY,
  normalizeHiddenSidebarItems,
  type SidebarItemDefinition,
  type SidebarSectionChild,
} from "@/shared/constants/sidebarVisibility";

function isSidebarGroup(
  child: SidebarSectionChild
): child is Extract<SidebarSectionChild, { type: "group" }> {
  return "type" in child && child.type === "group";
}

interface CommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function CommandPalette({ isOpen, onClose }: CommandPaletteProps) {
  if (!isOpen) return null;
  return <CommandPaletteDialog onClose={onClose} />;
}

interface PaletteItem {
  id: string;
  href: string;
  icon: string;
  label: string;
  subtitle?: string;
  external: boolean;
  sectionId: string;
  sectionLabel: string;
  subgroupId?: string;
  subgroupLabel?: string;
}

interface PaletteSubgroup {
  subgroupId: string | null;
  subgroupLabel: string | null;
  items: { item: PaletteItem; flatIndex: number }[];
}

interface PaletteGroup {
  sectionId: string;
  sectionLabel: string;
  subgroups: PaletteSubgroup[];
}

function CommandPaletteDialog({ onClose }: { onClose: () => void }) {
  const router = useRouter();
  const t = useTranslations("sidebar");
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const [query, setQuery] = useState("");
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [hiddenItems, setHiddenItems] = useState<Set<string>>(new Set());

  useEffect(() => {
    const ctrl = new AbortController();
    fetch("/api/settings", { signal: ctrl.signal })
      .then((res) => res.json())
      .then((data) => {
        setHiddenItems(
          new Set(normalizeHiddenSidebarItems(data?.[HIDDEN_SIDEBAR_ITEMS_SETTING_KEY]))
        );
      })
      .catch(() => {
        // ignore aborts and fetch failures; palette still works with empty hidden set
      });
    return () => ctrl.abort();
  }, []);

  useEffect(() => {
    const id = setTimeout(() => inputRef.current?.focus(), 30);
    return () => clearTimeout(id);
  }, []);

  const safeTranslate = useCallback(
    (key: string, fallback: string) => {
      try {
        return t(key);
      } catch {
        return fallback;
      }
    },
    [t]
  );

  const allItems = useMemo<PaletteItem[]>(
    () =>
      SIDEBAR_SECTIONS.flatMap((section) => {
        const sectionLabel = safeTranslate(section.titleKey, section.titleFallback);
        return section.children.flatMap<PaletteItem>((child) => {
          if (isSidebarGroup(child)) {
            const subgroupLabel = safeTranslate(child.titleKey, child.titleFallback);
            return child.items
              .filter((item) => !hiddenItems.has(item.id))
              .map<PaletteItem>((item) => ({
                id: item.id,
                href: item.href,
                icon: item.icon,
                label: safeTranslate(item.i18nKey, item.id),
                subtitle: item.subtitleKey ? safeTranslate(item.subtitleKey, "") : undefined,
                external: item.external ?? false,
                sectionId: section.id,
                sectionLabel,
                subgroupId: child.id,
                subgroupLabel,
              }));
          }
          const item = child as SidebarItemDefinition;
          if (hiddenItems.has(item.id)) return [];
          return [
            {
              id: item.id,
              href: item.href,
              icon: item.icon,
              label: safeTranslate(item.i18nKey, item.id),
              subtitle: item.subtitleKey ? safeTranslate(item.subtitleKey, "") : undefined,
              external: item.external ?? false,
              sectionId: section.id,
              sectionLabel,
            },
          ];
        });
      }),
    [hiddenItems, safeTranslate]
  );

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return allItems;
    return allItems.filter(
      (item) =>
        item.label.toLowerCase().includes(q) ||
        item.subtitle?.toLowerCase().includes(q) ||
        item.sectionLabel.toLowerCase().includes(q) ||
        item.subgroupLabel?.toLowerCase().includes(q)
    );
  }, [allItems, query]);

  const grouped = useMemo<PaletteGroup[]>(() => {
    const groups: PaletteGroup[] = [];
    const sectionById = new Map<string, PaletteGroup>();
    filtered.forEach((item, flatIndex) => {
      // Look up the section/subgroup by id across the whole list, not just the
      // previous item — a section's children can interleave root items and
      // groups (e.g. "omni-proxy" has a trailing root item after its groups),
      // which would otherwise produce two separate "_root" subgroups sharing
      // the same React key.
      let section = sectionById.get(item.sectionId);
      if (!section) {
        section = {
          sectionId: item.sectionId,
          sectionLabel: item.sectionLabel,
          subgroups: [],
        };
        sectionById.set(item.sectionId, section);
        groups.push(section);
      }
      const itemSubgroupId = item.subgroupId ?? null;
      let subgroup = section.subgroups.find((sg) => sg.subgroupId === itemSubgroupId);
      if (!subgroup) {
        subgroup = {
          subgroupId: itemSubgroupId,
          subgroupLabel: item.subgroupLabel ?? null,
          items: [],
        };
        section.subgroups.push(subgroup);
      }
      subgroup.items.push({ item, flatIndex });
    });
    return groups;
  }, [filtered]);

  const handleNavigate = useCallback(
    (href: string, external: boolean) => {
      onClose();
      if (external) {
        window.open(href, "_blank", "noopener,noreferrer");
      } else {
        router.push(href);
      }
    },
    [onClose, router]
  );

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        onClose();
        return;
      }
      if (e.key === "ArrowDown") {
        e.preventDefault();
        setSelectedIndex((prev) => (prev + 1) % Math.max(1, filtered.length));
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setSelectedIndex(
          (prev) => (prev - 1 + Math.max(1, filtered.length)) % Math.max(1, filtered.length)
        );
      } else if (e.key === "Enter") {
        e.preventDefault();
        const item = filtered[selectedIndex];
        if (item) {
          handleNavigate(item.href, item.external);
        }
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [filtered, selectedIndex, onClose, handleNavigate]);

  useEffect(() => {
    const list = listRef.current;
    if (!list) return;
    const el = list.querySelector<HTMLElement>(`[data-flat-index="${selectedIndex}"]`);
    el?.scrollIntoView({ block: "nearest" });
  }, [selectedIndex]);

  return (
    <div className="fixed inset-0 z-[60] flex items-start justify-center pt-[10vh] px-4">
      <div
        className="absolute inset-0 bg-black/40 backdrop-blur-sm"
        onClick={onClose}
        aria-hidden="true"
      />
      <div
        className="relative w-full max-w-3xl bg-surface border border-black/10 dark:border-white/10 rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200"
        role="dialog"
        aria-modal="true"
        aria-label={t("commandPalette.title")}
      >
        <div className="flex items-center gap-3 px-6 py-4 border-b border-black/5 dark:border-white/5">
          <span className="material-symbols-outlined text-[20px] text-text-muted shrink-0">
            search
          </span>
          <input
            ref={inputRef}
            type="text"
            className="flex-1 bg-transparent text-text placeholder:text-text-muted outline-none text-base"
            placeholder={t("commandPalette.searchPlaceholder")}
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setSelectedIndex(0);
            }}
            autoComplete="off"
            spellCheck={false}
          />
          {query && (
            <button
              className="text-text-muted hover:text-text transition-colors"
              onClick={() => {
                setQuery("");
                setSelectedIndex(0);
              }}
              tabIndex={-1}
              aria-label={t("commandPalette.clearSearch")}
            >
              <span className="material-symbols-outlined text-[16px]">close</span>
            </button>
          )}
          <kbd className="hidden sm:inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded text-[10px] font-mono bg-black/5 dark:bg-white/5 text-text-muted border border-black/10 dark:border-white/10 shrink-0">
            Esc
          </kbd>
        </div>

        {grouped.length > 0 ? (
          <ul
            ref={listRef}
            className="py-2 max-h-[60vh] overflow-y-auto custom-scrollbar"
            role="listbox"
          >
            {grouped.map((group) => (
              <li key={group.sectionId} role="presentation">
                <div className="sticky top-0 z-10 bg-surface/95 backdrop-blur-sm px-6 py-1.5 text-[10px] font-semibold uppercase tracking-wider text-text-muted border-b border-black/5 dark:border-white/5">
                  {group.sectionLabel}
                </div>
                <ul role="group" aria-label={group.sectionLabel}>
                  {group.subgroups.map((subgroup) => (
                    <li
                      key={`${group.sectionId}::${subgroup.subgroupId ?? "_root"}`}
                      role="presentation"
                    >
                      {subgroup.subgroupLabel && (
                        <div className="px-6 pt-2 pb-1 text-[10px] font-medium uppercase tracking-wide text-text-muted/70">
                          {subgroup.subgroupLabel}
                        </div>
                      )}
                      <ul
                        role={subgroup.subgroupLabel ? "group" : "presentation"}
                        aria-label={subgroup.subgroupLabel ?? undefined}
                      >
                        {subgroup.items.map(({ item, flatIndex }) => (
                          <li
                            key={item.id}
                            role="option"
                            aria-selected={flatIndex === selectedIndex}
                            data-flat-index={flatIndex}
                          >
                            <button
                              className={`w-full flex items-center gap-3 ${
                                subgroup.subgroupLabel ? "pl-10 pr-6" : "px-6"
                              } py-2.5 text-left transition-colors ${
                                flatIndex === selectedIndex
                                  ? "bg-accent/10 text-accent ring-1 ring-inset ring-accent/20"
                                  : "text-text hover:bg-black/5 dark:hover:bg-white/5"
                              }`}
                              onClick={() => handleNavigate(item.href, item.external)}
                              onMouseEnter={() => setSelectedIndex(flatIndex)}
                            >
                              <span
                                className={`material-symbols-outlined text-[18px] shrink-0 ${
                                  flatIndex === selectedIndex ? "text-accent" : "text-text-muted"
                                }`}
                              >
                                {item.icon}
                              </span>
                              <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium truncate">{item.label}</p>
                                {item.subtitle && (
                                  <p
                                    className={`text-xs truncate ${
                                      flatIndex === selectedIndex
                                        ? "text-accent/70"
                                        : "text-text-muted"
                                    }`}
                                  >
                                    {item.subtitle}
                                  </p>
                                )}
                              </div>
                              {item.external && (
                                <span className="material-symbols-outlined text-[14px] text-text-muted shrink-0">
                                  open_in_new
                                </span>
                              )}
                            </button>
                          </li>
                        ))}
                      </ul>
                    </li>
                  ))}
                </ul>
              </li>
            ))}
          </ul>
        ) : (
          <div className="py-10 text-center text-text-muted text-sm">{t("noResults")}</div>
        )}

        <div className="flex items-center gap-4 px-4 py-2 border-t border-black/5 dark:border-white/5 text-[11px] text-text-muted">
          <span className="flex items-center gap-1">
            <kbd className="px-1 py-0.5 rounded bg-black/5 dark:bg-white/5 border border-black/10 dark:border-white/10 font-mono">
              ↑↓
            </kbd>
            {t("commandPalette.navigate")}
          </span>
          <span className="flex items-center gap-1">
            <kbd className="px-1 py-0.5 rounded bg-black/5 dark:bg-white/5 border border-black/10 dark:border-white/10 font-mono">
              ↵
            </kbd>
            {t("commandPalette.open")}
          </span>
          <span className="flex items-center gap-1">
            <kbd className="px-1 py-0.5 rounded bg-black/5 dark:bg-white/5 border border-black/10 dark:border-white/10 font-mono">
              Esc
            </kbd>
            {t("commandPalette.close")}
          </span>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useMemo, useEffect } from "react";
import { useTranslations } from "next-intl";
import Modal from "./Modal";
import {
  buildPassthroughAliasModels,
  buildNodeAliasModels,
  shouldConfirmSelectAll,
  parseHiddenModelsByProvider,
  isProviderModelHidden,
  buildProviderTestTargets,
  toggleProviderSelection,
  chunkItems,
  isProviderTestEntryWorking,
  formatProviderTestResults,
  collectWorkingModelsToSelect,
  hasWorkingTestResults,
  listVisibleProviderIds,
} from "./modelSelectModalHelpers";
import { getModelsByProviderId, PROVIDER_ID_TO_ALIAS } from "@/shared/constants/models";
import { getCompatibleFallbackModels } from "@/lib/providers/managedAvailableModels";
import {
  getModelCatalogSourceLabel,
  matchesModelCatalogQuery,
  normalizeModelCatalogSource,
} from "@/shared/utils/modelCatalogSearch";
import {
  OAUTH_PROVIDERS,
  NOAUTH_PROVIDERS,
  APIKEY_PROVIDERS,
  isOpenAICompatibleProvider,
  isAnthropicCompatibleProvider,
} from "@/shared/constants/providers";
import { hasEligibleConnectionForModel } from "@/domain/connectionModelRules";
import { useNotificationStore } from "@/store/notificationStore";

// Provider order: OAuth first, then no-auth, then API Key (matches dashboard/providers)
const PROVIDER_ORDER = [
  ...Object.keys(OAUTH_PROVIDERS),
  ...Object.keys(NOAUTH_PROVIDERS),
  ...Object.keys(APIKEY_PROVIDERS),
];

type ModelSelectModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (model: unknown) => void;
  /**
   * Optional toggle callback — when set, clicking a model already in
   * `addedModelValues` invokes this instead of `onSelect`, so the modal acts
   * as an in-place add/remove toggle. Ported from upstream PR
   * decolua/9router#889 (Fajar Hidayat).
   */
  onDeselect?: (model: unknown) => void;
  /**
   * Batch add for "Select all" — callers that keep the modal open (combo
   * builder) must use this instead of looping `onSelect`, because each
   * single-add handler closes over the same models snapshot.
   */
  onSelectMany?: (models: unknown[]) => void;
  /**
   * Batch remove for "Unselect all" — same stale-state reason as onSelectMany.
   */
  onDeselectMany?: (models: unknown[]) => void;
  selectedModel?: string;
  selectedModels?: string[];
  activeProviders?: Array<{
    provider: string;
    id?: string | number;
    // Present on real connection objects (see fetchConnections() callers);
    // consumed by hasEligibleConnectionForModel() for the "configured only"
    // filter toggle below (#8219 dashboard-typecheck fix — the prop type was
    // too narrow for the field the new filter actually reads).
    providerSpecificData?: unknown;
  }>;
  title?: string;
  modelAliases?: Record<string, string>;
  addedModelValues?: string[];
  multiSelect?: boolean;
  showCombos?: boolean;
  alwaysIncludeProviders?: string[] | null;
  /**
   * When true, picking a model does NOT auto-close the modal — the caller must close
   * explicitly. A "Done" button is rendered in the modal footer so the user has a clear
   * way to confirm they are finished adding entries. Useful in combo creation, where the
   * user typically adds several models in a row. Mutually exclusive with `multiSelect`
   * (which renders its own Clear + Done footer driven by `selectedModels`).
   * Inspired by upstream PR decolua/9router#1031. Combined with `onDeselect`, this also
   * enables the toggle-style deselection from upstream PR decolua/9router#889.
   */
  keepOpenOnSelect?: boolean;
};

export default function ModelSelectModal({
  isOpen,
  onClose,
  onSelect,
  onDeselect,
  onSelectMany,
  onDeselectMany,
  selectedModel,
  selectedModels = [],
  activeProviders = [],
  title,
  modelAliases = {},
  addedModelValues = [],
  multiSelect = false,
  showCombos = true,
  alwaysIncludeProviders = [],
  keepOpenOnSelect = false,
}: ModelSelectModalProps) {
  const t = useTranslations("common");
  const notify = useNotificationStore();
  const resolvedTitle = title ?? t("selectModel");
  const labelOrFallback = (key: string, fallback: string, values?: Record<string, unknown>) =>
    typeof (t as { has?: (k: string) => boolean }).has === "function" &&
    (t as { has: (k: string) => boolean }).has(key)
      ? (t as unknown as (k: string, v?: Record<string, unknown>) => string)(key, values)
      : fallback;
  const [searchQuery, setSearchQuery] = useState("");
  const [combos, setCombos] = useState<any[]>([]);
  const [providerNodes, setProviderNodes] = useState<any[]>([]);
  const [customModels, setCustomModels] = useState<Record<string, any>>({});
  // #9203: unified hidden-model map (customModels.isHidden +
  // modelCompatOverrides.isHidden) from `/api/provider-models`, normalized so
  // the picker hides every model source the operator flagged — not just custom
  // rows that carry their own `isHidden` flag.
  const [hiddenModelsByProvider, setHiddenModelsByProvider] = useState<Map<string, Set<string>>>(
    new Map()
  );
  // Models discovered live from a custom provider's upstream `/models` endpoint,
  // keyed by provider id. Merged into the alias/custom/fallback list below and
  // tagged with the `auto` source badge. Ported from upstream PR
  // decolua/9router#2018 (Hamsa_M).
  const [showConfiguredOnly, setShowConfiguredOnly] = useState(() => {
    if (typeof window === "undefined") return false;
    return localStorage.getItem("modelSelectShowConfiguredOnly") === "true";
  });

  useEffect(() => {
    localStorage.setItem("modelSelectShowConfiguredOnly", String(showConfiguredOnly));
  }, [showConfiguredOnly]);
  const [fetchedModels, setFetchedModels] = useState<Record<string, any[]>>({});
  // Provider-level selection for "Test Selected Providers" (combo builder only).
  const [selectedProviderIds, setSelectedProviderIds] = useState<Set<string>>(() => new Set());
  const [testingProviders, setTestingProviders] = useState(false);
  const [testProgress, setTestProgress] = useState<{ done: number; total: number } | null>(null);
  const [modelTestStatus, setModelTestStatus] = useState<Record<string, "ok" | "error">>({});

  const fetchCombos = async () => {
    try {
      const res = await fetch("/api/combos");
      if (!res.ok) throw new Error(`Failed to fetch combos: ${res.status}`);
      const data = await res.json();
      setCombos(data.combos || []);
    } catch (error) {
      console.error("Error fetching combos:", error);
      setCombos([]);
    }
  };

  useEffect(() => {
    if (isOpen) fetchCombos();
  }, [isOpen]);

  // Reset provider-test bookkeeping whenever the modal closes so the next
  // open starts from a clean selection / progress state.
  useEffect(() => {
    if (isOpen) return;
    setSelectedProviderIds(new Set());
    setTestingProviders(false);
    setTestProgress(null);
    setModelTestStatus({});
  }, [isOpen]);

  const fetchProviderNodes = async () => {
    try {
      const res = await fetch("/api/provider-nodes");
      if (!res.ok) throw new Error(`Failed to fetch provider nodes: ${res.status}`);
      const data = await res.json();
      setProviderNodes(data.nodes || []);
    } catch (error) {
      console.error("Error fetching provider nodes:", error);
      setProviderNodes([]);
    }
  };

  useEffect(() => {
    if (isOpen) fetchProviderNodes();
  }, [isOpen]);

  const fetchCustomModels = async () => {
    try {
      const res = await fetch("/api/provider-models");
      if (!res.ok) throw new Error(`Failed to fetch custom models: ${res.status}`);
      const data = await res.json();
      setCustomModels(data.models || {});
      // #9203: keep the unified hidden-model map in sync with the model list.
      setHiddenModelsByProvider(parseHiddenModelsByProvider(data.hiddenModelsByProvider));
    } catch (error) {
      console.error("Error fetching custom models:", error);
      setCustomModels({});
    }
  };

  useEffect(() => {
    if (isOpen) fetchCustomModels();
  }, [isOpen]);

  // Fetch the live model catalog for one custom provider from its connection's
  // upstream `/models` endpoint. Returns the model array, or null on any failure.
  const fetchProviderModels = async (providerId: string): Promise<any[] | null> => {
    try {
      // Find the connection id for this provider — the route is keyed by connection.
      const connection = activeProviders.find((p) => p.provider === providerId);
      if (!connection?.id) return null;

      // #9203: ask the live route to drop hidden models server-side too, so the
      // operator's visibility settings apply before the rows reach the picker,
      // while chatOnly excludes media and retired models from this chat surface.
      const res = await fetch(
        `/api/providers/${connection.id}/models?excludeHidden=true&chatOnly=true`
      );
      if (!res.ok) {
        console.warn(`Failed to fetch models for ${providerId}: ${res.status}`);
        return null;
      }
      const data = await res.json();
      return data.models || [];
    } catch (error) {
      console.error(`Error fetching models for ${providerId}:`, error);
      return null;
    }
  };

  // When the modal opens, dynamically load models for every connected custom
  // (openai-/anthropic-compatible) provider in parallel.
  useEffect(() => {
    if (!isOpen) return;

    let cancelled = false;

    const loadCustomProviderModels = async () => {
      const customProviderIds = activeProviders
        .filter(
          (p) => isOpenAICompatibleProvider(p.provider) || isAnthropicCompatibleProvider(p.provider)
        )
        .map((p) => p.provider);

      if (customProviderIds.length === 0) return;

      const fetched: Record<string, any[]> = {};
      await Promise.all(
        customProviderIds.map(async (providerId) => {
          const models = await fetchProviderModels(providerId);
          if (models && models.length > 1) {
            fetched[providerId] = models;
          }
        })
      );

      if (!cancelled) setFetchedModels(fetched);
    };

    loadCustomProviderModels();

    return () => {
      cancelled = true;
    };

  }, [isOpen, activeProviders]);

  const allProviders = useMemo(
    () => ({ ...OAUTH_PROVIDERS, ...NOAUTH_PROVIDERS, ...APIKEY_PROVIDERS }),
    []
  );
  const alwaysIncludeProvidersKey = Array.isArray(alwaysIncludeProviders)
    ? alwaysIncludeProviders
        .filter((providerId) => typeof providerId === "string" && providerId)
        .join("\0")
    : "";

  // Group models by provider with priority order
  const groupedModels = useMemo(() => {
    const groups: Record<string, any> = {};

    // Get all active provider IDs from connections
    const activeConnectionIds = activeProviders.map((p) => p.provider);
    const explicitProviderIds = alwaysIncludeProvidersKey
      ? alwaysIncludeProvidersKey.split("\0")
      : [];

    // Only show connected providers (including both standard and custom)
    const providerIdsToShow = new Set([
      ...activeConnectionIds, // Connected providers
      ...explicitProviderIds, // Zero-config providers required by specific clients
    ]);

    // Sort by PROVIDER_ORDER
    const sortedProviderIds = [...providerIdsToShow].sort((a, b) => {
      const indexA = PROVIDER_ORDER.indexOf(a);
      const indexB = PROVIDER_ORDER.indexOf(b);
      return (indexA === -1 ? 999 : indexA) - (indexB === -1 ? 999 : indexB);
    });

    sortedProviderIds.forEach((providerId) => {
      const alias = PROVIDER_ID_TO_ALIAS[providerId] || providerId;
      const providerInfo = allProviders[providerId] || { name: providerId, color: "#666" };
      const isCustomProvider =
        isOpenAICompatibleProvider(providerId) || isAnthropicCompatibleProvider(providerId);

      // Get user-added custom models for this provider (if any), excluding
      // any explicitly hidden by the operator (#7156 — the legacy picker
      // must respect the same isHidden flag the Precision Builder and
      // /v1/models catalog already honor). #9203: the unified hidden map
      // additionally covers catalog-override hidden rows and is applied to
      // every source below, so a hidden passthrough alias / fallback /
      // auto-fetched model is filtered exactly like a hidden custom row.
      const providerCustomModels = (customModels[providerId] || []).filter((cm) => !cm.isHidden);
      const isHiddenForProvider = (modelId: string) =>
        isProviderModelHidden(hiddenModelsByProvider, providerId, modelId);

      if (providerInfo.passthroughModels) {
        // Passthrough aliases are stored prefixed by the canonical providerId
        // (e.g. "github/gpt-4"), not the public alias (e.g. "gh/"), so we must
        // filter/strip by providerId — matching the sibling custom-provider
        // branch below. (port: decolua/9router#485)
        const aliasModels = buildPassthroughAliasModels(
          modelAliases as Record<string, string>,
          providerId
        ).filter((am) => !isHiddenForProvider(am.id));

        // Merge custom models for passthrough providers
        const customEntries = providerCustomModels
          .filter((cm) => !aliasModels.some((am) => am.id === cm.id))
          .filter((cm) => !isHiddenForProvider(cm.id))
          .map((cm) => ({
            id: cm.id,
            name: cm.name || cm.id,
            value: `${alias}/${cm.id}`,
            isCustom: true,
            source: normalizeModelCatalogSource(cm.source) === "imported" ? "imported" : "custom",
          }));

        const allModels = [...aliasModels, ...customEntries];

        if (allModels.length > 0) {
          const matchedNode = providerNodes.find((node) => node.id === providerId);
          const displayName = matchedNode?.name || providerInfo.name;

          groups[providerId] = {
            name: displayName,
            alias: alias,
            color: providerInfo.color,
            models: allModels,
          };
        }
      } else if (isCustomProvider) {
        const matchedNode = providerNodes.find((node) => node.id === providerId);
        const displayName = matchedNode?.name || providerInfo.name;
        const nodePrefix = matchedNode?.prefix || providerId; // Consider a more user-friendly fallback if providerId is a UUID

        const nodeModels = buildNodeAliasModels(
          modelAliases as Record<string, string>,
          providerId,
          nodePrefix
        ).filter((nm) => !isHiddenForProvider(nm.id));

        const fallbackEntries = (
          getCompatibleFallbackModels(providerId, providerCustomModels) || []
        )
          .filter((fm) => !nodeModels.some((nm) => nm.id === fm.id))
          .filter((fm) => !isHiddenForProvider(fm.id))
          .map((fm) => ({
            id: fm.id,
            name: fm.name || fm.id,
            value: `${nodePrefix}/${fm.id}`,
            isFallback: true,
            source: "fallback",
          }));

        // Merge custom models for custom providers
        const customEntries = providerCustomModels
          .filter(
            (cm) =>
              !nodeModels.some((nm) => nm.id === cm.id) &&
              !fallbackEntries.some((fm) => fm.id === cm.id)
          )
          .filter((cm) => !isHiddenForProvider(cm.id))
          .map((cm) => ({
            id: cm.id,
            name: cm.name || cm.id,
            value: `${nodePrefix}/${cm.id}`,
            isCustom: true,
            source: normalizeModelCatalogSource(cm.source) === "imported" ? "imported" : "custom",
          }));

        // Models discovered live from the provider's upstream `/models` endpoint.
        // Deduped against alias, fallback, and user-added custom models; tagged
        // with the `auto` source so the badge reads "auto". #9203: the server
        // already filtered hidden rows via `excludeHidden=true`, but re-check the
        // unified map here so a hidden model is dropped even on the local-catalog
        // fallback path where the query param is not passed through.
        const fetchedEntries = (fetchedModels[providerId] || [])
          .map((m) => {
            const id = m.id || m.slug || m.model || m.name;
            return {
              id,
              name: m.name || m.displayName || id,
              value: `${nodePrefix}/${id}`,
              isFetched: true,
              source: "auto",
            };
          })
          .filter(
            (fm) =>
              fm.id &&
              !nodeModels.some((nm) => nm.id === fm.id) &&
              !fallbackEntries.some((fbm) => fbm.id === fm.id) &&
              !customEntries.some((cm) => cm.id === fm.id)
          )
          .filter((fm) => !isHiddenForProvider(fm.id));

        const allModels = [...nodeModels, ...fallbackEntries, ...customEntries, ...fetchedEntries];

        if (allModels.length > 0) {
          groups[providerId] = {
            name: displayName,
            alias: nodePrefix,
            color: providerInfo.color,
            models: allModels,
            isCustom: true,
            hasModels: true,
          };
        }
      } else {
        const systemModels = getModelsByProviderId(providerId);

        // Merge system models with user-added custom models
        const systemEntries = systemModels
          .map((m) => ({
            id: m.id,
            name: m.name,
            value: `${alias}/${m.id}`,
            source: "system",
          }))
          .filter((sm) => !isHiddenForProvider(sm.id));

        const customEntries = providerCustomModels
          .filter((cm) => !systemModels.some((sm) => sm.id === cm.id))
          .filter((cm) => !isHiddenForProvider(cm.id))
          .map((cm) => ({
            id: cm.id,
            name: cm.name || cm.id,
            value: `${alias}/${cm.id}`,
            isCustom: true,
            source: normalizeModelCatalogSource(cm.source) === "imported" ? "imported" : "custom",
          }));

        const allModels = [...systemEntries, ...customEntries];

        if (allModels.length > 0) {
          groups[providerId] = {
            name: providerInfo.name,
            alias: alias,
            color: providerInfo.color,
            models: allModels,
          };
        }
      }
    });

    return groups;
  }, [
    activeProviders,
    alwaysIncludeProvidersKey,
    modelAliases,
    allProviders,
    providerNodes,
    customModels,
    fetchedModels,
    hiddenModelsByProvider,
  ]);

  // Filter combos by search query
  const filteredCombos = useMemo(() => {
    if (!searchQuery.trim()) return combos;
    const query = searchQuery.toLowerCase();
    return combos.filter((c) => c.name.toLowerCase().includes(query));
  }, [combos, searchQuery]);

  // Filter models by search query
  const filteredGroups = useMemo(() => {
    if (!searchQuery.trim()) return groupedModels;

    const query = searchQuery.toLowerCase();
    const filtered: Record<string, any> = {};

    Object.entries(groupedModels).forEach(([providerId, group]: [string, any]) => {
      const matchedModels = group.models.filter((model) =>
        matchesModelCatalogQuery(query, {
          modelId: model.id,
          modelName: model.name,
          source: model.source,
        })
      );

      const providerNameMatches = group.name.toLowerCase().includes(query);

      if (matchedModels.length > 0 || providerNameMatches) {
        filtered[providerId] = {
          ...group,
          models: matchedModels.length > 0 ? matchedModels : group.models,
        };
      }
    });

    return filtered;
  }, [groupedModels, searchQuery]);

  // Filter models by connection eligibility when toggle is on
  const connectionFilteredGroups = useMemo(() => {
    if (!showConfiguredOnly) return filteredGroups;

    const result: Record<string, any> = {};
    Object.entries(filteredGroups).forEach(([providerId, group]: [string, any]) => {
      const providerConnections = activeProviders.filter((p: any) => p.provider === providerId);
      if (providerConnections.length === 0) return;

      const eligibleModels = group.models.filter((model: any) =>
        hasEligibleConnectionForModel(providerConnections, model.id)
      );
      if (eligibleModels.length > 0) {
        result[providerId] = { ...group, models: eligibleModels };
      }
    });
    return result;
  }, [filteredGroups, showConfiguredOnly, activeProviders]);

  // Flat list of currently visible provider models (respects search + configured-only).
  // Used by Select all / Unselect all — does not include the Combos section.
  const visibleModels = useMemo(() => {
    const models: any[] = [];
    Object.values(connectionFilteredGroups).forEach((group: any) => {
      if (Array.isArray(group?.models)) {
        models.push(...group.models);
      }
    });
    return models;
  }, [connectionFilteredGroups]);

  const addedModelValueSet = useMemo(() => new Set(addedModelValues), [addedModelValues]);

  const allVisibleSelected =
    visibleModels.length > 0 &&
    visibleModels.every(
      (model) => typeof model?.value === "string" && addedModelValueSet.has(model.value)
    );

  const showSelectAllToggle =
    keepOpenOnSelect &&
    !multiSelect &&
    typeof onSelectMany === "function" &&
    typeof onDeselectMany === "function" &&
    visibleModels.length > 0;

  // Same combo-builder gate as Select All — CLI tool cards and other single-pick
  // callers should not grow provider checkboxes / a test toolbar.
  const showProviderTestControls = keepOpenOnSelect && !multiSelect;

  const workingModelsToSelect = useMemo(
    () =>
      collectWorkingModelsToSelect({
        models: visibleModels,
        modelTestStatus,
        addedModelValues,
        alreadyAdded: false,
      }),
    [visibleModels, modelTestStatus, addedModelValues]
  );

  const workingModelsToUnselect = useMemo(
    () =>
      collectWorkingModelsToSelect({
        models: visibleModels,
        modelTestStatus,
        addedModelValues,
        alreadyAdded: true,
      }),
    [visibleModels, modelTestStatus, addedModelValues]
  );

  const visibleProviderIds = useMemo(
    () => listVisibleProviderIds(connectionFilteredGroups),
    [connectionFilteredGroups]
  );

  const allProvidersChecked =
    visibleProviderIds.length > 0 && visibleProviderIds.every((id) => selectedProviderIds.has(id));

  const showSelectWorkingModels =
    showProviderTestControls &&
    typeof onSelectMany === "function" &&
    typeof onDeselectMany === "function" &&
    !testingProviders &&
    hasWorkingTestResults(modelTestStatus);

  const canAddWorking = workingModelsToSelect.length > 0;
  const canRemoveWorking = workingModelsToUnselect.length > 0;

  const handleToggleSelectAllVisible = () => {
    if (!showSelectAllToggle) return;
    if (allVisibleSelected) {
      const toRemove = visibleModels.filter(
        (model) => typeof model?.value === "string" && addedModelValueSet.has(model.value)
      );
      if (toRemove.length > 0) onDeselectMany!(toRemove);
      return;
    }
    const toAdd = visibleModels.filter(
      (model) => typeof model?.value === "string" && !addedModelValueSet.has(model.value)
    );
    if (toAdd.length === 0) return;
    // Guard against a single click adding hundreds of models (e.g. with
    // "Show configured only" off) — see modelSelectModalHelpers.ts (#8526).
    if (
      shouldConfirmSelectAll(toAdd.length) &&
      !confirm(
        labelOrFallback("selectAllConfirm", `Add ${toAdd.length} models to this combo?`, {
          count: toAdd.length,
        })
      )
    ) {
      return;
    }
    onSelectMany!(toAdd);
  };

  const handleToggleProviderForTest = (providerId: string) => {
    setSelectedProviderIds((prev) => toggleProviderSelection(prev, providerId));
  };

  const handleSelectAllProviders = () => {
    setSelectedProviderIds(new Set(visibleProviderIds));
  };

  const handleClearProviderSelection = () => {
    setSelectedProviderIds(new Set());
  };

  /** Add or remove models that passed the last Test providers run. */
  const handleToggleWorkingModels = () => {
    if (!showSelectWorkingModels) return;
    if (canAddWorking) {
      if (
        shouldConfirmSelectAll(workingModelsToSelect.length) &&
        !confirm(
          labelOrFallback(
            "selectAllConfirm",
            `Add ${workingModelsToSelect.length} models to this combo?`,
            { count: workingModelsToSelect.length }
          )
        )
      ) {
        return;
      }
      onSelectMany!(workingModelsToSelect);
      return;
    }
    if (canRemoveWorking && typeof onDeselectMany === "function") {
      onDeselectMany(workingModelsToUnselect);
    }
  };

  /**
   * Smoke-test every currently-visible model under the providers the user
   * checked — same /api/models/test-all + chunk-of-3 concurrency as the
   * provider detail page "Test all models" button.
   */
  const handleTestSelectedProviders = async () => {
    if (testingProviders) return;
    if (selectedProviderIds.size === 0) {
      notify.error(
        labelOrFallback("noProvidersSelectedToTest", "Select at least one provider to test")
      );
      return;
    }

    const groups: Array<[string, Array<{ value?: string | null; id?: string | null }>]> =
      Object.entries(connectionFilteredGroups).map(([providerId, group]: [string, any]) => [
        providerId,
        Array.isArray(group?.models) ? group.models : [],
      ]);

    const targets = buildProviderTestTargets({
      selectedProviderIds,
      groups,
      activeProviders,
    });

    const flat = targets.flatMap((target) =>
      target.modelIds.map((modelId) => ({
        providerId: target.providerId,
        connectionId: target.connectionId,
        modelId,
      }))
    );

    if (flat.length === 0) {
      notify.error(
        labelOrFallback(
          "noModelsToTestForProviders",
          "No models to test for the selected providers"
        )
      );
      return;
    }

    setTestingProviders(true);
    setTestProgress({ done: 0, total: flat.length });

    let ok = 0;
    let error = 0;

    for (const chunk of chunkItems(flat)) {
      await Promise.all(
        chunk.map(async ({ providerId, connectionId, modelId }) => {
          try {
            const result: {
              results?: Record<string, { status?: string | null }>;
            } = await fetch("/api/models/test-all", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                providerId,
                connectionId,
                modelIds: [modelId],
              }),
            }).then((r) => r.json());

            const entry = result.results?.[modelId];
            const working = isProviderTestEntryWorking(entry);
            if (working) ok++;
            else error++;
            setModelTestStatus((prev) => ({
              ...prev,
              [modelId]: working ? "ok" : "error",
            }));
          } catch {
            error++;
            setModelTestStatus((prev) => ({ ...prev, [modelId]: "error" }));
          }
          setTestProgress((prev) => (prev ? { done: prev.done + 1, total: prev.total } : null));
        })
      );
    }

    const total = ok + error;
    notify.info(
      labelOrFallback("testSelectedProvidersResults", formatProviderTestResults(ok, total), {
        ok,
        total,
      })
    );
    setTestingProviders(false);
    setTestProgress(null);
  };

  const resolvedSelectedModels = multiSelect
    ? selectedModels
    : selectedModel
      ? [selectedModel]
      : [];

  const isValueSelected = (value: string) => resolvedSelectedModels.includes(value);

  const handleSelect = (model: any) => {
    // Upstream PR decolua/9router#889: when the model is already in
    // `addedModelValues` AND a deselect callback was supplied, the click acts
    // as an in-place remove instead of a duplicate add.
    const candidateValue =
      typeof model?.value === "string"
        ? model.value
        : typeof model?.name === "string"
          ? model.name
          : typeof model === "string"
            ? model
            : "";
    const isAdded = candidateValue ? addedModelValues.includes(candidateValue) : false;

    if (isAdded && onDeselect) {
      onDeselect(model);
    } else {
      onSelect(model);
    }

    // Legacy single-pick auto-closes; multiSelect or keepOpenOnSelect keep the
    // modal open so the user can toggle several entries in a row.
    if (!multiSelect && !keepOpenOnSelect) {
      onClose();
      setSearchQuery("");
    }
  };

  // Footer "Done" button for single-select callers that opted out of auto-close
  // (e.g. combo creation, where users add several models in a row). Skipped when
  // `multiSelect` is on — that mode renders its own Clear + Done footer below the body.
  const doneFooter =
    keepOpenOnSelect && !multiSelect ? (
      <button
        type="button"
        onClick={() => {
          onClose();
          setSearchQuery("");
        }}
        className="w-full px-3 py-2 text-sm font-medium rounded border border-primary bg-primary text-white hover:bg-primary/90 transition-colors"
      >
        {t("done")}
      </button>
    ) : null;

  return (
    <Modal
      isOpen={isOpen}
      onClose={() => {
        onClose();
        setSearchQuery("");
      }}
      title={resolvedTitle}
      size="xl"
      className="p-4! max-w-2xl"
      footer={doneFooter}
    >
      {/* Search - compact */}
      <div className="mb-3">
        <div className="relative">
          <span className="material-symbols-outlined absolute left-2.5 top-1/2 -translate-y-1/2 text-text-muted text-[16px]">
            search
          </span>
          <input
            type="text"
            placeholder={t("search")}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-8 pr-3 py-1.5 bg-surface border border-border rounded text-xs focus:outline-none focus:ring-1 focus:ring-primary/50"
          />
        </div>
      </div>

      <div className="mt-1.5 mb-2 space-y-2">
        <div className="flex items-center justify-between gap-2 flex-wrap">
          <label className="flex items-center gap-1.5 text-xs text-text-muted cursor-pointer min-w-0">
            <input
              type="checkbox"
              checked={showConfiguredOnly}
              onChange={(e) => setShowConfiguredOnly(e.target.checked)}
              className="rounded border-border"
            />
            <span className="truncate">{t("showConfiguredOnly")}</span>
          </label>

          {showSelectAllToggle && (
            <button
              type="button"
              onClick={handleToggleSelectAllVisible}
              data-testid="model-select-toggle-all-visible"
              className="shrink-0 px-2 py-1 text-xs font-medium rounded border border-border bg-surface text-text-main hover:border-primary/50 hover:bg-primary/5 transition-colors"
            >
              {allVisibleSelected
                ? labelOrFallback("unselectAll", "Unselect all")
                : labelOrFallback("selectAll", "Select all")}
              <span className="ml-1 text-[10px] text-text-muted font-normal">
                ({visibleModels.length})
              </span>
            </button>
          )}
        </div>

        {showProviderTestControls && (
          <div
            className="rounded-lg border border-border bg-black/[0.02] dark:bg-white/[0.02] px-2.5 py-2 space-y-2"
            data-testid="model-select-provider-test-panel"
          >
            <p className="text-[11px] text-text-muted leading-snug">
              {labelOrFallback(
                "providerTestHint",
                "Tip: check a provider → Test → Add working (or Remove working to undo)."
              )}
            </p>

            <div className="flex items-center justify-between gap-2 flex-wrap">
              <div className="flex items-center gap-1.5 flex-wrap">
                <span className="text-[11px] text-text-muted">
                  {labelOrFallback(
                    "providersSelectedCount",
                    `${selectedProviderIds.size} providers checked`,
                    { count: selectedProviderIds.size }
                  )}
                </span>
                <button
                  type="button"
                  onClick={
                    allProvidersChecked ? handleClearProviderSelection : handleSelectAllProviders
                  }
                  disabled={visibleProviderIds.length === 0 || testingProviders}
                  data-testid="model-select-toggle-all-providers"
                  className="px-2 py-0.5 text-[11px] font-medium rounded border border-border bg-surface text-text-main hover:border-primary/50 hover:bg-primary/5 transition-colors disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {allProvidersChecked
                    ? labelOrFallback("clearProviderSelection", "Uncheck providers")
                    : labelOrFallback("selectAllProviders", "Check all providers")}
                </button>
              </div>

              <div className="flex items-center gap-1.5 flex-wrap justify-end">
                <button
                  type="button"
                  onClick={handleTestSelectedProviders}
                  disabled={testingProviders || selectedProviderIds.size === 0}
                  data-testid="model-select-test-selected-providers"
                  title={labelOrFallback("testSelectedProviders", "Test providers")}
                  className="flex items-center gap-1 px-2 py-1 text-xs font-medium rounded border border-border bg-surface text-text-main hover:border-primary/50 hover:bg-primary/5 transition-colors disabled:cursor-not-allowed disabled:opacity-50"
                >
                  <span
                    className={`material-symbols-outlined text-[14px] ${
                      testingProviders ? "animate-spin" : ""
                    }`}
                  >
                    {testingProviders ? "progress_activity" : "science"}
                  </span>
                  <span>
                    {testingProviders && testProgress
                      ? labelOrFallback(
                          "testingSelectedProviders",
                          `Testing ${testProgress.done}/${testProgress.total}...`,
                          testProgress
                        )
                      : labelOrFallback("testSelectedProviders", "Test providers")}
                  </span>
                </button>

                {showSelectWorkingModels && (
                  <button
                    type="button"
                    onClick={handleToggleWorkingModels}
                    disabled={!canAddWorking && !canRemoveWorking}
                    data-testid="model-select-working-models"
                    className={`shrink-0 px-2 py-1 text-xs font-medium rounded border transition-colors disabled:cursor-not-allowed disabled:opacity-50 ${
                      canRemoveWorking
                        ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-700 dark:text-emerald-400"
                        : "border-border bg-surface text-text-main hover:border-primary/50 hover:bg-primary/5"
                    }`}
                  >
                    {canRemoveWorking
                      ? labelOrFallback("unselectWorkingModels", "Unselect working")
                      : labelOrFallback("selectWorkingModels", "Add working")}
                    <span
                      className={`ml-1 text-[10px] font-normal ${
                        canRemoveWorking ? "opacity-80" : "text-text-muted"
                      }`}
                    >
                      (
                      {canRemoveWorking
                        ? workingModelsToUnselect.length
                        : workingModelsToSelect.length}
                      )
                    </span>
                  </button>
                )}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Models grouped by provider - compact */}
      <div className="max-h-[min(50vh,420px)] overflow-y-auto space-y-3 isolate">
        {/* Combos section - always first */}
        {showCombos && filteredCombos.length > 0 && (
          <div>
            <div className="flex items-center gap-1.5 mb-1.5 sticky top-0 z-10 bg-surface py-1">
              <span className="material-symbols-outlined text-primary text-[14px]">layers</span>
              <span className="text-xs font-medium text-primary">{t("combos")}</span>
              <span className="text-[10px] text-text-muted">({filteredCombos.length})</span>
            </div>
            <div className="flex flex-wrap gap-1.5">
              {filteredCombos.map((combo) => {
                const isSelected = isValueSelected(combo.name);
                return (
                  <button
                    key={combo.id}
                    onClick={() =>
                      handleSelect({ id: combo.name, name: combo.name, value: combo.name })
                    }
                    className={`
                      px-2 py-1 rounded-xl text-xs font-medium transition-all border hover:cursor-pointer
                      ${
                        isSelected
                          ? "bg-primary text-white border-primary"
                          : "bg-surface border-border text-text-main hover:border-primary/50 hover:bg-primary/5"
                      }
                    `}
                  >
                    {combo.name}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Provider models */}
        {Object.entries(connectionFilteredGroups).map(([providerId, group]: [string, any]) => {
          const providerSelected = selectedProviderIds.has(providerId);
          return (
            <div key={providerId}>
              {/* Provider header — opaque sticky bg so model chips never bleed through */}
              <div
                className={`flex items-center gap-1.5 mb-2 sticky top-0 z-10 py-1.5 px-1 rounded bg-surface ${
                  providerSelected ? "ring-1 ring-inset ring-primary/35" : ""
                }`}
              >
                {showProviderTestControls ? (
                  <label className="flex items-center gap-1.5 min-w-0 cursor-pointer flex-1">
                    <input
                      type="checkbox"
                      checked={providerSelected}
                      onChange={() => handleToggleProviderForTest(providerId)}
                      data-testid={`model-select-provider-checkbox-${providerId}`}
                      aria-label={`Check ${group.name} for testing`}
                      className="rounded border-border shrink-0"
                    />
                    <div
                      className="w-2 h-2 rounded-full shrink-0"
                      style={{ backgroundColor: group.color }}
                    />
                    <span className="text-xs font-medium text-primary truncate">{group.name}</span>
                    <span className="text-[10px] text-text-muted shrink-0">
                      ({group.models.length})
                    </span>
                  </label>
                ) : (
                  <>
                    <div
                      className="w-2 h-2 rounded-full shrink-0"
                      style={{ backgroundColor: group.color }}
                    />
                    <span className="text-xs font-medium text-primary">{group.name}</span>
                    <span className="text-[10px] text-text-muted">({group.models.length})</span>
                  </>
                )}
              </div>

              <div className="flex flex-wrap gap-1.5">
                {group.models.map((model) => {
                  const isSelected = isValueSelected(model.value);
                  const isAdded = addedModelValues.includes(model.value);
                  const testStatus = modelTestStatus[model.value];
                  return (
                    <button
                      key={model.id}
                      onClick={() => handleSelect(model)}
                      className={`
                      px-2 py-1 rounded-xl text-xs font-medium transition-all border hover:cursor-pointer
                      ${
                        isSelected
                          ? "bg-primary text-white border-primary"
                          : isAdded
                            ? "bg-emerald-500/15 border-emerald-500/30 text-emerald-700 dark:text-emerald-400"
                            : testStatus === "ok"
                              ? "bg-surface border-emerald-500/40 text-text-main"
                              : testStatus === "error"
                                ? "bg-surface border-red-500/40 text-text-main"
                                : "bg-surface border-border text-text-main hover:border-primary/50 hover:bg-primary/5"
                      }
                    `}
                    >
                      {isAdded && <span className="mr-0.5 opacity-70">✓</span>}
                      {model.name}
                      {model.source && (
                        <span className="ml-1 text-[10px] uppercase opacity-70">
                          {getModelCatalogSourceLabel(model.source)}
                        </span>
                      )}
                      {testStatus === "ok" && (
                        <span className="ml-1 rounded px-1 py-px text-[9px] font-semibold uppercase tracking-wide bg-emerald-500/20 text-emerald-700 dark:text-emerald-400">
                          ok
                        </span>
                      )}
                      {testStatus === "error" && (
                        <span className="ml-1 rounded px-1 py-px text-[9px] font-semibold uppercase tracking-wide bg-red-500/20 text-red-600 dark:text-red-400">
                          fail
                        </span>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}

        {Object.keys(connectionFilteredGroups).length === 0 && filteredCombos.length === 0 && (
          <div className="text-center py-4 text-text-muted">
            <span className="material-symbols-outlined text-2xl mb-1 block">search_off</span>
            <p className="text-xs">{t("noModelsFound")}</p>
          </div>
        )}
      </div>
      {multiSelect && (
        <div className="mt-4 flex items-center justify-between gap-2 border-t border-border pt-3">
          <span className="text-xs text-text-muted">{resolvedSelectedModels.length} selected</span>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => onSelect(null)}
              className="px-2 py-1 text-xs rounded border border-border bg-surface hover:bg-primary/5"
            >
              {t("clear")}
            </button>
            <button
              type="button"
              onClick={() => {
                onClose();
                setSearchQuery("");
              }}
              className="px-2 py-1 text-xs rounded border border-border bg-surface hover:bg-primary/5"
            >
              {t("done")}
            </button>
          </div>
        </div>
      )}
    </Modal>
  );
}

"use client";

import { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { useTranslations } from "next-intl";

import Modal from "./Modal";
import Button from "./Button";
import Input from "./Input";
import {
  OAuthDeviceCodePanel,
  OAuthLoopbackMismatchPanel,
  OAuthManualInputPanel,
} from "./OAuthModalPanels";
import { parseResponseBody, getErrorMessage } from "@/shared/utils/api";
import { isCredentialBlob, submitCredentialBlob } from "@/shared/components/oauthBlobSubmit";
import {
  looksLikeCodexSessionJson,
  parseCodexSessionJson,
} from "@/lib/oauth/utils/codexSessionImport";
import GheConfigStep from "@/shared/components/oauthModal/GheConfigStep";
import GitlabDuoSetupStep from "@/shared/components/oauthModal/GitlabDuoSetupStep";
import OAuthErrorStep from "@/shared/components/oauthModal/OAuthErrorStep";
import OAuthWaitingStep from "@/shared/components/oauthModal/OAuthWaitingStep";
import { parseGrokCliPasteToken } from "@/lib/oauth/utils/grokCliAuthJson";
import { buildGoogleLoopbackHint } from "@/lib/oauth/utils/googleLoopbackHint";
import {
  buildPkceLoopbackMismatchHint,
  type PkceLoopbackMismatchHint,
} from "@/lib/oauth/utils/pkceLoopbackWarning";

export { formatDeviceCodeRemaining } from "./OAuthModalPanels";

const GOOGLE_OAUTH_PROVIDERS = new Set(["antigravity", "agy"]);

/** Providers that use a local callback server on a random port (PKCE browser flow). */
const PKCE_CALLBACK_SERVER_PROVIDERS = new Set(["codex", "xai-oauth", "grok-cli"]);

// grok-cli is wired into BOTH the device-code panel (its default, #7358) and
// the browser PKCE + import-token paths above/below (#7013) — the user picks
// via the "Device Code" / "Browser Login" / "JWT Token" tabs rendered further
// down. See the grokBrowserMode state and handleDeviceCodeMode/handleBrowserMode
// below for how the method choice is threaded into startOAuthFlow.
const DEVICE_CODE_PROVIDERS = new Set([
  "github",
  "kiro",
  "amazon-q",
  "kimi-coding",
  "kilocode",
  "codebuddy-cn",
  "ghe-copilot",
  "grok-cli",
]);

const TOKEN_PASTE_PROVIDERS = new Set(["devin-desktop", "devin-cli", "grok-cli"]);
const IMPORT_TOKEN_ONLY_PROVIDERS = new Set(["devin-desktop", "devin-cli"]);

// POST a bare Codex access token to the access-token-only import endpoint
// (#1290); shared by the bare-JWT and session-JSON paste branches (#6636).
async function submitCodexAccessToken(
  accessToken: string,
  name: string | undefined,
  setStep: (s: string) => void,
  onSuccess: (() => void) | undefined,
  fallbackErrorMessage: string
): Promise<void> {
  const res = await fetch("/api/oauth/codex/import-token", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ accessToken, name }),
  });
  const data = (await parseResponseBody(res)) as Record<string, unknown>;
  if (!res.ok) {
    throw new Error(getErrorMessage(data, res.status, fallbackErrorMessage));
  }
  setStep("success");
  onSuccess?.();
}

type OAuthModalProps = {
  isOpen: boolean;
  provider?: string;
  providerInfo?: { name?: string } | null;
  onSuccess?: () => void;
  onClose: () => void;
  idcConfig?: unknown;
  reauthConnection?: null | { id?: string };
};

type DevicePollResult =
  { status: "pending" | "slow_down" | "success" } | { status: "error"; message: string };

function positiveNumberOr(value: unknown, fallback: number): number {
  return Math.max(1, Number(value) || fallback);
}

async function pollDeviceCodeOnce(
  provider: string | undefined,
  payload: Record<string, unknown>,
  fallbackErrorMessage: string
): Promise<DevicePollResult> {
  try {
    const res = await fetch(`/api/oauth/${provider}/poll`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const data = (await parseResponseBody(res)) as Record<string, unknown>;

    if (data.success) return { status: "success" };
    if (data.error === "slow_down") return { status: "slow_down" };
    if (data.error && !data.pending) {
      return { status: "error", message: String(data.errorDescription || data.error) };
    }
    return { status: "pending" };
  } catch (error) {
    return {
      status: "error",
      message: error instanceof Error ? error.message : fallbackErrorMessage,
    };
  }
}

/**
 * OAuth Modal Component
 * - Localhost: Auto callback via popup message
 * - Remote: Manual paste callback URL
 */
export default function OAuthModal({
  isOpen,
  provider,
  providerInfo,
  onSuccess,
  onClose,
  idcConfig,
  reauthConnection,
}: OAuthModalProps) {
  const t = useTranslations("oauthModal");
  const [step, setStep] = useState("waiting"); // waiting | input | success | error
  const [authData, setAuthData] = useState(null);
  const [callbackUrl, setCallbackUrl] = useState("");
  const [error, setError] = useState(null);
  const [isDeviceCode, setIsDeviceCode] = useState(false);
  const [deviceData, setDeviceData] = useState(null);
  const [gheUrl, setGheUrl] = useState("");
  const [polling, setPolling] = useState(false);
  const [deviceCodeExpiresAt, setDeviceCodeExpiresAt] = useState<number | null>(null);
  const [deviceCodeSecondsRemaining, setDeviceCodeSecondsRemaining] = useState<number | null>(null);
  // API-key paste mode for direct-token providers.
  const [showPasteToken, setShowPasteToken] = useState(IMPORT_TOKEN_ONLY_PROVIDERS.has(provider));
  const [pasteToken, setPasteToken] = useState("");
  const [savingToken, setSavingToken] = useState(false);
  // grok-cli only (#7013 rework): device_code is the default method (matches
  // DEVICE_CODE_PROVIDERS); flipping this to true routes startOAuthFlow through
  // the browser PKCE / PKCE_CALLBACK_SERVER_PROVIDERS branch instead.
  const [grokBrowserMode, setGrokBrowserMode] = useState(false);
  // #8046 follow-up: structured diagnosis for the LAN-IP loopback mismatch, rendered
  // by its own step instead of as prose inside the generic red error step.
  const [loopbackHint, setLoopbackHint] = useState<PkceLoopbackMismatchHint | null>(null);

  const supportsTokenPaste = TOKEN_PASTE_PROVIDERS.has(provider);
  const importTokenOnly = IMPORT_TOKEN_ONLY_PROVIDERS.has(provider);
  const popupRef = useRef(null);
  const deviceFlowRunRef = useRef(0);
  const deviceVerificationUrl =
    deviceData?.verification_uri_complete || deviceData?.verification_uri || "";

  // Client-only runtime values
  const runtimeLocation = useMemo(() => {
    if (typeof window === "undefined") {
      return {
        isLocalhost: false,
        isTrueLocalhost: false,
        placeholderUrl: "/callback?code=...",
        loopbackLocation: { hostname: "", port: "", protocol: "http:" },
      };
    }

    const hostname = window.location.hostname;
    const isLocal =
      hostname === "localhost" ||
      hostname === "127.0.0.1" ||
      hostname.startsWith("192.168.") ||
      hostname.startsWith("10.") ||
      /^172\.(1[6-9]|2\d|3[01])\./.test(hostname);
    const isTrulyLocal = hostname === "localhost" || hostname === "127.0.0.1";

    return {
      isLocalhost: isLocal,
      isTrueLocalhost: isTrulyLocal,
      placeholderUrl: `${window.location.origin}/callback?code=...`,
      loopbackLocation: {
        hostname,
        port: window.location.port,
        protocol: window.location.protocol,
      },
    };
  }, []);

  const { isLocalhost, isTrueLocalhost, placeholderUrl, loopbackLocation } = runtimeLocation;
  const callbackProcessedRef = useRef(false);
  const flowStartedRef = useRef(false);

  const invalidateDeviceFlow = useCallback(() => {
    deviceFlowRunRef.current += 1;
    setPolling(false);
    setDeviceCodeExpiresAt(null);
    setDeviceCodeSecondsRemaining(null);
  }, []);

  // Define all useCallback hooks BEFORE the useEffects that reference them

  // Exchange tokens
  const exchangeTokens = useCallback(
    async (code, state) => {
      if (!authData) return;
      try {
        if (!authData.redirectUri || !authData.codeVerifier) {
          throw new Error(t("errorSessionIncomplete"));
        }

        const normalizedState = typeof state === "string" && state.length > 0 ? state : undefined;

        const res = await fetch(`/api/oauth/${provider}/exchange`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            code,
            redirectUri: authData.redirectUri,
            connectionId: reauthConnection?.id,
            codeVerifier: authData.codeVerifier,
            ...(normalizedState ? { state: normalizedState } : {}),
          }),
        });

        const data = (await parseResponseBody(res)) as Record<string, unknown>;
        if (!res.ok) {
          const errorObject =
            typeof data.error === "object" && data.error !== null
              ? (data.error as Record<string, unknown>)
              : null;
          const errMsg = errorObject
            ? (errorObject.message as string) || JSON.stringify(errorObject)
            : data.error || t("errorExchangeFailed");
          const details = Array.isArray(errorObject?.details)
            ? (errorObject.details as Array<{ field?: string; message?: string }>)
                .map((detail) => {
                  if (!detail?.message) return null;
                  return detail.field ? `${detail.field}: ${detail.message}` : detail.message;
                })
                .filter(Boolean)
                .join("; ")
            : "";
          throw new Error(details ? `${errMsg} (${details})` : errMsg);
        }

        setStep("success");
        onSuccess?.();
      } catch (err) {
        // Provide actionable guidance for redirect_uri_mismatch on Google OAuth providers
        if (
          err.message?.toLowerCase().includes("redirect_uri_mismatch") &&
          GOOGLE_OAUTH_PROVIDERS.has(provider)
        ) {
          setError(t("errorGoogleRedirectMismatch"));
        } else {
          setError(err.message);
        }
        setStep("error");
      }
    },
    [authData, provider, onSuccess, reauthConnection, t]
  );

  // Save a raw API token directly (Devin Desktop / Devin CLI import-token path).
  // For grok-cli, require the full auth.json object so refresh_token is persisted (#7610).
  const handleSaveToken = useCallback(async () => {
    const raw = pasteToken.trim();
    if (!raw || !provider) return;
    setSavingToken(true);
    setError(null);
    try {
      let token: string | Record<string, unknown> = raw;
      if (provider === "grok-cli") {
        const parsed = parseGrokCliPasteToken(raw);
        if (parsed.ok === false) {
          setError(parsed.error);
          return;
        }
        token = parsed.token;
      }
      // POST to /import-token. Grok accepts full auth.json; Devin accepts bare keys.
      const res = await fetch(`/api/oauth/${provider}/import-token`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          token,
          connectionId: reauthConnection?.id,
        }),
      });
      const data = (await parseResponseBody(res)) as Record<string, unknown>;
      if (!res.ok) {
        const errMsg = getErrorMessage(data, res.status, t("errorSaveFailed"));
        throw new Error(errMsg);
      }
      setStep("success");
      onSuccess?.();
    } catch (err) {
      // Show error inline inside the paste-token form (don't flip to error step)
      setError(err.message);
    } finally {
      setSavingToken(false);
    }
  }, [pasteToken, provider, onSuccess, reauthConnection, t]);

  // Poll for device code token
  const startPolling = useCallback(
    async (deviceCode, codeVerifier, interval, expiresIn, extraData) => {
      const runId = ++deviceFlowRunRef.current;
      const safeInterval = positiveNumberOr(interval, 5);
      const safeExpiresIn = positiveNumberOr(expiresIn, safeInterval * 60);
      const deadline = Date.now() + safeExpiresIn * 1000;
      let currentInterval = safeInterval;

      setPolling(true);
      setDeviceCodeExpiresAt(deadline);

      while (Date.now() < deadline) {
        await new Promise((resolve) => setTimeout(resolve, currentInterval * 1000));
        if (runId !== deviceFlowRunRef.current || Date.now() >= deadline) break;

        const result = await pollDeviceCodeOnce(
          provider,
          {
            deviceCode,
            connectionId: reauthConnection?.id,
            codeVerifier,
            extraData,
          },
          t("errorAuthorizationFailed")
        );
        if (runId !== deviceFlowRunRef.current) return;

        if (result.status === "success") {
          setStep("success");
          setPolling(false);
          setDeviceCodeExpiresAt(null);
          onSuccess?.();
          return;
        }

        if (result.status === "slow_down") {
          currentInterval = Math.min(currentInterval + 5, 30);
          continue;
        }

        if (result.status === "error") {
          setError(result.message);
          setStep("error");
          setPolling(false);
          setDeviceCodeExpiresAt(null);
          return;
        }
      }

      if (runId === deviceFlowRunRef.current) {
        setError(t("errorAuthorizationTimeout"));
        setStep("error");
        setPolling(false);
        setDeviceCodeExpiresAt(null);
      }
    },
    [provider, onSuccess, reauthConnection, t]
  );

  // Start OAuth flow. `opts.grokBrowser` lets the grok-cli method tabs force a
  // specific branch synchronously (avoids reading a just-set state value through
  // a stale closure); when omitted, falls back to the grokBrowserMode state.
  const startOAuthFlow = useCallback(
    async (opts?: { grokBrowser?: boolean }) => {
      if (!provider) return;
      try {
        setError(null);

        const grokWantsBrowser = provider === "grok-cli" && (opts?.grokBrowser ?? grokBrowserMode);

        // Device code flow
        if (DEVICE_CODE_PROVIDERS.has(provider) && !grokWantsBrowser) {
          invalidateDeviceFlow();
          setIsDeviceCode(true);
          setDeviceData(null);
          setStep("waiting");

          // GHE Copilot needs the enterprise URL collected first (see ghe-config step)
          if (provider === "ghe-copilot" && !gheUrl.trim()) {
            setStep("ghe-config");
            return;
          }

          const deviceCodeUrl = new URL(
            `/api/oauth/${provider}/device-code`,
            window.location.origin
          );
          if (
            (provider === "kiro" || provider === "amazon-q") &&
            idcConfig &&
            typeof idcConfig === "object"
          ) {
            const idc = idcConfig as { startUrl?: string; region?: string };
            if (typeof idc.startUrl === "string" && idc.startUrl.trim()) {
              deviceCodeUrl.searchParams.set("startUrl", idc.startUrl.trim());
            }
            if (typeof idc.region === "string" && idc.region.trim()) {
              deviceCodeUrl.searchParams.set("region", idc.region.trim());
            }
          }
          if (provider === "ghe-copilot" && gheUrl.trim()) {
            deviceCodeUrl.searchParams.set("gheUrl", gheUrl.trim());
          }

          const res = await fetch(deviceCodeUrl.toString());
          const data = (await parseResponseBody(res)) as Record<string, unknown>;
          if (!res.ok) {
            const errMsg = getErrorMessage(data, res.status, t("errorRequestFailed"));
            throw new Error(errMsg);
          }

          setDeviceData(data);

          // Open verification URL
          const verifyUrl = data.verification_uri_complete || data.verification_uri;
          if (typeof verifyUrl === "string" && verifyUrl) window.open(verifyUrl, "oauth_verify");

          // Start polling - pass extraData for Kiro (contains _clientId, _clientSecret)
          const extraData =
            provider === "kiro" || provider === "amazon-q"
              ? {
                  _clientId: data._clientId,
                  _clientSecret: data._clientSecret,
                  _region: data._region,
                }
              : provider === "ghe-copilot" && gheUrl.trim()
                ? { gheUrl: gheUrl.trim() }
                : null;
          startPolling(
            data.device_code,
            data.codeVerifier,
            data.interval || 5,
            data.expires_in,
            extraData
          );
          return;
        }

        let forceManual = false;

        // Claude Code and Cline OAuth flows can finish on provider-hosted pages that
        // show an auth code instead of redirecting back to OmniRoute.
        // Start directly in manual mode so users always have an input to paste code/url.
        // zed-hosted's native-app sign-in always redirects the browser to a local
        // 127.0.0.1:<port> callback that OmniRoute never listens on (the port is
        // arbitrary and unrelated to the dashboard's own port) — nothing can
        // auto-close the popup, so always show the manual paste-URL input.
        if (provider === "claude" || provider === "cline" || provider === "zed-hosted") {
          forceManual = true;
        }

        // PKCE callback server providers (Codex and Grok Build):
        // On localhost, spin up a local callback server and poll for the result.
        // Each provider owns its registered loopback callback. A LAN IP warns (#8046).
        // On remote the server is unreachable — fall through to standard manual flow.
        if (PKCE_CALLBACK_SERVER_PROVIDERS.has(provider)) {
          if (isTrueLocalhost) {
            try {
              const serverRes = await fetch(`/api/oauth/${provider}/start-callback-server`);
              const serverData = (await parseResponseBody(serverRes)) as Record<string, unknown>;
              if (!serverRes.ok)
                throw new Error(
                  getErrorMessage(serverData, serverRes.status, t("errorCallbackServerFailed"))
                );

              setAuthData({ ...serverData, redirectUri: serverData.redirectUri });
              setStep("waiting");
              popupRef.current = window.open(serverData.authUrl, "oauth_auth");

              // If browser blocked the popup, switch to manual input step immediately
              if (!popupRef.current) {
                setStep("input");
              }

              setPolling(true);
              const maxAttempts = 150;
              for (let i = 0; i < maxAttempts; i++) {
                await new Promise((r) => setTimeout(r, 2000));

                const pollRes = await fetch(`/api/oauth/${provider}/poll-callback`, {
                  method: "POST",
                  headers: { "Content-Type": "application/json" },
                  body: JSON.stringify({ connectionId: reauthConnection?.id }),
                });
                const pollData = (await parseResponseBody(pollRes)) as Record<string, unknown>;

                if (pollData.success) {
                  setStep("success");
                  setPolling(false);
                  onSuccess?.();
                  return;
                }

                if (pollData.error && !pollData.pending) {
                  throw new Error(pollData.errorDescription || pollData.error);
                }
              }

              setPolling(false);
              throw new Error(t("errorAuthorizationTimeout"));
            } catch (pkceErr) {
              console.warn(
                `${provider} callback server failed, falling back to manual flow`,
                pkceErr
              );
              setPolling(false);
              forceManual = true;
            }
          } else if (isLocalhost) {
            setLoopbackHint(buildPkceLoopbackMismatchHint(provider, loopbackLocation));
            setStep("loopback-mismatch");
            return;
          }
          // Remote (non-LAN): fall through to standard auth code flow below
        }

        // Authorization code flow
        // Redirect URI strategy:
        // - Codex/OpenAI: always port 1455 (registered in OAuth app)
        // - Devin Desktop/CLI retain the legacy localhost callback path as a fallback
        // - Google OAuth providers (antigravity/agy): default to loopback so the
        //   bundled native/desktop credentials keep working. Prefer 127.0.0.1 over
        //   localhost for the Google native-app handoff; Google documents that localhost
        //   can run into local firewall/name-resolution edge cases. The authorize route
        //   upgrades this to the public callback when custom Google web credentials plus
        //   NEXT_PUBLIC_BASE_URL or OMNIROUTE_PUBLIC_BASE_URL are configured.
        // - Other providers on remote: use actual origin (supports PUBLIC_URL env var)
        // - Localhost: use localhost:port
        let redirectUri: string;
        if (provider === "codex" || provider === "openai") {
          redirectUri = "http://localhost:1455/auth/callback";
        } else if (provider === "xai-oauth" || provider === "grok-cli") {
          // Fixed native-app loopback callback, distinct ports so both can run concurrently (#7013).
          const grokBuildPort = provider === "xai-oauth" ? 56121 : 56122;
          redirectUri = `http://127.0.0.1:${grokBuildPort}/callback`;
        } else if (provider === "devin-desktop" || provider === "devin-cli") {
          // Retained callback-path fallback for the retired browser flow.
          const port = window.location.port || "20128";
          redirectUri = `http://localhost:${port}/auth/callback`;
        } else if (GOOGLE_OAUTH_PROVIDERS.has(provider)) {
          // Google OAuth built-in credentials only accept loopback redirect URIs.
          // Even in remote deployments we use loopback — user copies the callback URL manually.
          const port = window.location.port || "20128";
          redirectUri = `http://127.0.0.1:${port}/callback`;
        } else if (!isLocalhost) {
          // Behind reverse proxy: use actual origin (e.g., https://omniroute.example.com/callback)
          // Supports PUBLIC_URL env var override, or falls back to window.location.origin.
          const publicUrl = process.env.NEXT_PUBLIC_BASE_URL;
          const origin =
            publicUrl && publicUrl !== "http://localhost:20128"
              ? publicUrl.replace(/\/$/, "")
              : window.location.origin;
          redirectUri = `${origin}/callback`;
        } else {
          const port =
            window.location.port || (window.location.protocol === "https:" ? "443" : "80");
          redirectUri = `http://localhost:${port}/callback`;
        }

        const res = await fetch(
          `/api/oauth/${provider}/authorize?redirect_uri=${encodeURIComponent(redirectUri)}`
        );
        const data = (await parseResponseBody(res)) as Record<string, unknown>;
        if (!res.ok) {
          const errMsg = getErrorMessage(data, res.status, t("errorAuthorizationFailed"));
          throw new Error(errMsg);
        }

        if (!data.authUrl) {
          throw new Error(data.error || t("errorBrowserUnavailable"));
        }

        setAuthData({ ...data, redirectUri: data.redirectUri || redirectUri });

        // For non-true-localhost (LAN IPs, remote) or manual fallback: use manual input mode (user pastes callback URL)
        if (!isTrueLocalhost || forceManual) {
          setStep("input");
          window.open(data.authUrl, "oauth_auth");
        } else {
          // Localhost: Open popup and wait for message
          setStep("waiting");
          popupRef.current = window.open(data.authUrl, "oauth_popup", "width=600,height=700");

          // Check if popup was blocked
          if (!popupRef.current) {
            setStep("input");
          }
        }
      } catch (err) {
        setError(err.message);
        setStep("error");
      }
    },
    [
      provider,
      isLocalhost,
      isTrueLocalhost,
      loopbackLocation,
      startPolling,
      onSuccess,
      reauthConnection,
      idcConfig,
      gheUrl,
      invalidateDeviceFlow,
      grokBrowserMode,
      t,
    ]
  );

  useEffect(() => {
    if (!deviceCodeExpiresAt) {
      setDeviceCodeSecondsRemaining(null);
      return;
    }

    const updateRemaining = () => {
      setDeviceCodeSecondsRemaining(
        Math.max(0, Math.ceil((deviceCodeExpiresAt - Date.now()) / 1000))
      );
    };
    updateRemaining();
    const timer = window.setInterval(updateRemaining, 1000);
    return () => window.clearInterval(timer);
  }, [deviceCodeExpiresAt]);

  useEffect(() => {
    invalidateDeviceFlow();
    flowStartedRef.current = false;
    setGrokBrowserMode(false);
  }, [provider, invalidateDeviceFlow]);

  useEffect(() => {
    if (!isOpen) {
      invalidateDeviceFlow();
      flowStartedRef.current = false;
    }
  }, [isOpen, invalidateDeviceFlow]);

  useEffect(
    () => () => {
      deviceFlowRunRef.current += 1;
    },
    []
  );

  // Reset state and start OAuth when modal opens
  useEffect(() => {
    if (!isOpen || !provider || flowStartedRef.current) return;
    flowStartedRef.current = true;
    const startsInPasteMode = IMPORT_TOKEN_ONLY_PROVIDERS.has(provider);
    // #8688: show GitLab Duo OAuth app / env setup before authorize error.
    const startsInGitlabDuoSetup = provider === "gitlab-duo";
    setShowPasteToken(startsInPasteMode);
    setGrokBrowserMode(false);
    setAuthData(null);
    setCallbackUrl("");
    setError(null);
    setIsDeviceCode(false);
    setDeviceData(null);
    setPolling(false);
    if (startsInGitlabDuoSetup) {
      setStep("gitlab-duo-setup");
      return;
    }
    if (!startsInPasteMode) startOAuthFlow();
  }, [isOpen, provider, startOAuthFlow]);

  // Listen for OAuth callback via multiple methods
  useEffect(() => {
    if (!authData) return;
    callbackProcessedRef.current = false; // Reset when authData changes

    // Handler for callback data - only process once
    const handleCallback = async (data) => {
      if (callbackProcessedRef.current) return; // Already processed

      const { code, state, error: callbackError, errorDescription } = data;

      if (authData?.state && state && state !== authData.state) {
        callbackProcessedRef.current = true;
        setError(t("errorStateMismatch"));
        setStep("error");
        return;
      }

      if (callbackError) {
        callbackProcessedRef.current = true;
        setError(errorDescription || callbackError);
        setStep("error");
        return;
      }

      if (code) {
        callbackProcessedRef.current = true;
        await exchangeTokens(code, state);
      }
    };

    // Method 1: postMessage from popup
    const handleMessage = (event) => {
      // Accept same-origin OR localhost with same port (remote access scenario:
      // dashboard at 192.168.x:port, callback redirects to localhost:port)
      const currentPort = window.location.port;
      let isLoopbackOrigin = false;
      let isLocalhostSamePort = false;
      try {
        const eventUrl = new URL(event.origin);
        isLoopbackOrigin = /^(localhost|127\.0\.0\.1|\[::1\]|::1)$/i.test(eventUrl.hostname);
        isLocalhostSamePort = isLoopbackOrigin && eventUrl.port === currentPort;
      } catch {
        // Ignore malformed origins.
      }

      const payload = event.data?.data;
      const hasMatchingState = !!authData?.state && payload?.state === authData.state;
      const isGoogleLoopbackRelay =
        GOOGLE_OAUTH_PROVIDERS.has(provider) && isLoopbackOrigin && hasMatchingState;

      if (
        event.origin !== window.location.origin &&
        !isLocalhostSamePort &&
        !isGoogleLoopbackRelay
      ) {
        return;
      }
      if (event.data?.type === "oauth_callback") {
        handleCallback(payload);
      }
    };
    window.addEventListener("message", handleMessage);

    // Method 2: BroadcastChannel
    let channel;
    try {
      channel = new BroadcastChannel("oauth_callback");
      channel.onmessage = (event) => handleCallback(event.data);
    } catch (e) {
      console.log("BroadcastChannel not supported");
    }

    // Method 3: localStorage event
    const handleStorage = (event) => {
      if (event.key === "oauth_callback" && event.newValue) {
        try {
          const data = JSON.parse(event.newValue);
          handleCallback(data);
          localStorage.removeItem("oauth_callback");
        } catch (e) {
          console.log("Failed to parse localStorage data");
        }
      }
    };
    window.addEventListener("storage", handleStorage);

    // Also check localStorage on mount (in case callback already happened)
    try {
      const stored = localStorage.getItem("oauth_callback");
      if (stored) {
        const data = JSON.parse(stored);
        // Only use if recent (within 30 seconds)
        if (data.timestamp && Date.now() - data.timestamp < 30000) {
          handleCallback(data);
          localStorage.removeItem("oauth_callback");
        }
      }
    } catch {
      // localStorage may be unavailable or data may be malformed - ignore silently
    }

    return () => {
      window.removeEventListener("message", handleMessage);
      window.removeEventListener("storage", handleStorage);
      if (channel) channel.close();
    };
  }, [authData, exchangeTokens, provider, t]);

  // Fix #344: Detect when OAuth popup is closed without completing authorization
  // Some providers (like Qoder) redirect to their own chat UI instead of sending a callback,
  // leaving the modal stuck at "Waiting for Authorization" forever.
  useEffect(() => {
    if (step !== "waiting" || isDeviceCode || !popupRef.current) return;

    let closed = false;
    const popupClosedInterval = setInterval(() => {
      if (callbackProcessedRef.current) {
        clearInterval(popupClosedInterval);
        return;
      }
      try {
        if (popupRef.current?.closed) {
          closed = true;
          clearInterval(popupClosedInterval);
          // Popup was closed without completing OAuth — switch to manual input mode
          // so user can paste the callback URL from their browser address bar
          if (step === "waiting") {
            setStep("input");
          }
        }
      } catch {
        // Cross-origin access may throw — ignore
      }
    }, 1000);

    // Safety timeout: 5 minutes
    const safetyTimeout = setTimeout(
      () => {
        if (!callbackProcessedRef.current && step === "waiting") {
          clearInterval(popupClosedInterval);
          setStep("input");
        }
      },
      5 * 60 * 1000
    );

    return () => {
      clearInterval(popupClosedInterval);
      clearTimeout(safetyTimeout);
    };
  }, [step, isDeviceCode]);

  // Handle manual URL input
  const handleManualSubmit = async () => {
    try {
      setError(null);
      if (isCredentialBlob(callbackUrl)) {
        await submitCredentialBlob(provider, callbackUrl, reauthConnection, setStep, onSuccess);
        return;
      }

      // Codex: a bare ChatGPT access token (JWT, no refresh token) pasted
      // directly instead of a callback URL/code — mirrors the grok-cli
      // raw-token paste pattern. Routed through the access-token-only import
      // endpoint (#1290) instead of the authorization-code exchange below.
      if (provider === "codex" && /^eyJ/.test(callbackUrl.trim())) {
        await submitCodexAccessToken(
          callbackUrl.trim(),
          undefined,
          setStep,
          onSuccess,
          t("errorImportAccessToken")
        );
        return;
      }

      // Codex: full session JSON from chatgpt.com/api/auth/session
      // (`{user, accessToken, expires}`), not just the bare token (#6636).
      if (provider === "codex" && looksLikeCodexSessionJson(callbackUrl)) {
        const result = parseCodexSessionJson(JSON.parse(callbackUrl.trim()));
        if (result.ok === false) {
          setError(result.error);
          return;
        }
        await submitCodexAccessToken(
          result.session.accessToken,
          result.session.email,
          setStep,
          onSuccess,
          t("errorImportAccessToken")
        );
        return;
      }

      if (!authData) {
        throw new Error(t("errorSessionNotInitialized"));
      }

      const input = callbackUrl.trim();
      let code = null;
      let state = authData?.state || null;
      let errorParam = null;
      let errorDescription = null;

      try {
        const url = new URL(input);
        code = url.searchParams.get("code");
        state = url.searchParams.get("state") || url.hash.replace(/^#/, "") || state;
        errorParam = url.searchParams.get("error");
        errorDescription = url.searchParams.get("error_description");
      } catch {
        // Claude Code remote auth may provide a raw "Authentication Code" like code#state.
        const [rawCode, rawState] = input.split("#", 2);
        code = rawCode || null;
        state = rawState || state;
      }

      if (errorParam) {
        throw new Error(errorDescription || errorParam);
      }

      if (!code) {
        throw new Error(t("errorNoAuthorizationCode"));
      }

      await exchangeTokens(code, state);
    } catch (err) {
      setError(err.message);
      setStep("error");
    }
  };

  const handleClose = useCallback(() => {
    invalidateDeviceFlow();
    onClose();
  }, [invalidateDeviceFlow, onClose]);

  const handlePasteMode = useCallback(() => {
    invalidateDeviceFlow();
    setShowPasteToken(true);
  }, [invalidateDeviceFlow]);

  const handleBrowserMode = useCallback(() => {
    setShowPasteToken(false);
    if (provider === "grok-cli") setGrokBrowserMode(true);
    startOAuthFlow(provider === "grok-cli" ? { grokBrowser: true } : undefined);
  }, [startOAuthFlow, provider]);

  // grok-cli only (#7013 rework): switch back to the device_code method
  // (the default) after the user previously chose Browser Login.
  const handleDeviceCodeMode = useCallback(() => {
    setShowPasteToken(false);
    setGrokBrowserMode(false);
    startOAuthFlow({ grokBrowser: false });
  }, [startOAuthFlow]);

  if (!provider || !providerInfo) return null;

  return (
    <Modal
      isOpen={isOpen}
      title={t("title", { providerName: providerInfo.name })}
      onClose={handleClose}
      size="lg"
    >
      <div className="flex flex-col gap-4">
        {/* Browser login with an optional token-import fallback. grok-cli adds a
            third "Device Code" tab since it keeps BOTH the device_code flow
            (#7358, default) and the browser PKCE login (#7013) alongside the
            paste-token import. */}
        {supportsTokenPaste && !importTokenOnly && step !== "success" && (
          <div className="flex gap-2 border-b border-border pb-3">
            {provider === "grok-cli" && (
              <button
                className={`text-sm px-3 py-1 rounded-t ${!showPasteToken && !grokBrowserMode ? "font-semibold border-b-2 border-primary text-primary" : "text-text-muted"}`}
                onClick={handleDeviceCodeMode}
              >
                {t("tabDeviceCode")}
              </button>
            )}
            <button
              className={`text-sm px-3 py-1 rounded-t ${!showPasteToken && (provider !== "grok-cli" || grokBrowserMode) ? "font-semibold border-b-2 border-primary text-primary" : "text-text-muted"}`}
              onClick={handleBrowserMode}
            >
              {t("tabBrowserLogin")}
            </button>
            <button
              className={`text-sm px-3 py-1 rounded-t ${showPasteToken ? "font-semibold border-b-2 border-primary text-primary" : "text-text-muted"}`}
              onClick={handlePasteMode}
            >
              {provider === "grok-cli" ? t("tabImportAuthJson") : t("tabPasteApiKey")}
            </button>
          </div>
        )}

        {/* Paste-token form (Devin Desktop / Devin CLI) */}
        {supportsTokenPaste && showPasteToken && step !== "success" && (
          <div className="flex flex-col gap-3">
            <p className="text-sm text-text-muted">
              {provider === "devin-desktop"
                ? t("devinDesktopPasteDescription")
                : provider === "grok-cli"
                  ? t("grokAuthJsonDescription")
                  : t("devinPasteDescription")}
            </p>
            {provider === "grok-cli" ? (
              <textarea
                className="w-full h-32 p-3 text-sm font-mono bg-input border border-border rounded-md resize-none focus:outline-none focus:ring-2 focus:ring-primary"
                value={pasteToken}
                onChange={(e) => setPasteToken(e.target.value)}
                placeholder={t("grokAuthJsonPlaceholder")}
                aria-label={t("grokAuthJsonLabel")}
              />
            ) : (
              <Input
                value={pasteToken}
                onChange={(e) => setPasteToken(e.target.value)}
                placeholder={t("apiTokenPlaceholder")}
                type="password"
                label={t("apiKeyTokenLabel")}
              />
            )}
            {error && <p className="text-sm text-red-500">{error}</p>}
            <div className="flex gap-2">
              <Button
                onClick={handleSaveToken}
                fullWidth
                disabled={!pasteToken.trim() || savingToken}
              >
                {savingToken ? t("saving") : t("saveConnection")}
              </Button>
              <Button onClick={handleClose} variant="ghost" fullWidth>
                {t("cancel")}
              </Button>
            </div>
          </div>
        )}

        {/* OAuth flow steps — hidden when paste-token mode is active */}
        {(!supportsTokenPaste || !showPasteToken) && (
          <>
            {/* GHE Copilot: collect the GitHub Enterprise base URL before starting */}
            {provider === "ghe-copilot" && step === "ghe-config" && (
              <GheConfigStep
                gheUrl={gheUrl}
                setGheUrl={setGheUrl}
                error={error}
                setError={setError}
                startOAuthFlow={startOAuthFlow}
              />
            )}

            {provider === "gitlab-duo" && step === "gitlab-duo-setup" && (
              <GitlabDuoSetupStep onContinue={() => void startOAuthFlow()} onClose={handleClose} />
            )}

            {step === "waiting" && !isDeviceCode && (
              <OAuthWaitingStep
                waitingLabel={t("waiting")}
                completeAuthLabel={t("completeAuthInPopup")}
                popupClosedHint={t("popupClosedHint")}
                popupBlockedLabel={t("popupBlocked")}
                onManualInput={() => setStep("input")}
              />
            )}

            {/* Device Code Flow - Waiting */}
            {step === "waiting" && isDeviceCode && deviceData && (
              <OAuthDeviceCodePanel
                deviceData={deviceData}
                verificationUrl={deviceVerificationUrl}
                secondsRemaining={deviceCodeSecondsRemaining}
                polling={polling}
              />
            )}

            {/* Manual Input Step */}
            {step === "input" && !isDeviceCode && (
              <OAuthManualInputPanel
                provider={provider}
                isGoogleOAuth={GOOGLE_OAUTH_PROVIDERS.has(provider)}
                isTrueLocalhost={isTrueLocalhost}
                googleHint={
                  GOOGLE_OAUTH_PROVIDERS.has(provider)
                    ? buildGoogleLoopbackHint(provider, loopbackLocation)
                    : null
                }
                authUrl={typeof authData?.authUrl === "string" ? authData.authUrl : ""}
                callbackUrl={callbackUrl}
                placeholderUrl={placeholderUrl}
                canSubmit={Boolean(callbackUrl && (authData || isCredentialBlob(callbackUrl)))}
                onCallbackUrlChange={setCallbackUrl}
                onSubmit={handleManualSubmit}
                onClose={handleClose}
              />
            )}
          </>
        )}

        {/* Success Step — shown for both OAuth and paste-token flows */}
        {step === "success" && (
          <div className="text-center py-6">
            <div className="size-16 mx-auto mb-4 rounded-full bg-green-100 dark:bg-green-900/30 flex items-center justify-center">
              <span className="material-symbols-outlined text-3xl text-green-600">
                check_circle
              </span>
            </div>
            <h3 className="text-lg font-semibold mb-2">{t("success")}</h3>
            <p className="text-sm text-text-muted mb-4">
              {t("successMessage", { providerName: providerInfo.name })}
            </p>
            <Button onClick={handleClose} fullWidth>
              {t("done")}
            </Button>
          </div>
        )}

        {/* LAN-IP loopback mismatch (#8046) — dedicated panel; retrying this origin cannot succeed. */}
        {step === "loopback-mismatch" && loopbackHint && !showPasteToken && (
          <OAuthLoopbackMismatchPanel
            providerName={providerInfo.name}
            hint={loopbackHint}
            onClose={handleClose}
          />
        )}

        {step === "error" && !showPasteToken && (
          <OAuthErrorStep
            error={error}
            errorTitle={t("error")}
            tryAgainLabel={t("tryAgain")}
            cancelLabel={t("cancel")}
            returnToGitlabDuoSetup={provider === "gitlab-duo"}
            onReturnToGitlabDuoSetup={() => {
              setError(null);
              setStep("gitlab-duo-setup");
            }}
            onTryAgain={() => void startOAuthFlow()}
            onClose={handleClose}
          />
        )}
      </div>
    </Modal>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useTranslations } from "next-intl";
import { Button, Card, Input, Select, Toggle } from "@/shared/components";

type RuleScope = "global" | "apiKey" | "combo" | "model" | "connection";
type TargetKind = "keep" | "model" | "combo";
type EffortMode = "inherit" | "default" | "force";
type BudgetAction = "preserve" | "remove" | "set";

type Rule = {
  id: string;
  name: string;
  description: string;
  scope: RuleScope;
  apiKeyId: string | null;
  comboId: string | null;
  connectionId: string | null;
  modelPattern: string | null;
  sourceEffort: string;
  requestTags: string[];
  tagMatchMode: "any" | "all";
  effortMode: EffortMode;
  targetEffort: string | null;
  targetKind: TargetKind;
  targetModel: string | null;
  targetComboId: string | null;
  budgetAction: BudgetAction;
  budgetTokens: number | null;
  priority: number;
  enabled: boolean;
};

type Reference = { id: string; name: string; provider?: string; displayName?: string };

type FormState = {
  name: string;
  description: string;
  scope: RuleScope;
  apiKeyId: string;
  comboId: string;
  connectionId: string;
  modelPattern: string;
  sourceEffort: string;
  requestTags: string;
  tagMatchMode: "any" | "all";
  effortMode: EffortMode;
  targetEffort: string;
  targetKind: TargetKind;
  targetModel: string;
  targetComboId: string;
  budgetAction: BudgetAction;
  budgetTokens: string;
  priority: string;
  enabled: boolean;
};

const STANDARD_EFFORTS = ["none", "low", "medium", "high", "xhigh"];
const EXTENDED_EFFORTS = ["max", "ultra"];

function emptyRule(apiKeyId?: string): FormState {
  return {
    name: "",
    description: "",
    scope: apiKeyId ? "apiKey" : "global",
    apiKeyId: apiKeyId || "",
    comboId: "",
    connectionId: "",
    modelPattern: "",
    sourceEffort: "any",
    requestTags: "",
    tagMatchMode: "any",
    effortMode: "inherit",
    targetEffort: "medium",
    targetKind: "keep",
    targetModel: "",
    targetComboId: "",
    budgetAction: "preserve",
    budgetTokens: "",
    priority: "0",
    enabled: true,
  };
}

function supportsExtendedCodexEffort(model: string, effort: "max" | "ultra"): boolean {
  const normalized = model
    .trim()
    .toLowerCase()
    .replace(/^(?:codex|cx)\//, "");
  return effort === "ultra"
    ? /^gpt-5\.6-(?:sol|terra)(?:-|$)/.test(normalized)
    : /^gpt-5\.6-(?:sol|terra|luna)(?:-|$)/.test(normalized);
}

export default function ReasoningRoutingRules({ apiKeyId }: { apiKeyId?: string }) {
  const t = useTranslations("reasoningRouting");
  const [rules, setRules] = useState<Rule[]>([]);
  const [combos, setCombos] = useState<Reference[]>([]);
  const [keys, setKeys] = useState<Reference[]>([]);
  const [connections, setConnections] = useState<Reference[]>([]);
  const [form, setForm] = useState<FormState>(() => emptyRule(apiKeyId));
  const [editingId, setEditingId] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [scopeFilter, setScopeFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [search, setSearch] = useState("");
  const [simulator, setSimulator] = useState({
    model: "",
    effort: "missing",
    requestTags: "",
    transport: "http",
  });
  const [simulation, setSimulation] = useState<Record<string, unknown> | null>(null);

  const load = useCallback(async () => {
    const responses = await Promise.all([
      fetch("/api/settings/reasoning-routing-rules"),
      fetch("/api/combos"),
      fetch("/api/keys"),
      fetch("/api/providers"),
    ]);
    if (responses.some((response) => !response.ok)) throw new Error(t("loadError"));
    const [ruleData, comboData, keyData, providerData] = await Promise.all(
      responses.map((response) => response.json())
    );
    setRules(Array.isArray(ruleData.rules) ? ruleData.rules : []);
    setCombos(Array.isArray(comboData.combos) ? comboData.combos : []);
    setKeys(Array.isArray(keyData.keys) ? keyData.keys : []);
    setConnections(Array.isArray(providerData.connections) ? providerData.connections : []);
  }, [t]);

  useEffect(() => {
    load().catch(() => setMessage(t("loadError")));
  }, [load, t]);

  const visibleRules = useMemo(() => {
    const query = search.trim().toLowerCase();
    return rules.filter((rule) => {
      if (apiKeyId && (rule.scope !== "apiKey" || rule.apiKeyId !== apiKeyId)) return false;
      if (!apiKeyId && scopeFilter !== "all" && rule.scope !== scopeFilter) return false;
      if (statusFilter === "enabled" && !rule.enabled) return false;
      if (statusFilter === "disabled" && rule.enabled) return false;
      if (!query) return true;
      return [rule.name, rule.description, rule.modelPattern, ...rule.requestTags]
        .filter(Boolean)
        .some((value) => String(value).toLowerCase().includes(query));
    });
  }, [apiKeyId, rules, scopeFilter, search, statusFilter]);

  const targetModelForCapability =
    form.targetKind === "model" ? form.targetModel : form.modelPattern;
  const effortOptions = useMemo(() => {
    const values = [...STANDARD_EFFORTS];
    for (const effort of EXTENDED_EFFORTS) {
      if (
        supportsExtendedCodexEffort(targetModelForCapability, effort as "max" | "ultra") ||
        form.targetEffort === effort
      ) {
        values.push(effort);
      }
    }
    return values.map((value) => ({ value, label: value }));
  }, [form.targetEffort, targetModelForCapability]);

  const capabilityWarning = useMemo(() => {
    if (form.effortMode === "inherit") return "";
    if (!EXTENDED_EFFORTS.includes(form.targetEffort)) return "";
    if (form.targetKind === "combo") return t("extendedComboWarning");
    if (!targetModelForCapability.trim()) return t("extendedUnknownWarning");
    return supportsExtendedCodexEffort(
      targetModelForCapability,
      form.targetEffort as "max" | "ultra"
    )
      ? ""
      : t("extendedUnsupportedWarning");
  }, [form.effortMode, form.targetEffort, form.targetKind, t, targetModelForCapability]);

  const reset = () => {
    setEditingId(null);
    setForm(emptyRule(apiKeyId));
  };

  const edit = (rule: Rule) => {
    setEditingId(rule.id);
    setForm({
      ...emptyRule(apiKeyId),
      ...rule,
      apiKeyId: rule.apiKeyId || "",
      comboId: rule.comboId || "",
      connectionId: rule.connectionId || "",
      modelPattern: rule.modelPattern || "",
      targetEffort: rule.targetEffort || "medium",
      targetModel: rule.targetModel || "",
      targetComboId: rule.targetComboId || "",
      requestTags: rule.requestTags.join(", "),
      budgetTokens: rule.budgetTokens ? String(rule.budgetTokens) : "",
      priority: String(rule.priority),
    });
  };

  const payload = () => {
    const targetKind: TargetKind = form.scope === "connection" ? "keep" : form.targetKind;
    return {
      ...form,
      apiKeyId: form.scope === "apiKey" ? form.apiKeyId || null : null,
      comboId: form.scope === "combo" ? form.comboId || null : null,
      connectionId: form.scope === "connection" ? form.connectionId || null : null,
      modelPattern:
        form.scope === "model" || form.scope === "apiKey" ? form.modelPattern || null : null,
      requestTags: form.requestTags
        .split(",")
        .map((tag) => tag.trim())
        .filter(Boolean),
      targetEffort: form.effortMode === "inherit" ? null : form.targetEffort,
      targetKind,
      targetModel: targetKind === "model" ? form.targetModel || null : null,
      targetComboId: targetKind === "combo" ? form.targetComboId || null : null,
      budgetTokens: form.budgetAction === "set" ? Number(form.budgetTokens) : null,
      priority: Number(form.priority),
    };
  };

  const save = async () => {
    setSaving(true);
    setMessage("");
    try {
      const response = await fetch(
        editingId
          ? `/api/settings/reasoning-routing-rules/${encodeURIComponent(editingId)}`
          : "/api/settings/reasoning-routing-rules",
        {
          method: editingId ? "PATCH" : "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(payload()),
        }
      );
      if (!response.ok) {
        const result = await response.json().catch(() => null);
        throw new Error(result?.error?.message || result?.error || t("saveError"));
      }
      await load();
      reset();
      setMessage(t("saved"));
    } catch (error) {
      setMessage(error instanceof Error ? error.message : t("saveError"));
    } finally {
      setSaving(false);
    }
  };

  const remove = async (id: string) => {
    if (!window.confirm(t("deleteConfirm"))) return;
    const response = await fetch(
      `/api/settings/reasoning-routing-rules/${encodeURIComponent(id)}`,
      { method: "DELETE" }
    );
    if (response.ok) await load();
    else setMessage(t("deleteError"));
  };

  const toggle = async (rule: Rule) => {
    const response = await fetch(
      `/api/settings/reasoning-routing-rules/${encodeURIComponent(rule.id)}`,
      {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ enabled: !rule.enabled }),
      }
    );
    if (response.ok) await load();
    else setMessage(t("saveError"));
  };

  const simulate = async () => {
    setSimulation(null);
    const response = await fetch("/api/settings/reasoning-routing-rules/simulate", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...simulator,
        apiKeyId: apiKeyId || form.apiKeyId || null,
        requestTags: simulator.requestTags
          .split(",")
          .map((tag) => tag.trim())
          .filter(Boolean),
      }),
    });
    setSimulation(await response.json());
  };

  const scopeOptions = ["global", "apiKey", "combo", "model", "connection"].map((scope) => ({
    value: scope,
    label: t(`scope.${scope}`),
  }));

  return (
    <Card title={apiKeyId ? t("apiKeyTitle") : t("title")} subtitle={t("subtitle")} icon="route">
      <div className="space-y-5">
        <div className="grid gap-3 md:grid-cols-3">
          <Input
            label={t("filterSearch")}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          {!apiKeyId && (
            <Select
              label={t("filterScope")}
              value={scopeFilter}
              onChange={(e) => setScopeFilter(e.target.value)}
              options={[{ value: "all", label: t("all") }, ...scopeOptions]}
            />
          )}
          <Select
            label={t("filterStatus")}
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            options={[
              { value: "all", label: t("all") },
              { value: "enabled", label: t("enabled") },
              { value: "disabled", label: t("disabled") },
            ]}
          />
        </div>

        <div className="space-y-2">
          {visibleRules.length === 0 && <p className="text-sm text-text-muted">{t("empty")}</p>}
          {visibleRules.map((rule) => (
            <div
              key={rule.id}
              className="flex flex-wrap items-center gap-3 rounded-lg border border-border p-3"
            >
              <Toggle
                checked={rule.enabled}
                onChange={() => toggle(rule)}
                size="sm"
                ariaLabel={t("toggleAria", { name: rule.name })}
              />
              <div className="min-w-0 flex-1">
                <p className="font-medium text-text-main">{rule.name}</p>
                <p className="text-xs text-text-muted">
                  {t(`scope.${rule.scope}`)} · {rule.modelPattern || t("allModels")} ·{" "}
                  {rule.sourceEffort} →{" "}
                  {rule.targetKind === "keep"
                    ? t("keepModel")
                    : rule.targetModel || rule.targetComboId}{" "}
                  · {t(`mode.${rule.effortMode}`)}
                  {rule.targetEffort ? ` ${rule.targetEffort}` : ""} ·{" "}
                  {t("priorityShort", { value: rule.priority })}
                </p>
              </div>
              <Button size="sm" variant="ghost" icon="edit" onClick={() => edit(rule)}>
                {t("edit")}
              </Button>
              <Button size="sm" variant="danger" icon="delete" onClick={() => remove(rule.id)}>
                {t("delete")}
              </Button>
            </div>
          ))}
        </div>

        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <Input
            label={t("name")}
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
            required
          />
          <Input
            label={t("description")}
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          {!apiKeyId && (
            <Select
              label={t("scopeLabel")}
              value={form.scope}
              onChange={(e) =>
                setForm({
                  ...form,
                  scope: e.target.value as RuleScope,
                  targetKind: e.target.value === "connection" ? "keep" : form.targetKind,
                })
              }
              options={scopeOptions}
            />
          )}
          {form.scope === "apiKey" && !apiKeyId && (
            <Select
              label={t("apiKey")}
              value={form.apiKeyId}
              onChange={(e) => setForm({ ...form, apiKeyId: e.target.value })}
              options={keys.map((key) => ({ value: key.id, label: key.name }))}
            />
          )}
          {form.scope === "combo" && (
            <Select
              label={t("sourceCombo")}
              value={form.comboId}
              onChange={(e) => setForm({ ...form, comboId: e.target.value })}
              options={combos.map((combo) => ({ value: combo.id, label: combo.name }))}
            />
          )}
          {form.scope === "connection" && (
            <Select
              label={t("connection")}
              value={form.connectionId}
              onChange={(e) => setForm({ ...form, connectionId: e.target.value })}
              options={connections.map((connection) => ({
                value: connection.id,
                label:
                  connection.displayName ||
                  connection.name ||
                  `${connection.provider} · ${connection.id.slice(0, 8)}`,
              }))}
            />
          )}
          {(form.scope === "model" || form.scope === "apiKey") && (
            <Input
              label={t("sourceModel")}
              value={form.modelPattern}
              onChange={(e) => setForm({ ...form, modelPattern: e.target.value })}
              placeholder={
                form.scope === "apiKey" ? t("sourceModelOptional") : t("sourceModelExample")
